window.songs=[{"order":1,"id":"01-prologue-live","title":"Prologue","titleZh":"序幕","lines":[{"id":"phantom-of-the-opera-01-001","lineIndex":1,"speaker":"","original":"Sold!","ipa":"/soʊld/","zh":"成交！","en":"","note":""},{"id":"phantom-of-the-opera-01-002","lineIndex":2,"speaker":"","original":"Your number, sir?","ipa":"/jʊɹ nʌmbɚ sɜ/","zh":"先生，您的号码？","en":"","note":""},{"id":"phantom-of-the-opera-01-003","lineIndex":3,"speaker":"","original":"Thank you.","ipa":"/θæŋk ju/","zh":"谢谢","en":"","note":""},{"id":"phantom-of-the-opera-01-004","lineIndex":4,"speaker":"","original":"Lot 665.","ipa":"/lɑt sɪkshʌndɹɪd sɪksti faɪv/","zh":"第665号拍卖品","en":"","note":""},{"id":"phantom-of-the-opera-01-005","lineIndex":5,"speaker":"","original":"Ladies and gentlemen","ipa":"/leɪdiz ænd dʒɛntəlmən/","zh":"女士们先生们","en":"","note":""},{"id":"phantom-of-the-opera-01-006","lineIndex":6,"speaker":"","original":"A papier-machine musical box in the shape of a barrel organ","ipa":"/ɐ peɪpiɚməʃin mjuzɪkəl bɑks ɪnðə ʃeɪp əvə bæɹəl ɔɹɡən/","zh":"一个手摇风琴造型的纸型八音盒","en":"","note":""},{"id":"phantom-of-the-opera-01-007","lineIndex":7,"speaker":"","original":"Attached, the figure of a monkey in Persian robes playing the cymbals","ipa":"/ɐtætʃt ðə fɪɡjɚɹ əvə mʌŋki ɪn pɜʒən ɹoʊbz pleɪɪŋ ðə sɪmbəlz/","zh":"饰有一座身穿波斯长袍击打铙钹的猴子塑像","en":"","note":""},{"id":"phantom-of-the-opera-01-008","lineIndex":8,"speaker":"","original":"This item","ipa":"/ðɪs aɪɾəm/","zh":"这件拍卖品","en":"","note":""},{"id":"phantom-of-the-opera-01-009","lineIndex":9,"speaker":"","original":"Discovered in the vaults of the theatre","ipa":"/dɪskʌvɚd ɪnðə vɔlts ʌvðə θiəɾɚ/","zh":"发现于本剧院的地窖中","en":"","note":""},{"id":"phantom-of-the-opera-01-010","lineIndex":10,"speaker":"","original":"Still in working order","ipa":"/stɪl ɪn wɜkɪŋ ɔɹdɚ/","zh":"仍可正常演奏","en":"","note":""},{"id":"phantom-of-the-opera-01-011","lineIndex":11,"speaker":"","original":"Showing here","ipa":"/ʃoʊɪŋ hɪɹ/","zh":"下面进行展示","en":"","note":""},{"id":"phantom-of-the-opera-01-012","lineIndex":12,"speaker":"","original":"May I start at twenty Francs?","ipa":"/meɪ aɪ stɑɹt æt twɛnti fɹæŋks/","zh":"可以从20法郎开始吗？","en":"","note":""},{"id":"phantom-of-the-opera-01-013","lineIndex":13,"speaker":"","original":"Fifteen then?","ipa":"/fɪftin ðɛn/","zh":"那，15法郎？","en":"","note":""},{"id":"phantom-of-the-opera-01-014","lineIndex":14,"speaker":"","original":"Fifteen I am bid.","ipa":"/fɪftin aɪɐm bɪd/","zh":"有人出价15法郎","en":"","note":""},{"id":"phantom-of-the-opera-01-015","lineIndex":15,"speaker":"","original":"Twenty, sir, thank you.","ipa":"/twɛnti sɜ θæŋk ju/","zh":"20法郎，先生，谢谢","en":"","note":""},{"id":"phantom-of-the-opera-01-016","lineIndex":16,"speaker":"","original":"Twenty, twenty-five, thank you, madam.","ipa":"/twɛnti twɛntifaɪv θæŋk ju mædəm/","zh":"20法郎，25法郎，谢谢，女士","en":"","note":""},{"id":"phantom-of-the-opera-01-017","lineIndex":17,"speaker":"","original":"Thirty. Selling at thirty then.","ipa":"/θɜɾi sɛlɪŋ æt θɜɾi ðɛn/","zh":"30法郎。现在价格在30法郎。","en":"","note":""},{"id":"phantom-of-the-opera-01-018","lineIndex":18,"speaker":"","original":"Thirty once. Twice.","ipa":"/θɜɾi wʌns twaɪs/","zh":"30法郎一次。两次。","en":"","note":""},{"id":"phantom-of-the-opera-01-019","lineIndex":19,"speaker":"","original":"Sold for thirty Francs!","ipa":"/soʊld fɔɹ θɜɾi fɹæŋks/","zh":"30法郎成交！","en":"","note":""},{"id":"phantom-of-the-opera-01-020","lineIndex":20,"speaker":"","original":"To the Vicomte de Chagny.","ipa":"/tə ðə vɪkɑmt də tʃæɡni/","zh":"夏尼子爵得标","en":"","note":""},{"id":"phantom-of-the-opera-01-021","lineIndex":21,"speaker":"","original":"Thank you, sir.","ipa":"/θæŋk ju sɜ/","zh":"谢谢您，先生","en":"","note":""},{"id":"phantom-of-the-opera-01-022","lineIndex":22,"speaker":"","original":"A collector's piece indeed","ipa":"/ɐ kəlɛktɚz pis ɪndid/","zh":"果然是一件值得收藏的珍品","en":"","note":""},{"id":"phantom-of-the-opera-01-023","lineIndex":23,"speaker":"","original":"Every detail exactly as she said","ipa":"/ɛvɹi diteɪl ɛɡzæktli æz ʃi sɛd/","zh":"每处细节都正如她所说","en":"","note":""},{"id":"phantom-of-the-opera-01-024","lineIndex":24,"speaker":"","original":"She often spoke of you, my friend","ipa":"/ʃi ɔfən spoʊk ʌv ju maɪ fɹɛnd/","zh":"她经常提起你，我的朋友","en":"","note":""},{"id":"phantom-of-the-opera-01-025","lineIndex":25,"speaker":"","original":"Your velvet lining and your figurine of lead","ipa":"/jʊɹ vɛlvɪt laɪnɪŋ ænd jʊɹ fɪɡjʊɹɹin ʌv lid/","zh":"你的天鹅绒内衬和你的铅制塑像","en":"","note":""},{"id":"phantom-of-the-opera-01-026","lineIndex":26,"speaker":"","original":"Will you still play","ipa":"/wɪl ju stɪl pleɪ/","zh":"当我们都离开人世后","en":"","note":""},{"id":"phantom-of-the-opera-01-027","lineIndex":27,"speaker":"","original":"When all the rest of us are dead?","ipa":"/wɛn ɔl ðə ɹɛst ʌv ʌs ɑɹ dɛd/","zh":"你仍会继续演奏吗？","en":"","note":""},{"id":"phantom-of-the-opera-01-028","lineIndex":28,"speaker":"","original":"Lot 666, then","ipa":"/lɑt sɪkshʌndɹɪd sɪksti sɪks ðɛn/","zh":"下面，第666号拍卖品","en":"","note":""},{"id":"phantom-of-the-opera-01-029","lineIndex":29,"speaker":"","original":"A chandelier in pieces.","ipa":"/ɐ ʃændəlɪɹ ɪn pisᵻz/","zh":"破碎的枝形吊灯","en":"","note":""},{"id":"phantom-of-the-opera-01-030","lineIndex":30,"speaker":"","original":"Some of you may recall the strange affair of The Phantom of the Opera","ipa":"/sʌm ʌv ju meɪ ɹᵻkɔl ðə stɹeɪndʒ ɐfɛɹ ʌvðə fæntəm ʌvðɪ ɑpɚɹə/","zh":"也许你们有人还记得当年神秘的剧院魅影事件","en":"","note":""},{"id":"phantom-of-the-opera-01-031","lineIndex":31,"speaker":"","original":"A mystery never fully explained.","ipa":"/ɐ mɪstɚɹi nɛvɚ fʊli ɛkspleɪnd/","zh":"一个未解之谜","en":"","note":""},{"id":"phantom-of-the-opera-01-032","lineIndex":32,"speaker":"","original":"We are told, ladies and gentlemen","ipa":"/wi ɑɹ toʊld leɪdiz ænd dʒɛntəlmən/","zh":"女士们先生们，我们被告知","en":"","note":""},{"id":"phantom-of-the-opera-01-033","lineIndex":33,"speaker":"","original":"That this is the very chandelier which figures in the famous disaster.","ipa":"/ðæt ðɪs ɪz ðə vɛɹi ʃændəlɪɹ wɪtʃ fɪɡjɚz ɪnðə feɪməs dɪzæstɚ/","zh":"这就是现身于当年著名事故的“那盏吊灯”","en":"","note":""},{"id":"phantom-of-the-opera-01-034","lineIndex":34,"speaker":"","original":"Our workshops have restored it","ipa":"/aʊɚ wɜkʃɑps hæv ɹᵻstɔɹd ɪt/","zh":"我们已将它修复","en":"","note":""},{"id":"phantom-of-the-opera-01-035","lineIndex":35,"speaker":"","original":"And fitted up parts of it with wiring for the new electric light","ipa":"/ænd fɪɾᵻd ʌp pɑɹts ʌv ɪt wɪð waɪɚɹɪŋ fɚðə nu ᵻlɛktɹɪk laɪt/","zh":"并加装了电线，配备了新的电灯泡","en":"","note":""},{"id":"phantom-of-the-opera-01-036","lineIndex":36,"speaker":"","original":"So that we may get a hint of what it may look like when reassembled","ipa":"/soʊ ðæt wi meɪ ɡɛt ɐ hɪnt ʌv wʌt ɪt meɪ lʊk laɪk wɛn ɹiɐsɛmbəld/","zh":"从而一瞥它重新组装后的风采","en":"","note":""},{"id":"phantom-of-the-opera-01-037","lineIndex":37,"speaker":"","original":"Perhaps we may frighten away the ghost of so many years ago","ipa":"/pɚhæps wi meɪ fɹaɪʔn̩ ɐweɪ ðə ɡoʊst ʌv soʊ mɛni jɪɹz ɐɡoʊ/","zh":"这一次也许我们能吓走多年前的鬼魅","en":"","note":""},{"id":"phantom-of-the-opera-01-038","lineIndex":38,"speaker":"","original":"With a little illumination, gentlemen!","ipa":"/wɪð ɐ lɪɾəl ɪlumᵻneɪʃən dʒɛntəlmən/","zh":"用一点灯光就行，先生们！","en":"","note":""}],"sourceOrder":1,"displayOrder":1},{"order":2,"id":"02-overture-live","title":"Overture","titleZh":"序曲","lines":[{"id":"phantom-of-the-opera-02-001","lineIndex":1,"speaker":"Carlotta","original":"This trophy from our saviours, from our saviours!","ipa":"/kɑɹlɑɾə ðɪs tɹoʊfi fɹʌm aʊɚ seɪvjɚz fɹʌm aʊɚ seɪvjɚz/","zh":"卡洛塔：这战利品属于我们的救世主，属于我们的救世主！","en":"","note":""},{"id":"phantom-of-the-opera-02-002","lineIndex":2,"speaker":"Carlotta","original":"From the enslaving force of Rome!","ipa":"/kɑɹlɑɾə fɹʌmðɪ ɛnsleɪvɪŋ fɔɹs ʌv ɹoʊm/","zh":"卡洛塔：征服罗马！","en":"","note":""},{"id":"phantom-of-the-opera-02-003","lineIndex":3,"speaker":"Girl's chorus","original":"With feasting and dancing and song / Men's chorus: The trumpets of Carthage resound!","ipa":"/ɡɜlz kɔɹəs wɪð fistɪŋ ænd dænsɪŋ ænd sɔŋ slæʃ mɛnz kɔɹəs ðə tɹʌmpɪts ʌv kɑɹθɪdʒ ɹᵻzaʊnd/","zh":"女声：宴会、跳舞、歌唱","en":"","note":""},{"id":"phantom-of-the-opera-02-004","lineIndex":4,"speaker":"Girl's chorus","original":"Tonight in celebration / Men's chorus: Hear, Romans, now and tremble!","ipa":"/ɡɜlz kɔɹəs tənaɪt ɪn sɛləbɹeɪʃən slæʃ mɛnz kɔɹəs hɪɹ ɹoʊmənz naʊ ænd tɹɛmbəl/","zh":"女声：今晚我们来庆祝","en":"","note":""},{"id":"phantom-of-the-opera-02-005","lineIndex":5,"speaker":"Girl's chorus","original":"We greet the victorious throng, returned to bring salvation! / Men's chorus: Hark to our step on the ground!","ipa":"/ɡɜlz kɔɹəs wi ɡɹit ðə vɪktɔɹiəs θɹɔŋ ɹᵻtɜnd tə bɹɪŋ sælveɪʃən slæʃ mɛnz kɔɹəs hɑɹk tʊ aʊɚ stɛp ɔnðə ɡɹaʊnd/","zh":"女声：我们迎接胜利的队伍，归来拯救我们！","en":"","note":""},{"id":"phantom-of-the-opera-02-006","lineIndex":6,"speaker":"All","original":"Hear the drums --- Hannibal comes!","ipa":"/ɔl hɪɹ ðə dɹʌmz hænɪbəl kʌmz/","zh":"听这鼓声—汉尼拔来了！","en":"","note":""}],"sourceOrder":2,"displayOrder":2},{"order":3,"id":"03-think-of-me-live","title":"Think Of Me","titleZh":"想念我","lines":[{"id":"phantom-of-the-opera-03-001","lineIndex":1,"speaker":"","original":"Think of me","ipa":"/θɪŋk ʌv mi/","zh":"想想我","en":"","note":""},{"id":"phantom-of-the-opera-03-002","lineIndex":2,"speaker":"","original":"think of me fondly","ipa":"/θɪŋk ʌv mi fɑndli/","zh":"深情地想我","en":"","note":""},{"id":"phantom-of-the-opera-03-003","lineIndex":3,"speaker":"","original":"when we've said goodbye.","ipa":"/wɛn wiv sɛd ɡʊdbaɪ/","zh":"当我们已互道再会","en":"","note":""},{"id":"phantom-of-the-opera-03-004","lineIndex":4,"speaker":"","original":"Remember me, once in a while -","ipa":"/ɹᵻmɛmbɚ mi wʌns ɪn ɐ waɪl/","zh":"偶尔记得我","en":"","note":""},{"id":"phantom-of-the-opera-03-005","lineIndex":5,"speaker":"","original":"please promise me you'll try.","ipa":"/pliz pɹɑmɪs mi jul tɹaɪ/","zh":"请答应我你会去尝试","en":"","note":""},{"id":"phantom-of-the-opera-03-006","lineIndex":6,"speaker":"","original":"When you find that once again you long to take your heart back and be free -","ipa":"/wˌɛn juː fˈaɪnd ðæt wˈʌns ɐɡˈɛn juː lˈɔŋ tə tˈeɪk jʊɹ hˈɑːɹt bˈæk ænd biː fɹˈiː/","zh":"当你再次发觉你冀望将心收回...重获自由","en":"","note":""},{"id":"phantom-of-the-opera-03-009","lineIndex":7,"speaker":"","original":"if you ever find a moment","ipa":"/ɪf ju ɛvɚ faɪnd ɐ moʊmənt/","zh":"若你有片刻闲暇","en":"","note":""},{"id":"phantom-of-the-opera-03-010","lineIndex":8,"speaker":"","original":"spare a thought for me...","ipa":"/spɛɹ ɐ θɔt fɔɹ mi/","zh":"分一些思念给我","en":"","note":""},{"id":"phantom-of-the-opera-03-011","lineIndex":9,"speaker":"","original":"We've never said our love was evergreen","ipa":"/wiv nɛvɚ sɛd aʊɚ lʌv wʌz ɛvɚɡɹin/","zh":"未曾说过我们的爱如松柏长青","en":"","note":""},{"id":"phantom-of-the-opera-03-012","lineIndex":10,"speaker":"","original":"or as unchanging as the sea -","ipa":"/ɔɹ æz ʌntʃeɪndʒɪŋ æz ðə si/","zh":"或如沧海般恒久不变","en":"","note":""},{"id":"phantom-of-the-opera-03-013","lineIndex":11,"speaker":"","original":"but if you can still remember","ipa":"/bʌt ɪf ju kæn stɪl ɹᵻmɛmbɚ/","zh":"但若你依稀记得","en":"","note":""},{"id":"phantom-of-the-opera-03-014","lineIndex":12,"speaker":"","original":"stop and think of me...","ipa":"/stɑp ænd θɪŋk ʌv mi/","zh":"驻足片刻，想一想我","en":"","note":""},{"id":"phantom-of-the-opera-03-015","lineIndex":13,"speaker":"","original":"Think of all the things we've shared and seen -","ipa":"/θɪŋk ʌv ɔl ðə θɪŋz wiv ʃɛɹd ænd sin/","zh":"想想所有那些...我们彼此分享目睹的事","en":"","note":""},{"id":"phantom-of-the-opera-03-016","lineIndex":14,"speaker":"","original":"don't think about the things which might have been...","ipa":"/doʊnt θɪŋk ɐbaʊt ðə θɪŋz wɪtʃ maɪthɐv bɪn/","zh":"莫去想事情可能的变化","en":"","note":""},{"id":"phantom-of-the-opera-03-017","lineIndex":15,"speaker":"","original":"Think of me","ipa":"/θɪŋk ʌv mi/","zh":"想想我","en":"","note":""},{"id":"phantom-of-the-opera-03-018","lineIndex":16,"speaker":"","original":"think of me waking","ipa":"/θɪŋk ʌv mi weɪkɪŋ/","zh":"想想醒着的我","en":"","note":""},{"id":"phantom-of-the-opera-03-019","lineIndex":17,"speaker":"","original":"silent and resigned.","ipa":"/saɪlənt ænd ɹɪzaɪnd/","zh":"沉默且温驯","en":"","note":""},{"id":"phantom-of-the-opera-03-020","lineIndex":18,"speaker":"","original":"Imagine me","ipa":"/ɪmædʒɪn mi/","zh":"想像我","en":"","note":""},{"id":"phantom-of-the-opera-03-021","lineIndex":19,"speaker":"","original":"trying too hard to put you from my mind.","ipa":"/tɹaɪɪŋ tu hɑɹd tə pʊt ju fɹʌm maɪ maɪnd/","zh":"极力想将你自心中抹除","en":"","note":""},{"id":"phantom-of-the-opera-03-022","lineIndex":20,"speaker":"","original":"Recall those days","ipa":"/ɹikɔl ðoʊz deɪz/","zh":"回想那些日子","en":"","note":""},{"id":"phantom-of-the-opera-03-023","lineIndex":21,"speaker":"","original":"look back on all those times","ipa":"/lʊk bæk ɔn ɔl ðoʊz taɪmz/","zh":"回顾那些时光","en":"","note":""},{"id":"phantom-of-the-opera-03-024","lineIndex":22,"speaker":"","original":"think of the things we'll never do -","ipa":"/θɪŋk ʌvðə θɪŋz wil nɛvɚ du/","zh":"想想那些我们未曾做过的事","en":"","note":""},{"id":"phantom-of-the-opera-03-025","lineIndex":23,"speaker":"","original":"there will never be a day","ipa":"/ðɛɹ wɪl nɛvɚ bi ɐ deɪ/","zh":"我没有一天","en":"","note":""},{"id":"phantom-of-the-opera-03-026","lineIndex":24,"speaker":"","original":"when I won't think of you...","ipa":"/wɛn aɪ woʊnt θɪŋk ʌv ju/","zh":"不想你","en":"","note":""},{"id":"phantom-of-the-opera-03-027","lineIndex":25,"speaker":"","original":"Can it be?","ipa":"/kæn ɪt bi/","zh":"可能吗？","en":"","note":""},{"id":"phantom-of-the-opera-03-028","lineIndex":26,"speaker":"","original":"Can it be Christine?","ipa":"/kæn ɪt bi kɹɪstin/","zh":"会是克莉丝汀吗？","en":"","note":""},{"id":"phantom-of-the-opera-03-029","lineIndex":27,"speaker":"","original":"Bravo!","ipa":"/bɹɑvoʊ/","zh":"太棒了！","en":"","note":""},{"id":"phantom-of-the-opera-03-030","lineIndex":28,"speaker":"","original":"What a change!","ipa":"/wʌt ɐ tʃeɪndʒ/","zh":"多么大的变化！","en":"","note":""},{"id":"phantom-of-the-opera-03-031","lineIndex":29,"speaker":"","original":"You're really not a bit the gawkish girl that once you were...","ipa":"/jʊɹ ɹiəli nɑɾə bɪt ðə ɡɔkɪʃ ɡɜl ðæt wʌns ju wɜ/","zh":"你再也不是曾经那个笨拙的女孩了","en":"","note":""},{"id":"phantom-of-the-opera-03-032","lineIndex":30,"speaker":"","original":"She may not remember me","ipa":"/ʃi meɪ nɑt ɹᵻmɛmbɚ mi/","zh":"她或许不记得我","en":"","note":""},{"id":"phantom-of-the-opera-03-033","lineIndex":31,"speaker":"","original":"but I remember her...","ipa":"/bʌt aɪ ɹᵻmɛmbɚ hɜ/","zh":"但我记得她","en":"","note":""},{"id":"phantom-of-the-opera-03-034","lineIndex":32,"speaker":"","original":"We've never said our love was evergreen","ipa":"/wiv nɛvɚ sɛd aʊɚ lʌv wʌz ɛvɚɡɹin/","zh":"未曾说过我们的爱如松柏常青","en":"","note":""},{"id":"phantom-of-the-opera-03-035","lineIndex":33,"speaker":"","original":"or as unchanging as the sea -","ipa":"/ɔɹ æz ʌntʃeɪndʒɪŋ æz ðə si/","zh":"或如沧海般恒永不变","en":"","note":""},{"id":"phantom-of-the-opera-03-036","lineIndex":34,"speaker":"","original":"but please promise me that sometimes you will think oooooo~f me!","ipa":"/bˌʌt plˈiːz pɹˈɑːmɪs mˌiː ðæt sˈʌmtaɪmz juː wɪl θˈɪŋk ˈuːuːˌuː tˈɪldə ˈɛf mˌiː/","zh":"但请答应我偶尔...你会想想...我！","en":"","note":""}],"sourceOrder":3,"displayOrder":3},{"order":4,"id":"04-angel-of-music-live","title":"Angel Of Music","titleZh":"音乐天使","lines":[{"id":"phantom-of-the-opera-04-001","lineIndex":1,"speaker":"Meg","original":"Where in the world have you been hiding?","ipa":"/mɛɡ koʊlən wɛɹ ɪnðə wɜld hæv ju bɪn haɪdɪŋ/","zh":"你究竟一直藏匿何处","en":"","note":""},{"id":"phantom-of-the-opera-04-002","lineIndex":2,"speaker":"","original":"Really you were perfect.","ipa":"/ɹiəli ju wɜ pɜfɛkt/","zh":"你真是完美无瑕","en":"","note":""},{"id":"phantom-of-the-opera-04-003","lineIndex":3,"speaker":"","original":"I only wish I knew your secret","ipa":"/aɪ oʊnli wɪʃ aɪ nu jʊɹ sikɹᵻt/","zh":"但愿我能知道你的秘密","en":"","note":""},{"id":"phantom-of-the-opera-04-004","lineIndex":4,"speaker":"","original":"Who is this new tutor?","ipa":"/hu ɪz ðɪs nu tuɾɚ/","zh":"谁是你的良师？","en":"","note":""},{"id":"phantom-of-the-opera-04-005","lineIndex":5,"speaker":"Christine","original":"Father once spoke of an angel","ipa":"/kɹɪstin koʊlən fɑðɚ wʌns spoʊk əvən eɪndʒəl/","zh":"父亲曾提及一位天使","en":"","note":""},{"id":"phantom-of-the-opera-04-006","lineIndex":6,"speaker":"","original":"I used to dream he'd appear","ipa":"/aɪ juzd tə dɹim hid ɐpɪɹ/","zh":"我时常梦想他会出现","en":"","note":""},{"id":"phantom-of-the-opera-04-007","lineIndex":7,"speaker":"","original":"Now as I sing I can sense him","ipa":"/naʊ æz aɪ sɪŋ aɪ kæn sɛns hɪm/","zh":"如今当我唱歌时，我能感受到他的存在","en":"","note":""},{"id":"phantom-of-the-opera-04-008","lineIndex":8,"speaker":"","original":"And I know he's here.","ipa":"/ænd aɪ noʊ hiz hɪɹ/","zh":"我知道他就在此地","en":"","note":""},{"id":"phantom-of-the-opera-04-009","lineIndex":9,"speaker":"","original":"Here in this room he calls me softly","ipa":"/hɪɹ ɪn ðɪs ɹum hi kɔlz mi sɔftli/","zh":"就在这房间里，他轻柔地呼唤我","en":"","note":""},{"id":"phantom-of-the-opera-04-010","lineIndex":10,"speaker":"","original":"Somewhere inside...hiding.","ipa":"/sʌmwɛɹ ɪnsaɪd haɪdɪŋ/","zh":"躲藏在房内某处","en":"","note":""},{"id":"phantom-of-the-opera-04-011","lineIndex":11,"speaker":"","original":"Somehow I know, he's always with me","ipa":"/sʌmhaʊ aɪ noʊ hiz ɔlweɪz wɪð mi/","zh":"不知怎么地，我知道他一直在我身边","en":"","note":""},{"id":"phantom-of-the-opera-04-012","lineIndex":12,"speaker":"","original":"he's the unseen genius.","ipa":"/hiz ðɪ ʌnsin dʒinɪəs/","zh":"他是看不见的守护神","en":"","note":""},{"id":"phantom-of-the-opera-04-013","lineIndex":13,"speaker":"Meg","original":"Christine you must have been dreaming","ipa":"/mɛɡ koʊlən kɹɪstin ju mʌstɐv bɪn dɹimɪŋ/","zh":"克莉丝汀，你一定是在作梦","en":"","note":""},{"id":"phantom-of-the-opera-04-014","lineIndex":14,"speaker":"","original":"Stories like this can't come true","ipa":"/stɔɹiz laɪk ðɪs kænt kʌm tɹu/","zh":"这种故事不会成真的","en":"","note":""},{"id":"phantom-of-the-opera-04-015","lineIndex":15,"speaker":"","original":"Christine you're talking in riddles","ipa":"/kɹɪstin jʊɹ tɔkɪŋ ɪn ɹɪdəlz/","zh":"克莉丝汀，你的话语令人费解","en":"","note":""},{"id":"phantom-of-the-opera-04-016","lineIndex":16,"speaker":"","original":"And it's not like you!","ipa":"/ænd ɪts nɑt laɪk ju/","zh":"这样并不像你","en":"","note":""},{"id":"phantom-of-the-opera-04-017","lineIndex":17,"speaker":"Christine","original":"Angel of music","ipa":"/kɹɪstin koʊlən eɪndʒəl ʌv mjuzɪk/","zh":"音乐天使","en":"","note":""},{"id":"phantom-of-the-opera-04-018","lineIndex":18,"speaker":"","original":"Guide and Guardian","ipa":"/ɡaɪd ænd ɡɑɹdiən/","zh":"指引我、守护我","en":"","note":""},{"id":"phantom-of-the-opera-04-019","lineIndex":19,"speaker":"","original":"Grant to me your glory!","ipa":"/ɡɹænt tə mi jʊɹ ɡlɔɹi/","zh":"赐与我汝之荣耀","en":"","note":""},{"id":"phantom-of-the-opera-04-020","lineIndex":20,"speaker":"Meg","original":"Who is this Angel?","ipa":"/mɛɡ koʊlən hu ɪz ðɪs eɪndʒəl/","zh":"这个天使是谁？","en":"","note":""},{"id":"phantom-of-the-opera-04-021","lineIndex":21,"speaker":"","original":"This...","ipa":"/ðɪs/","zh":"这个...","en":"","note":""},{"id":"phantom-of-the-opera-04-022","lineIndex":22,"speaker":"Both","original":"Angel of music, Hide no longer","ipa":"/boʊθ koʊlən eɪndʒəl ʌv mjuzɪk haɪd noʊ lɑŋɡɚ/","zh":"音乐天使，莫再躲藏","en":"","note":""},{"id":"phantom-of-the-opera-04-023","lineIndex":23,"speaker":"","original":"secret and strange angel","ipa":"/sikɹᵻt ænd stɹeɪndʒ eɪndʒəl/","zh":"秘密且陌生的天使","en":"","note":""},{"id":"phantom-of-the-opera-04-024","lineIndex":24,"speaker":"Christine","original":"He's with me even now","ipa":"/kɹɪstin koʊlən hiz wɪð mi ivən naʊ/","zh":"即使现在，他也在我身边","en":"","note":""},{"id":"phantom-of-the-opera-04-025","lineIndex":25,"speaker":"Meg","original":"Your hands are cold","ipa":"/mɛɡ koʊlən jʊɹ hændz ɑɹ koʊld/","zh":"你的双手冰冷","en":"","note":""},{"id":"phantom-of-the-opera-04-026","lineIndex":26,"speaker":"Christine","original":"All around me","ipa":"/kɹɪstin koʊlən ɔl ɚɹaʊnd mi/","zh":"围绕在我四周","en":"","note":""},{"id":"phantom-of-the-opera-04-027","lineIndex":27,"speaker":"Meg","original":"Your face, Christine, it's white","ipa":"/mɛɡ koʊlən jʊɹ feɪs kɹɪstin ɪts waɪt/","zh":"克莉丝汀，你的脸色苍白","en":"","note":""},{"id":"phantom-of-the-opera-04-028","lineIndex":28,"speaker":"Christine","original":"It frightens me","ipa":"/kɹɪstin koʊlən ɪt fɹaɪʔn̩z mi/","zh":"令我惧怕","en":"","note":""},{"id":"phantom-of-the-opera-04-029","lineIndex":29,"speaker":"Meg","original":"Don't be frightened","ipa":"/mɛɡ koʊlən doʊnt bi fɹaɪʔn̩d/","zh":"无需惧怕","en":"","note":""}],"sourceOrder":4,"displayOrder":4},{"order":5,"id":"05-the-phantom-of-the-opera-live","title":"The Phantom Of The Opera","titleZh":"剧院魅影","lines":[{"id":"phantom-of-the-opera-05-001","lineIndex":1,"speaker":"","original":"In sleep he sang to me","ipa":"/ɪn slip hi sæŋ tə mi/","zh":"梦中他为我献唱","en":"","note":""},{"id":"phantom-of-the-opera-05-002","lineIndex":2,"speaker":"","original":"In dreams he came","ipa":"/ɪn dɹimz hi keɪm/","zh":"在梦中他迎面而来","en":"","note":""},{"id":"phantom-of-the-opera-05-003","lineIndex":3,"speaker":"","original":"That voice which calls to me","ipa":"/ðæt vɔɪs wɪtʃ kɔlz tə mi/","zh":"那呼唤着我的声音","en":"","note":""},{"id":"phantom-of-the-opera-05-004","lineIndex":4,"speaker":"","original":"And speaks my name","ipa":"/ænd spiks maɪ neɪm/","zh":"叫着我的名字","en":"","note":""},{"id":"phantom-of-the-opera-05-005","lineIndex":5,"speaker":"","original":"And do I dream again","ipa":"/ænd du aɪ dɹim ɐɡɛn/","zh":"这是否又是一个梦","en":"","note":""},{"id":"phantom-of-the-opera-05-006","lineIndex":6,"speaker":"","original":"For now I find","ipa":"/fɔɹ naʊ aɪ faɪnd/","zh":"现在我发现","en":"","note":""},{"id":"phantom-of-the-opera-05-007","lineIndex":7,"speaker":"","original":"The phantom of the opera is there","ipa":"/ðə fæntəm ʌvðɪ ɑpɚɹə ɪz ðɛɹ/","zh":"这剧院魅影就在那","en":"","note":""},{"id":"phantom-of-the-opera-05-008","lineIndex":8,"speaker":"","original":"Inside my mind","ipa":"/ɪnsaɪd maɪ maɪnd/","zh":"我脑海的深处","en":"","note":""},{"id":"phantom-of-the-opera-05-009","lineIndex":9,"speaker":"","original":"Sing once again with me","ipa":"/sɪŋ wʌns ɐɡɛn wɪð mi/","zh":"再次与我合唱","en":"","note":""},{"id":"phantom-of-the-opera-05-010","lineIndex":10,"speaker":"","original":"Our strange duet","ipa":"/aʊɚ stɹeɪndʒ djuɛt/","zh":"我们奇妙的二重唱","en":"","note":""},{"id":"phantom-of-the-opera-05-011","lineIndex":11,"speaker":"","original":"My power over you","ipa":"/maɪ paʊɚɹ oʊvɚ ju/","zh":"我掌控你的力量","en":"","note":""},{"id":"phantom-of-the-opera-05-012","lineIndex":12,"speaker":"","original":"Grows stronger yet","ipa":"/ɡɹoʊz stɹɔŋɡɚ jɛt/","zh":"日益壮大","en":"","note":""},{"id":"phantom-of-the-opera-05-013","lineIndex":13,"speaker":"","original":"And though you turn from me","ipa":"/ænd ðoʊ ju tɜn fɹʌm mi/","zh":"纵然你离我而去","en":"","note":""},{"id":"phantom-of-the-opera-05-014","lineIndex":14,"speaker":"","original":"To glance behind","ipa":"/tə ɡlæns bᵻhaɪnd/","zh":"只要回首","en":"","note":""},{"id":"phantom-of-the-opera-05-015","lineIndex":15,"speaker":"","original":"The phantom of the opera is there","ipa":"/ðə fæntəm ʌvðɪ ɑpɚɹə ɪz ðɛɹ/","zh":"那剧院魅影就在那","en":"","note":""},{"id":"phantom-of-the-opera-05-016","lineIndex":16,"speaker":"","original":"Inside your mind","ipa":"/ɪnsaɪd jʊɹ maɪnd/","zh":"在你心中","en":"","note":""},{"id":"phantom-of-the-opera-05-017","lineIndex":17,"speaker":"","original":"Those who have seen your face","ipa":"/ðoʊz hu hæv sin jʊɹ feɪs/","zh":"凡见过你面容之人","en":"","note":""},{"id":"phantom-of-the-opera-05-018","lineIndex":18,"speaker":"","original":"Draw back in fear","ipa":"/dɹɔ bæk ɪn fɪɹ/","zh":"蜷缩于恐惧之中","en":"","note":""},{"id":"phantom-of-the-opera-05-019","lineIndex":19,"speaker":"","original":"I am the mask you wear","ipa":"/aɪɐm ðə mæsk ju wɛɹ/","zh":"我便是你所戴的面具","en":"","note":""},{"id":"phantom-of-the-opera-05-020","lineIndex":20,"speaker":"","original":"It's me they hear","ipa":"/ɪts mi ðeɪ hɪɹ/","zh":"它们听见的是我","en":"","note":""},{"id":"phantom-of-the-opera-05-021","lineIndex":21,"speaker":"","original":"My spirit and your voice in one combined","ipa":"/maɪ spɪɹɪt ænd jʊɹ vɔɪs ɪn wʌn kəmbaɪnd/","zh":"你/我的灵魂和我/你的歌声已融为一体","en":"","note":""},{"id":"phantom-of-the-opera-05-022","lineIndex":22,"speaker":"","original":"The phantom of the opera is there","ipa":"/ðə fæntəm ʌvðɪ ɑpɚɹə ɪz ðɛɹ/","zh":"这剧院魅影就在那","en":"","note":""},{"id":"phantom-of-the-opera-05-023","lineIndex":23,"speaker":"","original":"Inside your mind","ipa":"/ɪnsaɪd jʊɹ maɪnd/","zh":"你脑海的深处","en":"","note":""},{"id":"phantom-of-the-opera-05-024","lineIndex":24,"speaker":"","original":"In all your fantasy","ipa":"/ɪn ɔl jʊɹ fæntəsi/","zh":"在你所有的幻想中","en":"","note":""},{"id":"phantom-of-the-opera-05-025","lineIndex":25,"speaker":"","original":"You always knew","ipa":"/ju ɔlweɪz nu/","zh":"你一直明了","en":"","note":""},{"id":"phantom-of-the-opera-05-026","lineIndex":26,"speaker":"","original":"That man and mystery","ipa":"/ðæt mæn ænd mɪstɚɹi/","zh":"那男人和神祕之事","en":"","note":""},{"id":"phantom-of-the-opera-05-027","lineIndex":27,"speaker":"","original":"Were both in you","ipa":"/wɜ boʊθ ɪn ju/","zh":"都在你身上","en":"","note":""},{"id":"phantom-of-the-opera-05-028","lineIndex":28,"speaker":"","original":"And in this labyrinth","ipa":"/ænd ɪn ðɪs læbɚɹɪnθ/","zh":"而在这","en":"","note":""},{"id":"phantom-of-the-opera-05-029","lineIndex":29,"speaker":"","original":"Where night is blind","ipa":"/wɛɹ naɪt ɪz blaɪnd/","zh":"夜晚漆黑的迷宫里","en":"","note":""},{"id":"phantom-of-the-opera-05-030","lineIndex":30,"speaker":"","original":"The phantom of the opera is","ipa":"/ðə fæntəm ʌvðɪ ɑpɚɹə ɪz/","zh":"剧院魅影就在","en":"","note":""},{"id":"phantom-of-the-opera-05-031","lineIndex":31,"speaker":"","original":"There","ipa":"/ðɛɹ/","zh":"这里","en":"","note":""},{"id":"phantom-of-the-opera-05-032","lineIndex":32,"speaker":"","original":"Inside my mind","ipa":"/ɪnsaɪd maɪ maɪnd/","zh":"我脑海深处","en":"","note":""},{"id":"phantom-of-the-opera-05-033","lineIndex":33,"speaker":"","original":"Sing! My angel of music","ipa":"/sɪŋ maɪ eɪndʒəl ʌv mjuzɪk/","zh":"唱吧！我的音乐天使！","en":"","note":""},{"id":"phantom-of-the-opera-05-034","lineIndex":34,"speaker":"","original":"He's there","ipa":"/hiz ðɛɹ/","zh":"他在那","en":"","note":""},{"id":"phantom-of-the-opera-05-035","lineIndex":35,"speaker":"","original":"The Phantom of the Opera","ipa":"/ðə fˈæntəm ʌvðɪ ˈɑːpɚɹə/","zh":"剧院魅影","en":"","note":""},{"id":"phantom-of-the-opera-05-037","lineIndex":36,"speaker":"","original":"Sing...","ipa":"/sɪŋ/","zh":"唱吧……","en":"","note":""},{"id":"phantom-of-the-opera-05-038","lineIndex":37,"speaker":"","original":"Sing for me...","ipa":"/sɪŋ fɔɹ mi/","zh":"为我而唱吧……","en":"","note":""},{"id":"phantom-of-the-opera-05-039","lineIndex":38,"speaker":"","original":"Sing' my angel of music!","ipa":"/sɪŋ maɪ eɪndʒəl ʌv mjuzɪk/","zh":"唱吧！我的音乐天使！","en":"","note":""},{"id":"phantom-of-the-opera-05-040","lineIndex":39,"speaker":"","original":"Sing for me!","ipa":"/sɪŋ fɔɹ mi/","zh":"为我而唱吧！","en":"","note":""}],"sourceOrder":5,"displayOrder":5},{"order":6,"id":"06-the-music-of-the-night-live","title":"The Music Of The Night","titleZh":"夜之乐章","lines":[{"id":"phantom-of-the-opera-06-001","lineIndex":1,"speaker":"","original":"Night time sharpens heightens each sensation","ipa":"/naɪt taɪm ʃɑɹpənz haɪʔn̩z itʃ sɛnseɪʃən/","zh":"夜晚让各种感觉更加敏锐强烈","en":"","note":""},{"id":"phantom-of-the-opera-06-002","lineIndex":2,"speaker":"","original":"Darkness stirs and wakes imagination","ipa":"/dɑɹknəs stɜz ænd weɪks ɪmædʒᵻneɪʃən/","zh":"黑暗骚动唤醒了无限想像","en":"","note":""},{"id":"phantom-of-the-opera-06-003","lineIndex":3,"speaker":"","original":"Silently the senses abandon their defences","ipa":"/saɪləntli ðə sɛnsᵻz ɐbændən ðɛɹ dᵻfɛnsᵻz/","zh":"感官静静地卸下了武装","en":"","note":""},{"id":"phantom-of-the-opera-06-004","lineIndex":4,"speaker":"","original":"Slowly, gently, night unfurls its splendour","ipa":"/sloʊli dʒɛntli naɪt ʌnfɜlz ɪts splɛndɚ/","zh":"缓缓地，轻柔地，黑夜展露它的华丽","en":"","note":""},{"id":"phantom-of-the-opera-06-005","lineIndex":5,"speaker":"","original":"Grasp it, sense it, tremulous and tender","ipa":"/ɡɹæsp ɪt sɛns ɪt tɹɛmjʊləs ænd tɛndɚ/","zh":"紧握它，感受它，战战兢兢地","en":"","note":""},{"id":"phantom-of-the-opera-06-006","lineIndex":6,"speaker":"","original":"Turn your face away from the garish light of day","ipa":"/tɜn jʊɹ feɪs ɐweɪ fɹʌmðə ɡɛɹɪʃ laɪt ʌv deɪ/","zh":"将你的脸庞移离白昼的灿烂光芒","en":"","note":""},{"id":"phantom-of-the-opera-06-007","lineIndex":7,"speaker":"","original":"Turn your thoughts away from cold, unfeeling light","ipa":"/tɜn jʊɹ θɔts ɐweɪ fɹʌm koʊld ʌnfilɪŋ laɪt/","zh":"将你的思绪远离冷漠无情的光芒","en":"","note":""},{"id":"phantom-of-the-opera-06-008","lineIndex":8,"speaker":"","original":"And listen to the music of the night","ipa":"/ænd lɪsən tə ðə mjuzɪk ʌvðə naɪt/","zh":"聆听夜之音乐","en":"","note":""},{"id":"phantom-of-the-opera-06-009","lineIndex":9,"speaker":"","original":"Close your eyes and Surrender to your darkest dreams!","ipa":"/kloʊs jʊɹ aɪz ænd sɚɹɛndɚ tə jʊɹ dɑɹkɪst dɹimz/","zh":"闭上双眼，臣服于你最深沉的梦中","en":"","note":""},{"id":"phantom-of-the-opera-06-010","lineIndex":10,"speaker":"","original":"Purge all thoughts of the life you knew before!","ipa":"/pɜdʒ ɔl θɔts ʌvðə laɪf ju nu bᵻfɔɹ/","zh":"涤净你过往生活的思绪","en":"","note":""},{"id":"phantom-of-the-opera-06-011","lineIndex":11,"speaker":"","original":"Close your eyes let your spirit start to soar","ipa":"/kloʊs jʊɹ aɪz lɛt jʊɹ spɪɹɪt stɑɹt tə sɔɹ/","zh":"闭上双眼，让灵魂驰骋翱翔","en":"","note":""},{"id":"phantom-of-the-opera-06-012","lineIndex":12,"speaker":"","original":"And you live as you've never lived before","ipa":"/ænd ju lɪv æz juv nɛvɚ lɪvd bᵻfɔɹ/","zh":"你将宛如重获新生一般","en":"","note":""},{"id":"phantom-of-the-opera-06-013","lineIndex":13,"speaker":"","original":"Softly, deftly, music shall surround you","ipa":"/sɔftli dɛftli mjuzɪk ʃæl sɚɹaʊnd ju/","zh":"轻柔灵巧地，音乐将抚慰你","en":"","note":""},{"id":"phantom-of-the-opera-06-014","lineIndex":14,"speaker":"","original":"feel it, heal it, secretly possess you","ipa":"/fil ɪt hil ɪt sikɹᵻtli pəzɛs ju/","zh":"倾听它、体会它，悄悄地占有你","en":"","note":""},{"id":"phantom-of-the-opera-06-015","lineIndex":15,"speaker":"","original":"Open up your mind let your fantasies unwind","ipa":"/oʊpən ʌp jʊɹ maɪnd lɛt jʊɹ fæntəsiz ʌnwaɪnd/","zh":"敞开心扉，让你的幻想天马行空","en":"","note":""},{"id":"phantom-of-the-opera-06-016","lineIndex":16,"speaker":"","original":"In this darkness which you know you cannot fight","ipa":"/ɪn ðɪs dɑɹknəs wɪtʃ ju noʊ ju kænɑt faɪt/","zh":"在你熟悉的黑暗中，你无法抗拒","en":"","note":""},{"id":"phantom-of-the-opera-06-017","lineIndex":17,"speaker":"","original":"The darkness of the music of the night","ipa":"/ðə dɑɹknəs ʌvðə mjuzɪk ʌvðə naɪt/","zh":"夜之乐章的黑暗","en":"","note":""},{"id":"phantom-of-the-opera-06-018","lineIndex":18,"speaker":"","original":"Let your mind start a journey through a strange new world","ipa":"/lɛt jʊɹ maɪnd stɑɹt ɐ dʒɜni θɹut ɐ stɹeɪndʒ nu wɜld/","zh":"让你的心灵开启奇异新世界之旅","en":"","note":""},{"id":"phantom-of-the-opera-06-019","lineIndex":19,"speaker":"","original":"Purge all thoughts of the world you knew before","ipa":"/pɜdʒ ɔl θɔts ʌvðə wɜld ju nu bᵻfɔɹ/","zh":"抛开你过往生活的所有思绪","en":"","note":""},{"id":"phantom-of-the-opera-06-020","lineIndex":20,"speaker":"","original":"Let your soul take you where you long to be","ipa":"/lɛt jʊɹ soʊl teɪk ju wɛɹ ju lɔŋ tə bi/","zh":"让你的灵魂带你奔向你所渴望之地","en":"","note":""},{"id":"phantom-of-the-opera-06-021","lineIndex":21,"speaker":"","original":"Only then can you belong to me","ipa":"/oʊnli ðɛn kæn ju bᵻlɔŋ tə mi/","zh":"唯有那时你才能属于我","en":"","note":""},{"id":"phantom-of-the-opera-06-022","lineIndex":22,"speaker":"","original":"Floating, falling, sweet intoxication","ipa":"/floʊɾɪŋ fɔlɪŋ swit ɪntɑksɪkeɪʃən/","zh":"时起时落，心醉神迷","en":"","note":""},{"id":"phantom-of-the-opera-06-023","lineIndex":23,"speaker":"","original":"Touch me, trust me, savour each sensation","ipa":"/tʌtʃ mi tɹʌst mi seɪvɚɹ itʃ sɛnseɪʃən/","zh":"触摸我、信赖我、品尝每种情感","en":"","note":""},{"id":"phantom-of-the-opera-06-024","lineIndex":24,"speaker":"","original":"Let the dream begin","ipa":"/lɛt ðə dɹim bɪɡɪn/","zh":"让梦再度开启","en":"","note":""},{"id":"phantom-of-the-opera-06-025","lineIndex":25,"speaker":"","original":"Let your darker side give in","ipa":"/lɛt jʊɹ dɑɹkɚ saɪd ɡɪv ɪn/","zh":"让你的阴暗面臣服","en":"","note":""},{"id":"phantom-of-the-opera-06-026","lineIndex":26,"speaker":"","original":"To the power of the music that I write","ipa":"/tə ðə paʊɚɹ ʌvðə mjuzɪk ðæt aɪ ɹaɪt/","zh":"在我所谱写的音乐力量之下","en":"","note":""},{"id":"phantom-of-the-opera-06-027","lineIndex":27,"speaker":"","original":"The power of the music of the night","ipa":"/ðə paʊɚɹ ʌvðə mjuzɪk ʌvðə naɪt/","zh":"夜之乐章的力量","en":"","note":""},{"id":"phantom-of-the-opera-06-028","lineIndex":28,"speaker":"","original":"You alone can make my song take flight","ipa":"/ju ɐloʊn kæn meɪk maɪ sɔŋ teɪk flaɪt/","zh":"唯有你能令我的歌声飞扬","en":"","note":""},{"id":"phantom-of-the-opera-06-029","lineIndex":29,"speaker":"","original":"Help me make the music of the night","ipa":"/hɛlp mi meɪk ðə mjuzɪk ʌvðə naɪt/","zh":"助我共谱夜之乐章","en":"","note":""}],"sourceOrder":6,"displayOrder":6},{"order":7,"id":"07-i-remember-stranger-than-you-dream-it-live","title":"I Remember.../Stranger Than You Dream It...","titleZh":"我记得……／比你梦中更陌生……","lines":[{"id":"phantom-of-the-opera-07-001","lineIndex":1,"speaker":"","original":"I remember there was a mist","ipa":"/aɪ ɹᵻmɛmbɚ ðɛɹwʌz ɐ mɪst/","zh":"我记得在睡梦中迷雾重重","en":"","note":""},{"id":"phantom-of-the-opera-07-002","lineIndex":2,"speaker":"","original":"Swirling mist up upon a vast glassy lake","ipa":"/swaɪɚɹɪŋ mɪst ʌp əpɑn ɐ væst ɡlæsi leɪk/","zh":"烟雾缭绕 湖水清如明镜","en":"","note":""},{"id":"phantom-of-the-opera-07-003","lineIndex":3,"speaker":"","original":"There were candles all around","ipa":"/ðɛɹwɜ kændəlz ɔl ɚɹaʊnd/","zh":"周围烛光倒影坏绕","en":"","note":""},{"id":"phantom-of-the-opera-07-004","lineIndex":4,"speaker":"","original":"And on the lake there was a boat","ipa":"/ænd ɔnðə leɪk ðɛɹwʌz ɐ boʊt/","zh":"在湖中央飘着一艘船","en":"","note":""},{"id":"phantom-of-the-opera-07-005","lineIndex":5,"speaker":"","original":"And in the boat there was a man","ipa":"/ænd ɪnðə boʊt ðɛɹwʌz ɐ mæn/","zh":"有一人孤立船中","en":"","note":""},{"id":"phantom-of-the-opera-07-006","lineIndex":6,"speaker":"","original":"Who is in the shape in the shadows?","ipa":"/hu ɪz ɪnðə ʃeɪp ɪnðə ʃædoʊz/","zh":"在树荫下隐藏的是谁","en":"","note":""},{"id":"phantom-of-the-opera-07-007","lineIndex":7,"speaker":"","original":"Who is the face in the mask?","ipa":"/hu ɪz ðə feɪs ɪnðə mæsk/","zh":"在面具下的又是何人","en":"","note":""},{"id":"phantom-of-the-opera-07-008","lineIndex":8,"speaker":"","original":"Damn you!","ipa":"/dæm ju/","zh":"真是该死","en":"","note":""},{"id":"phantom-of-the-opera-07-009","lineIndex":9,"speaker":"","original":"You little prying Pandora","ipa":"/ju lɪɾəl pɹaɪɪŋ pændɔɹə/","zh":"你这个爱偷窥的潘多拉","en":"","note":""},{"id":"phantom-of-the-opera-07-010","lineIndex":10,"speaker":"","original":"You little demon","ipa":"/ju lɪɾəl dimən/","zh":"你这个魔鬼","en":"","note":""},{"id":"phantom-of-the-opera-07-011","lineIndex":11,"speaker":"","original":"Is this what you wanted to see?","ipa":"/ɪz ðɪs wʌt ju wɔntᵻd tə si/","zh":"这就是你想要看到的吗","en":"","note":""},{"id":"phantom-of-the-opera-07-012","lineIndex":12,"speaker":"","original":"Curse you!","ipa":"/kɜs ju/","zh":"诅咒你","en":"","note":""},{"id":"phantom-of-the-opera-07-013","lineIndex":13,"speaker":"","original":"you little lying Delilah","ipa":"/ju lɪɾəl laɪɪŋ dᵻlaɪlə/","zh":"你这个爱偷窥的戴丽拉","en":"","note":""},{"id":"phantom-of-the-opera-07-014","lineIndex":14,"speaker":"","original":"You little viper","ipa":"/ju lɪɾəl vɪplɚ/","zh":"你这个蛇蝎心肠的女人","en":"","note":""},{"id":"phantom-of-the-opera-07-015","lineIndex":15,"speaker":"","original":"now you cannot ever be free","ipa":"/naʊ ju kænɑt ɛvɚ bi fɹi/","zh":"我不会再让你重获自由","en":"","note":""},{"id":"phantom-of-the-opera-07-016","lineIndex":16,"speaker":"","original":"Damn you!","ipa":"/dæm ju/","zh":"真是该死","en":"","note":""},{"id":"phantom-of-the-opera-07-017","lineIndex":17,"speaker":"","original":"Curse you!","ipa":"/kɜs ju/","zh":"诅咒你","en":"","note":""},{"id":"phantom-of-the-opera-07-018","lineIndex":18,"speaker":"","original":"Stranger than you dreamt it","ipa":"/stɹeɪndʒɚ ðɐn ju dɹɛmpt ɪt/","zh":"事情比你梦中所见还要诡异","en":"","note":""},{"id":"phantom-of-the-opera-07-019","lineIndex":19,"speaker":"","original":"Can you even dare to look or bear to think of me","ipa":"/kæn ju ivən dɛɹ tə lʊk ɔɹ bɛɹ tə θɪŋk ʌv mi/","zh":"可能你会不敢看我甚至不敢想起我","en":"","note":""},{"id":"phantom-of-the-opera-07-020","lineIndex":20,"speaker":"","original":"this loathsome gargoyle who burns in hell","ipa":"/ðɪs loʊðsʌm ɡɑɹɡɔɪl hu bɜnz ɪn hɛl/","zh":"我这个来自地狱的令人厌恶的怪兽","en":"","note":""},{"id":"phantom-of-the-opera-07-021","lineIndex":21,"speaker":"","original":"but secretly yearns for heaven secretly","ipa":"/bʌt sikɹᵻtli jɜnz fɔɹ hɛvən sikɹᵻtli/","zh":"却依旧偷偷地向往着天堂","en":"","note":""},{"id":"phantom-of-the-opera-07-022","lineIndex":22,"speaker":"","original":"secretly","ipa":"/sikɹᵻtli/","zh":"偷偷地....","en":"","note":""},{"id":"phantom-of-the-opera-07-023","lineIndex":23,"speaker":"","original":"but Christine","ipa":"/bʌt kɹɪstin/","zh":"但是，克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-07-024","lineIndex":24,"speaker":"","original":"Fear can turn to love","ipa":"/fɪɹ kæn tɜn tə lʌv/","zh":"恐惧也可以变成爱的对吗","en":"","note":""},{"id":"phantom-of-the-opera-07-025","lineIndex":25,"speaker":"","original":"You 'll learn to see to find the man behind the monster","ipa":"/ju ɛlɛl lɜn tə si tə faɪnd ðə mæn bᵻhaɪnd ðə mɔnstɚ/","zh":"你不要因为这个像怪物一样的外表而害怕","en":"","note":""},{"id":"phantom-of-the-opera-07-026","lineIndex":26,"speaker":"","original":"This repulsive carcass who seems a beast","ipa":"/ðɪs ɹᵻpʌlsɪv kɑɹkəs hu simz ɐ bist/","zh":"这个丑陋的身躯虽然像个野兽","en":"","note":""},{"id":"phantom-of-the-opera-07-027","lineIndex":27,"speaker":"","original":"but secretly dreams of beauty","ipa":"/bʌt sikɹᵻtli dɹimz ʌv bjuɾi/","zh":"但依旧对美心生向往","en":"","note":""},{"id":"phantom-of-the-opera-07-028","lineIndex":28,"speaker":"","original":"secretly","ipa":"/sikɹᵻtli/","zh":"只能偷偷地","en":"","note":""},{"id":"phantom-of-the-opera-07-029","lineIndex":29,"speaker":"","original":"secretly","ipa":"/sikɹᵻtli/","zh":"偷偷地","en":"","note":""},{"id":"phantom-of-the-opera-07-030","lineIndex":30,"speaker":"","original":"oh Christine","ipa":"/oʊ kɹɪstin/","zh":"噢克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-07-031","lineIndex":31,"speaker":"","original":"Come, we must return","ipa":"/kʌm wi mʌst ɹᵻtɜn/","zh":"快过来，我们要回去了","en":"","note":""},{"id":"phantom-of-the-opera-07-032","lineIndex":32,"speaker":"","original":"those two fools who run my theatre will be missing you","ipa":"/ðoʊz tu fulz hu ɹʌn maɪ θiəɾɚ wɪl bi mɪsɪŋ ju/","zh":"不然经营我剧院的那两个蠢货要去找你了","en":"","note":""}],"sourceOrder":7,"displayOrder":7},{"order":8,"id":"08-magical-lasso-live","title":"Magical Lasso","titleZh":"魔法套索","lines":[{"id":"phantom-of-the-opera-08-001","lineIndex":1,"speaker":"","original":"Like yellow parchment","ipa":"/laɪk jɛloʊ pɑɹtʃmənt/","zh":"他的皮肤宛如","en":"","note":""},{"id":"phantom-of-the-opera-08-002","lineIndex":2,"speaker":"","original":"is his skin...","ipa":"/ɪz hɪz skɪn/","zh":"黄色羊皮纸","en":"","note":""},{"id":"phantom-of-the-opera-08-003","lineIndex":3,"speaker":"","original":"A great black hole serves as the nose that never grew...","ipa":"/ɐ ɡɹˈeɪt blˈæk hˈoʊl sˈɜːvd æz ðə nˈoʊz ðæt nˈɛvɚ ɡɹˈuː/","zh":"好像不曾长过鼻子似地","en":"","note":""},{"id":"phantom-of-the-opera-08-005","lineIndex":4,"speaker":"","original":"You must be always","ipa":"/ju mʌst bi ɔlweɪz/","zh":"你们务必要","en":"","note":""},{"id":"phantom-of-the-opera-08-006","lineIndex":5,"speaker":"","original":"on your guard","ipa":"/ɔn jʊɹ ɡɑɹd/","zh":"时时警惕","en":"","note":""},{"id":"phantom-of-the-opera-08-007","lineIndex":6,"speaker":"","original":"or he will catch you with his magical lasso!","ipa":"/ɔːɹ hiː wɪl kˈætʃ juː wɪð hɪz mˈædʒɪkəl lˈæsoʊ/","zh":"否则他会用魔索套住你","en":"","note":""},{"id":"phantom-of-the-opera-08-009","lineIndex":7,"speaker":"","original":"Those who speak","ipa":"/ðoʊz hu spik/","zh":"那些","en":"","note":""},{"id":"phantom-of-the-opera-08-010","lineIndex":8,"speaker":"","original":"of what they know","ipa":"/ʌv wʌt ðeɪ noʊ/","zh":"搬弄是非的人","en":"","note":""},{"id":"phantom-of-the-opera-08-011","lineIndex":9,"speaker":"","original":"find, too late, that prudent","ipa":"/faɪnd tu leɪt ðæt pɹudənt/","zh":"往往太迟发觉","en":"","note":""},{"id":"phantom-of-the-opera-08-012","lineIndex":10,"speaker":"","original":"silence is wise.","ipa":"/saɪləns ɪz waɪz/","zh":"沉默是金的道理","en":"","note":""},{"id":"phantom-of-the-opera-08-013","lineIndex":11,"speaker":"","original":"Joseph Buquet","ipa":"/dʒoʊsəf bjukeɪ/","zh":"乔瑟夫布凯","en":"","note":""},{"id":"phantom-of-the-opera-08-014","lineIndex":12,"speaker":"","original":"hold your tongue","ipa":"/hoʊld jʊɹ tʌŋ/","zh":"闭上你的嘴巴","en":"","note":""},{"id":"phantom-of-the-opera-08-015","lineIndex":13,"speaker":"","original":"he will burn you with the heat of his eyes...","ipa":"/hiː wɪl bˈɜːn juː wɪððə hˈiːt ʌv hɪz ˈaɪz/","zh":"他会用炽热的眼神烧死你","en":"","note":""}],"sourceOrder":8,"displayOrder":8},{"order":9,"id":"09-notes-prima-donna-live","title":"Notes.../Prima Donna","titleZh":"信件……／首席女高音","lines":[{"id":"phantom-of-the-opera-09-001","lineIndex":1,"speaker":"","original":"NOTES-PRIMA DONNA - Andrew Lloyd Webber","ipa":"/noʊtspɹimə dɑnə ændɹu lɔɪd wɛbɚ/","zh":"笔记 - PRIMA DONNA - 安德鲁·劳埃德·韦伯","en":"","note":""},{"id":"phantom-of-the-opera-09-002","lineIndex":2,"speaker":"","original":"\"Mystery after gala night\"","ipa":"/mɪstɚɹi æftɚ ɡeɪlə naɪt/","zh":"“晚会之后的谜团”","en":"","note":""},{"id":"phantom-of-the-opera-09-003","lineIndex":3,"speaker":"","original":"It says \"mystery of sopranos flight\"","ipa":"/ɪt sɛz mɪstɚɹi ʌv səpɹɑnoʊz flaɪt/","zh":"上面写着“女高音飞行之谜”","en":"","note":""},{"id":"phantom-of-the-opera-09-004","lineIndex":4,"speaker":"","original":"\"mystified\" all the papers say","ipa":"/mɪstᵻfaɪd ɔl ðə peɪpɚz seɪ/","zh":"所有报纸都说“很神秘”","en":"","note":""},{"id":"phantom-of-the-opera-09-005","lineIndex":5,"speaker":"","original":"\"we are mystified we suspect foul play\"","ipa":"/wi ɑɹ mɪstᵻfaɪd wi səspɛkt faʊl pleɪ/","zh":"“我们很困惑，我们怀疑有谋杀行为”","en":"","note":""},{"id":"phantom-of-the-opera-09-006","lineIndex":6,"speaker":"","original":"Bad news on soprano scene -","ipa":"/bæd nuz ɔn səpɹɑnoʊ sin/","zh":"女高音界的坏消息 -","en":"","note":""},{"id":"phantom-of-the-opera-09-007","lineIndex":7,"speaker":"","original":"first Carlotta, now Christine!","ipa":"/fɜst kɑɹlɑɾə naʊ kɹɪstin/","zh":"先是卡洛塔，现在是克里斯汀！","en":"","note":""},{"id":"phantom-of-the-opera-09-008","lineIndex":8,"speaker":"","original":"Still, at least the seats get sold","ipa":"/stɪl æt list ðə sits ɡɛt soʊld/","zh":"尽管如此，至少座位还是被卖掉了","en":"","note":""},{"id":"phantom-of-the-opera-09-009","lineIndex":9,"speaker":"","original":"gossip's worth its weight in gold...","ipa":"/ɡɑsɪps wɜθ ɪts weɪt ɪn ɡoʊld/","zh":"八卦是有价值的。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-010","lineIndex":10,"speaker":"","original":"What a way to run a business!","ipa":"/wʌt ɐ weɪ tə ɹʌn ɐ bɪznəs/","zh":"这是多么好的经营方式啊！","en":"","note":""},{"id":"phantom-of-the-opera-09-011","lineIndex":11,"speaker":"","original":"Spare me these unending trials!","ipa":"/spɛɹ mi ðiz ʌnɛndɪŋ tɹaɪəlz/","zh":"让我免受这些无休止的考验吧！","en":"","note":""},{"id":"phantom-of-the-opera-09-012","lineIndex":12,"speaker":"","original":"Half your cast disappears","ipa":"/hæf jʊɹ kæst dɪsɐpɪɹz/","zh":"你一半的演员消失了","en":"","note":""},{"id":"phantom-of-the-opera-09-013","lineIndex":13,"speaker":"","original":"but the crowd still cheers!","ipa":"/bʌt ðə kɹaʊd stɪl tʃɪɹz/","zh":"但人群依然欢呼！","en":"","note":""},{"id":"phantom-of-the-opera-09-014","lineIndex":14,"speaker":"","original":"Opera!","ipa":"/ɑpɚɹə/","zh":"歌剧！","en":"","note":""},{"id":"phantom-of-the-opera-09-015","lineIndex":15,"speaker":"","original":"To hell with Gluck and Handel -","ipa":"/tə hɛl wɪð ɡlʌk ænd hændəl/","zh":"让格鲁克和亨德尔见鬼去吧—","en":"","note":""},{"id":"phantom-of-the-opera-09-016","lineIndex":16,"speaker":"","original":"It's a scandal that'll pack 'em in the aisles!","ipa":"/ɪts ɐ skændəl ðæɾəl pæk ɛm ɪnðɪ aɪəlz/","zh":"这是一个会让他们挤满过道的丑闻！","en":"","note":""},{"id":"phantom-of-the-opera-09-017","lineIndex":17,"speaker":"","original":"Damnable!","ipa":"/dæməbəl/","zh":"可恶！","en":"","note":""},{"id":"phantom-of-the-opera-09-018","lineIndex":18,"speaker":"","original":"Will they all walk out?","ipa":"/wɪl ðeɪ ɔl wɔk aʊt/","zh":"他们都会走出来吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-019","lineIndex":19,"speaker":"","original":"This is damnable!","ipa":"/ðɪs ɪz dæməbəl/","zh":"这真是该死！","en":"","note":""},{"id":"phantom-of-the-opera-09-020","lineIndex":20,"speaker":"","original":"Andre, please don't shout...","ipa":"/ɑndɹeɪ pliz doʊnt ʃaʊt/","zh":"安德烈，请不要喊叫。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-021","lineIndex":21,"speaker":"","original":"It's publicity! And the take is vast!","ipa":"/ɪts pʌblɪsᵻɾi ænd ðə teɪk ɪz væst/","zh":"这是宣传！而且收入是巨大的！","en":"","note":""},{"id":"phantom-of-the-opera-09-022","lineIndex":22,"speaker":"","original":"Free publicity!","ipa":"/fɹi pʌblɪsᵻɾi/","zh":"免费宣传！","en":"","note":""},{"id":"phantom-of-the-opera-09-023","lineIndex":23,"speaker":"","original":"But we have no cast...","ipa":"/bʌt wi hæv noʊ kæst/","zh":"但我们没有演员阵容。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-024","lineIndex":24,"speaker":"","original":"But Andre","ipa":"/bʌt ɑndɹeɪ/","zh":"但是安德烈","en":"","note":""},{"id":"phantom-of-the-opera-09-025","lineIndex":25,"speaker":"","original":"have you seen the queue?","ipa":"/hæv ju sin ðə kju/","zh":"你看到队列了吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-026","lineIndex":26,"speaker":"","original":"Oh, it seems you've got one too...","ipa":"/oʊ ɪt simz juv ɡɑt wʌn tu/","zh":"哦，看来你也有一个。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-027","lineIndex":27,"speaker":"","original":"\"Dear Andre what a charming gala!","ipa":"/dɪɹ ɑndɹeɪ wʌt ɐ tʃɑɹmɪŋ ɡeɪlə/","zh":"“亲爱的安德烈，多么迷人的盛会啊！","en":"","note":""},{"id":"phantom-of-the-opera-09-028","lineIndex":28,"speaker":"","original":"Christine enjoyed a great success!","ipa":"/kɹɪstin ɛndʒɔɪd ɐ ɡɹeɪt səksɛs/","zh":"克里斯汀获得了巨大的成功！","en":"","note":""},{"id":"phantom-of-the-opera-09-029","lineIndex":29,"speaker":"","original":"We were hardly bereft when Carlotta left -","ipa":"/wi wɜ hɑɹdli bᵻɹɛft wɛn kɑɹlɑɾə lɛft/","zh":"当卡洛塔离开时，我们并没有感到失落—","en":"","note":""},{"id":"phantom-of-the-opera-09-030","lineIndex":30,"speaker":"","original":"Otherwise the chorus was entrancing","ipa":"/ʌðɚwaɪz ðə kɔɹəs wʌz ɛntɹænsɪŋ/","zh":"否则副歌就很迷人","en":"","note":""},{"id":"phantom-of-the-opera-09-031","lineIndex":31,"speaker":"","original":"but the dancing was a lamentable mess!\"","ipa":"/bʌt ðə dænsɪŋ wʌzɐ lɐmɛntəbəl mɛs/","zh":"但舞蹈真是一团糟！”","en":"","note":""},{"id":"phantom-of-the-opera-09-033","lineIndex":32,"speaker":"\"Dear Firmin, just a brief reminder","original":"my salary has not been paid.","ipa":"/maɪ sælɚɹi həznɑt bɪn peɪd/","zh":"我的工资还没有支付。","en":"","note":""},{"id":"phantom-of-the-opera-09-034","lineIndex":33,"speaker":"","original":"Send it care of the ghost, by return of post.","ipa":"/sɛnd ɪt kɛɹ ʌvðə ɡoʊst baɪ ɹᵻtɜn ʌv poʊst/","zh":"通过邮寄方式将其寄给鬼魂。","en":"","note":""},{"id":"phantom-of-the-opera-09-036","lineIndex":34,"speaker":"P. T. O.","original":"No-one likes a debtor","ipa":"/noʊwʌn laɪks ɐ dɛɾɚ/","zh":"没有人喜欢欠债的人","en":"","note":""},{"id":"phantom-of-the-opera-09-037","lineIndex":35,"speaker":"","original":"so it's better if my orders are obeyed!\"","ipa":"/soʊ ɪts bɛɾɚ ɪf maɪ ɔɹdɚz ɑɹ oʊbeɪd/","zh":"所以还是听我的命令比较好！”","en":"","note":""},{"id":"phantom-of-the-opera-09-038","lineIndex":36,"speaker":"","original":"Who would have the gall to send this?","ipa":"/hu wʊdhɐv ðə ɡɔl tə sɛnd ðɪs/","zh":"谁敢送这个？","en":"","note":""},{"id":"phantom-of-the-opera-09-039","lineIndex":37,"speaker":"","original":"Someone with a puerile brain!","ipa":"/sʌmwʌn wɪð ɐ pjuɹəl bɹeɪn/","zh":"一个脑子幼稚的人！","en":"","note":""},{"id":"phantom-of-the-opera-09-040","lineIndex":38,"speaker":"","original":"These are both signed \"O. G.\"...","ipa":"/ðiz ɑɹ boʊθ saɪnd oʊdʒi/","zh":"这些都标有“O. G.”。。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-041","lineIndex":39,"speaker":"","original":"Who the hell is he?","ipa":"/hu ðə hɛl ɪz hi/","zh":"他到底是谁？","en":"","note":""},{"id":"phantom-of-the-opera-09-042","lineIndex":40,"speaker":"","original":"Opera ghost!","ipa":"/ɑpɚɹə ɡoʊst/","zh":"歌剧鬼！","en":"","note":""},{"id":"phantom-of-the-opera-09-043","lineIndex":41,"speaker":"","original":"It's really not amusing!","ipa":"/ɪts ɹiəli nɑt ɐmjuzɪŋ/","zh":"实在是不好笑啊！","en":"","note":""},{"id":"phantom-of-the-opera-09-044","lineIndex":42,"speaker":"","original":"He's abusing our position!","ipa":"/hiz ɐbjuzɪŋ aʊɚ pəzɪʃən/","zh":"他滥用我们的地位！","en":"","note":""},{"id":"phantom-of-the-opera-09-045","lineIndex":43,"speaker":"","original":"In addition he wants money!","ipa":"/ɪn ɐdɪʃən hi wɔnts mʌni/","zh":"而且他还想要钱！","en":"","note":""},{"id":"phantom-of-the-opera-09-046","lineIndex":44,"speaker":"","original":"He's a funny sort of spectre...","ipa":"/hiz ɐ fʌni sɔɹt ʌv spɛktɚ/","zh":"他是一个有趣的幽灵。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-047","lineIndex":45,"speaker":"","original":"... to expect a large retainer!","ipa":"/tʊ ɛkspɛkt ɐ lɑɹdʒ ɹᵻteɪnɚ/","zh":"。。。期待一个大的保留！","en":"","note":""},{"id":"phantom-of-the-opera-09-048","lineIndex":46,"speaker":"","original":"Nothing plainer -","ipa":"/nʌθɪŋ pleɪnɚ/","zh":"没有什么更简单的了—","en":"","note":""},{"id":"phantom-of-the-opera-09-049","lineIndex":47,"speaker":"","original":"he is clearly quite insane!","ipa":"/hi ɪz klɪɹli kwaɪt ɪnseɪn/","zh":"他显然已经疯了！","en":"","note":""},{"id":"phantom-of-the-opera-09-050","lineIndex":48,"speaker":"","original":"Where is she?","ipa":"/wɛɹ ɪz ʃi/","zh":"她在哪儿？","en":"","note":""},{"id":"phantom-of-the-opera-09-051","lineIndex":49,"speaker":"","original":"You mean Carlotta?","ipa":"/ju min kɑɹlɑɾə/","zh":"你是说卡洛塔吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-052","lineIndex":50,"speaker":"","original":"I mean Miss Daae -","ipa":"/aɪ min mɪs dɑ/","zh":"我是说Daae小姐-","en":"","note":""},{"id":"phantom-of-the-opera-09-053","lineIndex":51,"speaker":"","original":"where is she?","ipa":"/wɛɹ ɪz ʃi/","zh":"她在哪儿？","en":"","note":""},{"id":"phantom-of-the-opera-09-054","lineIndex":52,"speaker":"","original":"Well, how should we know?","ipa":"/wɛl haʊ ʃʊd wi noʊ/","zh":"那么，我们怎么知道呢？","en":"","note":""},{"id":"phantom-of-the-opera-09-055","lineIndex":53,"speaker":"","original":"I want an answer -","ipa":"/aɪ wɔnt ɐn ænsɚ/","zh":"我想要一个答案—","en":"","note":""},{"id":"phantom-of-the-opera-09-056","lineIndex":54,"speaker":"","original":"I take it that you sent me this note?","ipa":"/aɪ teɪk ɪt ðæt ju sɛnt mi ðɪs noʊt/","zh":"我想这封信是你寄给我的吧？","en":"","note":""},{"id":"phantom-of-the-opera-09-057","lineIndex":55,"speaker":"","original":"What's all this nonsense?","ipa":"/wʌts ɔl ðɪs nɑnsəns/","zh":"这是什么废话？","en":"","note":""},{"id":"phantom-of-the-opera-09-058","lineIndex":56,"speaker":"","original":"Of course not!","ipa":"/ʌv kɔɹs nɑt/","zh":"当然不是！","en":"","note":""},{"id":"phantom-of-the-opera-09-059","lineIndex":57,"speaker":"","original":"Don't look at us!","ipa":"/doʊnt lʊk æɾ ʌs/","zh":"别看我们！","en":"","note":""},{"id":"phantom-of-the-opera-09-060","lineIndex":58,"speaker":"","original":"She's not with you, then?","ipa":"/ʃiz nɑt wɪð ju ðɛn/","zh":"那她没和你在一起吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-061","lineIndex":59,"speaker":"","original":"Of course not!","ipa":"/ʌv kɔɹs nɑt/","zh":"当然不是！","en":"","note":""},{"id":"phantom-of-the-opera-09-062","lineIndex":60,"speaker":"","original":"We're in the dark...","ipa":"/wɪɹ ɪnðə dɑɹk/","zh":"我们在黑暗中。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-063","lineIndex":61,"speaker":"","original":"Monsieur, don't argue -","ipa":"/məsjɜ doʊnt ɑɹɡju/","zh":"先生，别争论-","en":"","note":""},{"id":"phantom-of-the-opera-09-064","lineIndex":62,"speaker":"","original":"Isn't this the letter you wrote?","ipa":"/ɪzənt ðɪs ðə lɛɾɚ ju ɹoʊt/","zh":"这不是你写的信吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-065","lineIndex":63,"speaker":"","original":"And what is it, that we're meant to have wrote?","ipa":"/ænd wʌt ɪz ɪt ðæt wɪɹ mɛnt tə hæv ɹoʊt/","zh":"我们应该写什么？","en":"","note":""},{"id":"phantom-of-the-opera-09-066","lineIndex":64,"speaker":"","original":"\"Do not fear for Miss Daae.","ipa":"/dunɑt fɪɹ fɔɹ mɪs dɑ/","zh":"“不要担心 Daae 小姐。","en":"","note":""},{"id":"phantom-of-the-opera-09-067","lineIndex":65,"speaker":"","original":"The Angel of Music has her under his wing.","ipa":"/ðɪ eɪndʒəl ʌv mjuzɪk hɐz hɜɹ ʌndɚ hɪz wɪŋ/","zh":"音乐天使将她保护在自己的羽翼之下。","en":"","note":""},{"id":"phantom-of-the-opera-09-068","lineIndex":66,"speaker":"","original":"Make no attempt to see her again.\"","ipa":"/meɪk noʊ ɐtɛmpt tə si hɜɹ ɐɡɛn/","zh":"不要再试图见到她。”","en":"","note":""},{"id":"phantom-of-the-opera-09-069","lineIndex":67,"speaker":"","original":"If you didn't write it, who did?","ipa":"/ɪf ju dɪdnt ɹaɪt ɪt hu dɪd/","zh":"如果不是你写的，那又是谁写的？","en":"","note":""},{"id":"phantom-of-the-opera-09-070","lineIndex":68,"speaker":"","original":"Where is he?","ipa":"/wɛɹ ɪz hi/","zh":"他在哪儿？","en":"","note":""},{"id":"phantom-of-the-opera-09-071","lineIndex":69,"speaker":"","original":"Ah, welcome back!","ipa":"/ɑ wɛlkʌm bæk/","zh":"啊，欢迎回来！","en":"","note":""},{"id":"phantom-of-the-opera-09-072","lineIndex":70,"speaker":"","original":"Your precious patron -","ipa":"/jʊɹ pɹɛʃəs peɪtɹən/","zh":"您宝贵的赞助人 -","en":"","note":""},{"id":"phantom-of-the-opera-09-073","lineIndex":71,"speaker":"","original":"where is he?","ipa":"/wɛɹ ɪz hi/","zh":"他在哪里？","en":"","note":""},{"id":"phantom-of-the-opera-09-074","lineIndex":72,"speaker":"","original":"What is it now?","ipa":"/wʌt ɪz ɪt naʊ/","zh":"现在怎么样？","en":"","note":""},{"id":"phantom-of-the-opera-09-075","lineIndex":73,"speaker":"","original":"I have your letter -","ipa":"/aɪ hæv jʊɹ lɛɾɚ/","zh":"我收到了你的信 -","en":"","note":""},{"id":"phantom-of-the-opera-09-076","lineIndex":74,"speaker":"","original":"a letter which I rather resent!","ipa":"/ɐ lɛɾɚ wɪtʃ aɪ ɹæðɚ ɹᵻzɛnt/","zh":"这封我相当反感的信！","en":"","note":""},{"id":"phantom-of-the-opera-09-077","lineIndex":75,"speaker":"","original":"And did you send it?","ipa":"/ænd dɪd ju sɛnd ɪt/","zh":"你发送了吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-078","lineIndex":76,"speaker":"","original":"Of course not!","ipa":"/ʌv kɔɹs nɑt/","zh":"当然不是！","en":"","note":""},{"id":"phantom-of-the-opera-09-079","lineIndex":77,"speaker":"","original":"As if he would!","ipa":"/æz ɪf hi wʊd/","zh":"好像他会的！","en":"","note":""},{"id":"phantom-of-the-opera-09-080","lineIndex":78,"speaker":"","original":"You didn't send it?","ipa":"/ju dɪdnt sɛnd ɪt/","zh":"您没有发送？","en":"","note":""},{"id":"phantom-of-the-opera-09-081","lineIndex":79,"speaker":"","original":"Of course not!","ipa":"/ʌv kɔɹs nɑt/","zh":"当然不是！","en":"","note":""},{"id":"phantom-of-the-opera-09-082","lineIndex":80,"speaker":"","original":"What's going on...?","ipa":"/wʌts ɡoʊɪŋ ɔn/","zh":"发生了什么事。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-083","lineIndex":81,"speaker":"","original":"You dare to tell me","ipa":"/ju dɛɹ tə tɛl mi/","zh":"你敢告诉我","en":"","note":""},{"id":"phantom-of-the-opera-09-084","lineIndex":82,"speaker":"","original":"that this is not the letter you sent?!","ipa":"/ðæt ðɪs ɪz nɑt ðə lɛɾɚ ju sɛnt ɛkskləmeɪʃən/","zh":"这不是你寄的信？！","en":"","note":""},{"id":"phantom-of-the-opera-09-085","lineIndex":83,"speaker":"","original":"And what is it that I'm","ipa":"/ænd wʌt ɪz ɪt ðæt aɪm/","zh":"我","en":"","note":""},{"id":"phantom-of-the-opera-09-086","lineIndex":84,"speaker":"","original":"meant to have sent?","ipa":"/mɛnt tə hæv sɛnt/","zh":"想要发送的内容是什么？","en":"","note":""},{"id":"phantom-of-the-opera-09-087","lineIndex":85,"speaker":"","original":"\"Your days","ipa":"/jʊɹ deɪz/","zh":"“你在大众歌剧院","en":"","note":""},{"id":"phantom-of-the-opera-09-088","lineIndex":86,"speaker":"","original":"at the Opera Populaire are numbered.","ipa":"/æt ðɪ ɑpɚɹə pɑpjʊlɛɹ ɑɹ nʌmbɚd/","zh":"的日子已经屈指可数了。","en":"","note":""},{"id":"phantom-of-the-opera-09-089","lineIndex":87,"speaker":"","original":"Christine Daae will be singing on your behalf tonight.","ipa":"/kɹɪstin dɑ wɪl bi sɪŋɪŋ ɔn jʊɹ bᵻhæf tənaɪt/","zh":"Christine Daae 今晚将为你演唱。","en":"","note":""},{"id":"phantom-of-the-opera-09-090","lineIndex":88,"speaker":"","original":"Be prepared for a great misfortune","ipa":"/bi pɹɪpɛɹd fɚɹə ɡɹeɪt mɪsfɔɹtʃʊn/","zh":"如果你试图取代她的位置，请做好迎接巨大不幸的准备","en":"","note":""},{"id":"phantom-of-the-opera-09-091","lineIndex":89,"speaker":"","original":"should you attempt to take her place.\"","ipa":"/ʃʊd ju ɐtɛmpt tə teɪk hɜ pleɪs/","zh":"。”","en":"","note":""},{"id":"phantom-of-the-opera-09-092","lineIndex":90,"speaker":"","original":"Far too many notes for my taste -","ipa":"/fɑɹ tu mɛni noʊts fɔɹ maɪ teɪst/","zh":"太多的笔记不符合我的口味 -","en":"","note":""},{"id":"phantom-of-the-opera-09-093","lineIndex":91,"speaker":"","original":"and most of them about Christine!","ipa":"/ænd moʊst əv ðɛm ɐbaʊt kɹɪstin/","zh":"其中大部分都是关于 Christine 的！","en":"","note":""},{"id":"phantom-of-the-opera-09-094","lineIndex":92,"speaker":"","original":"All we've heard since we came","ipa":"/ɔl wiv hɜd sɪns wi keɪm/","zh":"自从我们来到","en":"","note":""},{"id":"phantom-of-the-opera-09-095","lineIndex":93,"speaker":"","original":"is Miss Daae's name...","ipa":"/ɪz mɪs dɑz neɪm/","zh":"以来，我们所听到的就是Daae小姐的名字。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-096","lineIndex":94,"speaker":"","original":"Miss Daae has returned.","ipa":"/mɪs dɑ hɐz ɹᵻtɜnd/","zh":"Daae小姐回来了。","en":"","note":""},{"id":"phantom-of-the-opera-09-097","lineIndex":95,"speaker":"","original":"I trust her midnight oil","ipa":"/aɪ tɹʌst hɜ mɪdnaɪt ɔɪl/","zh":"我相信她的夜宵","en":"","note":""},{"id":"phantom-of-the-opera-09-098","lineIndex":96,"speaker":"","original":"is well and truly burned.","ipa":"/ɪz wɛl ænd tɹuli bɜnd/","zh":"已经燃烧得很好。","en":"","note":""},{"id":"phantom-of-the-opera-09-099","lineIndex":97,"speaker":"","original":"Where precisely is she now?","ipa":"/wɛɹ pɹɪsaɪsli ɪz ʃi naʊ/","zh":"她现在到底在哪里？","en":"","note":""},{"id":"phantom-of-the-opera-09-100","lineIndex":98,"speaker":"","original":"I thought it best that she went home...","ipa":"/aɪ θɔt ɪt bɛst ðæt ʃi wɛnt hoʊm/","zh":"我认为她最好回家。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-101","lineIndex":99,"speaker":"","original":"She needed rest.","ipa":"/ʃi nidᵻd ɹɛst/","zh":"她需要休息。","en":"","note":""},{"id":"phantom-of-the-opera-09-102","lineIndex":100,"speaker":"","original":"May I see her?","ipa":"/meɪ aɪ si hɜ/","zh":"我可以见她吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-103","lineIndex":101,"speaker":"","original":"No, monsieur, she will see no-one.","ipa":"/noʊ məsjɜ ʃi wɪl si noʊwʌn/","zh":"不，先生，她不会见任何人。","en":"","note":""},{"id":"phantom-of-the-opera-09-104","lineIndex":102,"speaker":"","original":"Will she sing?","ipa":"/wɪl ʃi sɪŋ/","zh":"她会唱歌吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-105","lineIndex":103,"speaker":"","original":"Will she sing?","ipa":"/wɪl ʃi sɪŋ/","zh":"她会唱歌吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-106","lineIndex":104,"speaker":"","original":"Here, I have a note...","ipa":"/hɪɹ aɪ hæv ɐ noʊt/","zh":"这里，我有一个注释。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-107","lineIndex":105,"speaker":"","original":"Let me see it!","ipa":"/lɛt mi si ɪt/","zh":"让我看看！","en":"","note":""},{"id":"phantom-of-the-opera-09-108","lineIndex":106,"speaker":"","original":"Please!","ipa":"/pliz/","zh":"拜托！","en":"","note":""},{"id":"phantom-of-the-opera-09-109","lineIndex":107,"speaker":"","original":"\"Gentlemen, I have now sent you several notes of the most amiable nature, detailing how my theatre is to be run. You have not followed my instructions.","ipa":"/dʒˈɛntəlmən aɪ hæv nˈaʊ sˈɛnt juː sˈɛvɹəl nˈoʊts ʌvðə mˈoʊst ˈeɪmiəbəl nˈeɪtʃɚ diːtˈeɪlɪŋ hˌaʊ maɪ θˈiəɾɚɹ ɪz təbi ɹˈʌn juː hɐvnˌɑːt fˈɑːloʊd maɪ ɪnstɹˈʌkʃənz/","zh":"“先生们，我现在已经向你们发送了几份关于最和蔼可亲的便条，详细说明了我的剧院将如何运营。你们没有听从我的指示。","en":"","note":""},{"id":"phantom-of-the-opera-09-112","lineIndex":108,"speaker":"","original":"I shall give you one last chance...\"","ipa":"/aɪʃɐl ɡɪv ju wʌn læst tʃæns/","zh":"我会给你们最后一次机会……”","en":"","note":""},{"id":"phantom-of-the-opera-09-113","lineIndex":109,"speaker":"","original":"... Christine Daae has returned to you","ipa":"/kɹɪstin dɑ hɐz ɹᵻtɜnd tə ju/","zh":"。。。 Christine Daae 已回到您身边","en":"","note":""},{"id":"phantom-of-the-opera-09-114","lineIndex":110,"speaker":"","original":"and I am anxious her career should progress.","ipa":"/ænd aɪɐm æŋʃəs hɜ kɚɹɪɹ ʃʊd pɹəɡɹɛs/","zh":"我担心她的事业应该取得进展。","en":"","note":""},{"id":"phantom-of-the-opera-09-115","lineIndex":111,"speaker":"","original":"In the new production of \"Il Muto\"","ipa":"/ɪnðə nu pɹədʌkʃən ʌv ɪl mjuɾoʊ/","zh":"在新制作的“Il Muto”中","en":"","note":""},{"id":"phantom-of-the-opera-09-116","lineIndex":112,"speaker":"","original":"you will therefore cast Carlotta as the Pageboy","ipa":"/ju wɪl ðɛɹfɔɹ kæst kɑɹlɑɾə æz ðə peɪdʒbɔɪ/","zh":"因此，您将让卡洛塔扮演侍童","en":"","note":""},{"id":"phantom-of-the-opera-09-117","lineIndex":113,"speaker":"","original":"and put Miss Daae in the role of Countess.","ipa":"/ænd pʊt mɪs dɑ ɪnðə ɹoʊl ʌv kaʊntɛs/","zh":"并让 Daae 小姐扮演伯爵夫人的角色。","en":"","note":""},{"id":"phantom-of-the-opera-09-118","lineIndex":114,"speaker":"","original":"The role which Miss Daae plays calls for charm and appeal.","ipa":"/ðə ɹoʊl wɪtʃ mɪs dɑ pleɪz kɔlz fɔɹ tʃɑɹm ænd ɐpil/","zh":"多爱小姐扮演的角色充满魅力和感染力。","en":"","note":""},{"id":"phantom-of-the-opera-09-119","lineIndex":115,"speaker":"","original":"The role of the Pageboy is silent -","ipa":"/ðə ɹoʊl ʌvðə peɪdʒbɔɪ ɪz saɪlənt/","zh":"侍童的角色是沉默的 -","en":"","note":""},{"id":"phantom-of-the-opera-09-120","lineIndex":116,"speaker":"","original":"which makes my casting, in a word... ideal.","ipa":"/wɪtʃ meɪks maɪ kæstɪŋ ɪn ɐ wɜd aɪdiəl/","zh":"这使得我的选角，总而言之。。。理想的。","en":"","note":""},{"id":"phantom-of-the-opera-09-121","lineIndex":117,"speaker":"","original":"I shall watch the performance from my normal seat in","ipa":"/aɪʃɐl wɑtʃ ðə pɚfɔɹməns fɹʌm maɪ nɔɹməl sit ɪn/","zh":"我将在","en":"","note":""},{"id":"phantom-of-the-opera-09-122","lineIndex":118,"speaker":"","original":"Box Five, which will be kept empty for me. Should","ipa":"/bɑks faɪv wɪtʃ wɪl bi kɛpt ɛmpti fɔɹ mi ʃʊd/","zh":"第五号包厢的普通座位上观看演出，该座位将为我保留为空。如果","en":"","note":""},{"id":"phantom-of-the-opera-09-123","lineIndex":119,"speaker":"","original":"these commands be ignored, a disaster beyond your imagination will occur.","ipa":"/ðiːz kəmˈændz biː ɪɡnˈɔːɹd ɐ dɪzˈæstɚ bᵻjˌɔnd jʊɹ ɪmˌædʒᵻnˈeɪʃən wɪl əkˈɜː/","zh":"这些命令被忽略，将会发生超出您想象的灾难。","en":"","note":""},{"id":"phantom-of-the-opera-09-125","lineIndex":120,"speaker":"","original":"\"I remain, Gentlemen, Your obedient servant, O. G.\"","ipa":"/aɪ ɹᵻmeɪn dʒɛntəlmən jʊɹ oʊbidiənt sɜvənt oʊdʒi/","zh":"“先生们，我仍然是你们服从的仆人，O. G.”","en":"","note":""},{"id":"phantom-of-the-opera-09-126","lineIndex":121,"speaker":"","original":"Christine!","ipa":"/kɹɪstin/","zh":"克里斯汀！","en":"","note":""},{"id":"phantom-of-the-opera-09-127","lineIndex":122,"speaker":"","original":"Whatever next...?","ipa":"/wʌtɛvɚ nɛkst/","zh":"不管接下来。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-128","lineIndex":123,"speaker":"","original":"It's all a ploy to help Christine!","ipa":"/ɪts ɔl ɐ plɔɪ tə hɛlp kɹɪstin/","zh":"这都是帮助克里斯汀的策略！","en":"","note":""},{"id":"phantom-of-the-opera-09-129","lineIndex":124,"speaker":"","original":"This is insane...","ipa":"/ðɪs ɪz ɪnseɪn/","zh":"这太疯狂了。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-130","lineIndex":125,"speaker":"","original":"I know who sent this:","ipa":"/aɪ noʊ hu sɛnt ðɪs/","zh":"我知道是谁发来的：","en":"","note":""},{"id":"phantom-of-the-opera-09-131","lineIndex":126,"speaker":"","original":"The Vicomte - her lover!","ipa":"/ðə vɪkɑmt hɜ lʌvɚ/","zh":"子爵 - 她的爱人！","en":"","note":""},{"id":"phantom-of-the-opera-09-132","lineIndex":127,"speaker":"","original":"Indeed?","ipa":"/ɪndid/","zh":"确实如此？","en":"","note":""},{"id":"phantom-of-the-opera-09-133","lineIndex":128,"speaker":"","original":"Can you believe this?","ipa":"/kæn ju bᵻliv ðɪs/","zh":"你能相信吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-134","lineIndex":129,"speaker":"","original":"Signora!","ipa":"/sɪnjɔɹə/","zh":"夫人！","en":"","note":""},{"id":"phantom-of-the-opera-09-135","lineIndex":130,"speaker":"","original":"O traditori!","ipa":"/oʊ tɹɐdɪtɔɹi/","zh":"哦，传统！","en":"","note":""},{"id":"phantom-of-the-opera-09-136","lineIndex":131,"speaker":"","original":"This is a joke!","ipa":"/ðɪs ɪz ɐ dʒoʊk/","zh":"这是个笑话！","en":"","note":""},{"id":"phantom-of-the-opera-09-137","lineIndex":132,"speaker":"","original":"This changes nothing!","ipa":"/ðɪs tʃeɪndʒᵻz nʌθɪŋ/","zh":"这没有任何改变！","en":"","note":""},{"id":"phantom-of-the-opera-09-138","lineIndex":133,"speaker":"","original":"O mentitori!","ipa":"/oʊ mɛntɪtɔɹi/","zh":"哦，mentitori！","en":"","note":""},{"id":"phantom-of-the-opera-09-139","lineIndex":134,"speaker":"","original":"Signora!","ipa":"/sɪnjɔɹə/","zh":"夫人！","en":"","note":""},{"id":"phantom-of-the-opera-09-140","lineIndex":135,"speaker":"","original":"You are our star!","ipa":"/ju ɑɹ aʊɚ stɑɹ/","zh":"你是我们的明星！","en":"","note":""},{"id":"phantom-of-the-opera-09-141","lineIndex":136,"speaker":"","original":"And always will be!","ipa":"/ænd ɔlweɪz wɪl bi/","zh":"永远都是！","en":"","note":""},{"id":"phantom-of-the-opera-09-142","lineIndex":137,"speaker":"","original":"Signora...","ipa":"/sɪnjɔɹə/","zh":"夫人。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-143","lineIndex":138,"speaker":"","original":"The man is mad!","ipa":"/ðə mæn ɪz mæd/","zh":"这个男人疯了！","en":"","note":""},{"id":"phantom-of-the-opera-09-144","lineIndex":139,"speaker":"","original":"We don't take orders!","ipa":"/wi doʊnt teɪk ɔɹdɚz/","zh":"我们不接受订单！","en":"","note":""},{"id":"phantom-of-the-opera-09-145","lineIndex":140,"speaker":"","original":"Miss Daae will be playing the Pageboy-","ipa":"/mɪs dɑ wɪl bi pleɪɪŋ ðə peɪdʒbɔɪ/","zh":"Daae小姐将扮演Pageboy-","en":"","note":""},{"id":"phantom-of-the-opera-09-146","lineIndex":141,"speaker":"","original":"the silent role...","ipa":"/ðə saɪlənt ɹoʊl/","zh":"沉默的角色。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-147","lineIndex":142,"speaker":"","original":"Carlotta will be playing the lead!","ipa":"/kɑɹlɑɾə wɪl bi pleɪɪŋ ðə lid/","zh":"卡洛塔将担任主角！","en":"","note":""},{"id":"phantom-of-the-opera-09-148","lineIndex":143,"speaker":"","original":"It's useless trying to appease me!","ipa":"/ɪts jusləs tɹaɪɪŋ tʊ ɐpiz mi/","zh":"试图安抚我是没有用的！","en":"","note":""},{"id":"phantom-of-the-opera-09-149","lineIndex":144,"speaker":"","original":"You're only saying this to please me!","ipa":"/jʊɹ oʊnli seɪɪŋ ðɪs tə pliz mi/","zh":"你这么说只是为了取悦我！","en":"","note":""},{"id":"phantom-of-the-opera-09-150","lineIndex":145,"speaker":"","original":"Signori, e vero?","ipa":"/sɪnjɔɹi i viəɹoʊ/","zh":"先生，是吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-151","lineIndex":146,"speaker":"","original":"Non, non, non voglio udire!","ipa":"/nɑn nɑn nɑn vɑɡlɪoʊ judaɪɚ/","zh":"不，不，不voglio udire！","en":"","note":""},{"id":"phantom-of-the-opera-09-152","lineIndex":147,"speaker":"","original":"Lasciatemi morire!","ipa":"/læsɪeɪtmi mɔɹaɪɚ/","zh":"Lasciatemi morire！","en":"","note":""},{"id":"phantom-of-the-opera-09-153","lineIndex":148,"speaker":"","original":"O padre mio!","ipa":"/oʊ pɑdɹeɪ mioʊ/","zh":"我的神父啊！","en":"","note":""},{"id":"phantom-of-the-opera-09-154","lineIndex":149,"speaker":"","original":"Dio!","ipa":"/dioʊ/","zh":"迪奥！","en":"","note":""},{"id":"phantom-of-the-opera-09-155","lineIndex":150,"speaker":"","original":"Who scorn his word","ipa":"/hu skɔɹn hɪz wɜd/","zh":"谁蔑视他的话","en":"","note":""},{"id":"phantom-of-the-opera-09-156","lineIndex":151,"speaker":"","original":"beware to those...","ipa":"/bᵻwɛɹ tə ðoʊz/","zh":"小心那些。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-157","lineIndex":152,"speaker":"","original":"You have reviled me!","ipa":"/ju hæv ɹᵻvaɪld mi/","zh":"你辱骂了我！","en":"","note":""},{"id":"phantom-of-the-opera-09-158","lineIndex":153,"speaker":"","original":"The angel sees","ipa":"/ðɪ eɪndʒəl siz/","zh":"天使看见","en":"","note":""},{"id":"phantom-of-the-opera-09-159","lineIndex":154,"speaker":"","original":"the angel knows...","ipa":"/ðɪ eɪndʒəl noʊz/","zh":"天使知道。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-160","lineIndex":155,"speaker":"","original":"Why did Christine fly from my arms...?","ipa":"/waɪ dɪd kɹɪstin flaɪ fɹʌm maɪ ɑɹmz/","zh":"克莉丝汀为什么从我怀里飞走了。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-161","lineIndex":156,"speaker":"","original":"You have rebuked me!","ipa":"/ju hæv ɹᵻbjukt mi/","zh":"你斥责了我！","en":"","note":""},{"id":"phantom-of-the-opera-09-162","lineIndex":157,"speaker":"","original":"Signora, pardon us...","ipa":"/sɪnjɔɹə pɑɹdən ʌs/","zh":"夫人，请原谅我们。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-163","lineIndex":158,"speaker":"","original":"You have replaced me!","ipa":"/ju hæv ɹᵻpleɪst mi/","zh":"你取代了我！","en":"","note":""},{"id":"phantom-of-the-opera-09-164","lineIndex":159,"speaker":"","original":"Please, Signora, we beseech you...","ipa":"/pliz sɪnjɔɹə wi bᵻsitʃ ju/","zh":"拜托，夫人，我们恳求您。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-165","lineIndex":160,"speaker":"","original":"This hour shall see your darkest fears...","ipa":"/ðɪs aʊɚ ʃæl si jʊɹ dɑɹkɪst fɪɹz/","zh":"这一小时将见证你最黑暗的恐惧。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-166","lineIndex":161,"speaker":"","original":"I must see her...","ipa":"/aɪ mʌst si hɜ/","zh":"我必须见她。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-167","lineIndex":162,"speaker":"","original":"Abbandonata!","ipa":"/æbɐndoʊnɑɾə/","zh":"放弃！","en":"","note":""},{"id":"phantom-of-the-opera-09-168","lineIndex":163,"speaker":"","original":"Deseredata!","ipa":"/dɪzɜɹɪdeɪɾə/","zh":"销毁数据！","en":"","note":""},{"id":"phantom-of-the-opera-09-169","lineIndex":164,"speaker":"","original":"O, sventurata!","ipa":"/oʊ svɛntʃɚɹɑɾə/","zh":"噢，冒险！","en":"","note":""},{"id":"phantom-of-the-opera-09-170","lineIndex":165,"speaker":"","original":"The angel knows","ipa":"/ðɪ eɪndʒəl noʊz/","zh":"天使知道","en":"","note":""},{"id":"phantom-of-the-opera-09-171","lineIndex":166,"speaker":"","original":"the angel hears...","ipa":"/ðɪ eɪndʒəl hɪɹz/","zh":"天使听到。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-172","lineIndex":167,"speaker":"","original":"Where did she go...?","ipa":"/wɛɹ dɪd ʃi ɡoʊ/","zh":"她去哪儿了。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-173","lineIndex":168,"speaker":"","original":"Abbandonata!","ipa":"/æbɐndoʊnɑɾə/","zh":"放弃！","en":"","note":""},{"id":"phantom-of-the-opera-09-174","lineIndex":169,"speaker":"","original":"Disgraziata!","ipa":"/dɪsɡɹeɪzɪɑɾə/","zh":"可耻！","en":"","note":""},{"id":"phantom-of-the-opera-09-175","lineIndex":170,"speaker":"","original":"Signora, sing for us!","ipa":"/sɪnjɔɹə sɪŋ fɔɹ ʌs/","zh":"夫人，为我们唱歌吧！","en":"","note":""},{"id":"phantom-of-the-opera-09-176","lineIndex":171,"speaker":"","original":"Don't be a martyr...","ipa":"/doʊnt bi ɐ mɑɹɾɚ/","zh":"不要成为烈士。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-177","lineIndex":172,"speaker":"","original":"What new surprises lie in store...?","ipa":"/wʌt nu sɚpɹaɪzᵻz laɪ ɪn stɔɹ/","zh":"等待着我们的新惊喜。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-178","lineIndex":173,"speaker":"","original":"Our star...!","ipa":"/aʊɚ stɑɹ/","zh":"我们的明星。。.！","en":"","note":""},{"id":"phantom-of-the-opera-09-179","lineIndex":174,"speaker":"","original":"Non vo' cantar!","ipa":"/nɑn voʊ kæntɚ/","zh":"别唱了！","en":"","note":""},{"id":"phantom-of-the-opera-09-180","lineIndex":175,"speaker":"","original":"Your public needs you!","ipa":"/jʊɹ pʌblɪk nidz ju/","zh":"您的公众需要您！","en":"","note":""},{"id":"phantom-of-the-opera-09-181","lineIndex":176,"speaker":"","original":"We need you, too!","ipa":"/wi nid ju tu/","zh":"我们也需要你！","en":"","note":""},{"id":"phantom-of-the-opera-09-182","lineIndex":177,"speaker":"","original":"Would you not rather have your precious little ingenue?","ipa":"/wʊd ju nɑt ɹæðɚ hæv jʊɹ pɹɛʃəs lɪɾəl ɪndʒɛnu/","zh":"你不想拥有你那可爱的天真无邪的小孩子吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-183","lineIndex":178,"speaker":"","original":"Signora, no!","ipa":"/sɪnjɔɹə noʊ/","zh":"夫人，不！","en":"","note":""},{"id":"phantom-of-the-opera-09-184","lineIndex":179,"speaker":"","original":"The world wants you!","ipa":"/ðə wɜld wɔnts ju/","zh":"世界需要你！","en":"","note":""},{"id":"phantom-of-the-opera-09-185","lineIndex":180,"speaker":"","original":"Prima donna first lady of the stage!","ipa":"/pɹimə dɑnə fɜst leɪdi ʌvðə steɪdʒ/","zh":"舞台上的第一夫人！","en":"","note":""},{"id":"phantom-of-the-opera-09-186","lineIndex":181,"speaker":"","original":"Your devotees are on their knees to implore you!","ipa":"/jʊɹ dɛvoʊtiz ɑɹ ɔn ðɛɹ niz tʊ ɪmplɔɹ ju/","zh":"你的信徒正在跪下恳求你！","en":"","note":""},{"id":"phantom-of-the-opera-09-187","lineIndex":182,"speaker":"","original":"Can you bow out when they're shouting your name?","ipa":"/kæn ju baʊ aʊt wɛn ðeɪɚ ʃaʊɾɪŋ jʊɹ neɪm/","zh":"当他们喊你的名字时你能退出吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-188","lineIndex":183,"speaker":"","original":"Think of how they all adore you!","ipa":"/θɪŋk ʌv haʊ ðeɪ ɔl ɐdɔɹ ju/","zh":"想想他们多么崇拜你！","en":"","note":""},{"id":"phantom-of-the-opera-09-189","lineIndex":184,"speaker":"","original":"Prima donna","ipa":"/pɹimə dɑnə/","zh":"首席女歌手","en":"","note":""},{"id":"phantom-of-the-opera-09-190","lineIndex":185,"speaker":"","original":"enchant us once again!","ipa":"/ɛntʃænt ʌs wʌns ɐɡɛn/","zh":"再次让我们着迷！","en":"","note":""},{"id":"phantom-of-the-opera-09-191","lineIndex":186,"speaker":"","original":"Think of your muse...","ipa":"/θɪŋk ʌv jʊɹ mjuz/","zh":"想想你的缪斯女神。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-192","lineIndex":187,"speaker":"","original":"And of the queues round the theatre!","ipa":"/ænd ʌvðə kjuz ɹaʊnd ðə θiəɾɚ/","zh":"还有剧院周围的队列！","en":"","note":""},{"id":"phantom-of-the-opera-09-193","lineIndex":188,"speaker":"","original":"Can you deny us the triumph in store?","ipa":"/kæn ju dᵻnaɪ ʌs ðə tɹaɪʌmf ɪn stɔɹ/","zh":"你能否认我们在商店中的胜利吗？","en":"","note":""},{"id":"phantom-of-the-opera-09-194","lineIndex":189,"speaker":"","original":"Sing, prima donna, once more!","ipa":"/sɪŋ pɹimə dɑnə wʌns mɔɹ/","zh":"首席女歌手，再唱一次！","en":"","note":""},{"id":"phantom-of-the-opera-09-195","lineIndex":190,"speaker":"","original":"Christine spoke of an angel...","ipa":"/kɹɪstin spoʊk əvən eɪndʒəl/","zh":"克里斯汀谈到了一位天使。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-196","lineIndex":191,"speaker":"","original":"Prima donna, your song shall live again!","ipa":"/pɹimə dɑnə jʊɹ sɔŋ ʃæl lɪv ɐɡɛn/","zh":"女主角，你的歌将再次流传！","en":"","note":""},{"id":"phantom-of-the-opera-09-197","lineIndex":192,"speaker":"","original":"Think of your public!","ipa":"/θɪŋk ʌv jʊɹ pʌblɪk/","zh":"想想你的公众！","en":"","note":""},{"id":"phantom-of-the-opera-09-198","lineIndex":193,"speaker":"","original":"You took a snub","ipa":"/ju tʊk ɐ snʌb/","zh":"你受到了冷落","en":"","note":""},{"id":"phantom-of-the-opera-09-199","lineIndex":194,"speaker":"","original":"but there's a public who needs you!","ipa":"/bʌt ðɛɹz ɐ pʌblɪk hu nidz ju/","zh":"但还有公众需要你！","en":"","note":""},{"id":"phantom-of-the-opera-09-200","lineIndex":195,"speaker":"","original":"She has heard the voice of the angel of music...","ipa":"/ʃi hɐz hɜd ðə vɔɪs ʌvðɪ eɪndʒəl ʌv mjuzɪk/","zh":"她听到了音乐天使的声音。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-201","lineIndex":196,"speaker":"","original":"Those who hear your voice","ipa":"/ðoʊz hu hɪɹ jʊɹ vɔɪs/","zh":"那些听到你声音的人","en":"","note":""},{"id":"phantom-of-the-opera-09-202","lineIndex":197,"speaker":"","original":"liken you to an angel!","ipa":"/laɪkən ju tʊ ɐn eɪndʒəl/","zh":"将你视为天使！","en":"","note":""},{"id":"phantom-of-the-opera-09-203","lineIndex":198,"speaker":"","original":"Think of their cry","ipa":"/θɪŋk ʌv ðɛɹ kɹaɪ/","zh":"想起他们的哭泣","en":"","note":""},{"id":"phantom-of-the-opera-09-204","lineIndex":199,"speaker":"","original":"of undying support!","ipa":"/ʌv ʌndaɪɪŋ səpɔɹt/","zh":"不朽的支持！","en":"","note":""},{"id":"phantom-of-the-opera-09-205","lineIndex":200,"speaker":"","original":"Is this her angel of music...?","ipa":"/ɪz ðɪs hɜɹ eɪndʒəl ʌv mjuzɪk/","zh":"这就是她的音乐天使吗？。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-206","lineIndex":201,"speaker":"","original":"We get our opera...","ipa":"/wi ɡɛt aʊɚɹ ɑpɚɹə/","zh":"我们得到了我们的歌剧。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-207","lineIndex":202,"speaker":"","original":"She gets her limelight!","ipa":"/ʃi ɡɛts hɜ laɪmlaɪt/","zh":"她成为众人瞩目的焦点！","en":"","note":""},{"id":"phantom-of-the-opera-09-208","lineIndex":203,"speaker":"","original":"Follow where the limelight leads you!","ipa":"/fɑloʊ wɛɹ ðə laɪmlaɪt lidz ju/","zh":"追随聚光灯的指引！","en":"","note":""},{"id":"phantom-of-the-opera-09-209","lineIndex":204,"speaker":"","original":"Is this ghost an angel or a madman...?","ipa":"/ɪz ðɪs ɡoʊst ɐn eɪndʒəl ɔɹ ɐ mædmən/","zh":"这个鬼魂是天使还是疯子。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-210","lineIndex":205,"speaker":"","original":"Angel or madman...?","ipa":"/eɪndʒəl ɔɹ mædmən/","zh":"天使或疯子。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-211","lineIndex":206,"speaker":"","original":"Leading ladies are a trial!","ipa":"/lidɪŋ leɪdiz ɑɹ ɐ tɹaɪəl/","zh":"女主角是考验！","en":"","note":""},{"id":"phantom-of-the-opera-09-212","lineIndex":207,"speaker":"","original":"Heaven help you","ipa":"/hɛvən hɛlp ju/","zh":"天堂会帮助你","en":"","note":""},{"id":"phantom-of-the-opera-09-213","lineIndex":208,"speaker":"","original":"those who doubt...","ipa":"/ðoʊz hu daʊt/","zh":"那些怀疑的人。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-214","lineIndex":209,"speaker":"","original":"You'll sing again","ipa":"/jul sɪŋ ɐɡɛn/","zh":"你会再次歌唱","en":"","note":""},{"id":"phantom-of-the-opera-09-215","lineIndex":210,"speaker":"","original":"and to unending ovation!","ipa":"/ænd tʊ ʌnɛndɪŋ oʊveɪʃən/","zh":"并获得无尽的掌声！","en":"","note":""},{"id":"phantom-of-the-opera-09-216","lineIndex":211,"speaker":"","original":"Orders! Warnings!","ipa":"/ɔɹdɚz wɔɹnɪŋz/","zh":"订单！警告！","en":"","note":""},{"id":"phantom-of-the-opera-09-217","lineIndex":212,"speaker":"","original":"Lunatic demands!","ipa":"/lunətɪk dᵻmændz/","zh":"疯狂的要求！","en":"","note":""},{"id":"phantom-of-the-opera-09-218","lineIndex":213,"speaker":"","original":"This miscasting will invite damnation...","ipa":"/ðɪs mɪskæstɪŋ wɪl ɪnvaɪt dæmneɪʃən/","zh":"这种错误的选择会招致诅咒。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-219","lineIndex":214,"speaker":"","original":"Tears... oaths...","ipa":"/tɪɹz oʊθs/","zh":"泪水。。。誓言。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-220","lineIndex":215,"speaker":"","original":"lunatic demands are regular occurrences!","ipa":"/ɪənæɾɪk dᵻmændz ɑɹ ɹɛɡjʊlɚɹ əkɜɹənsᵻz/","zh":"疯狂的要求经常发生！","en":"","note":""},{"id":"phantom-of-the-opera-09-221","lineIndex":216,"speaker":"","original":"Bliss or damnation?","ipa":"/blɪs ɔɹ dæmneɪʃən/","zh":"幸福还是诅咒？","en":"","note":""},{"id":"phantom-of-the-opera-09-222","lineIndex":217,"speaker":"","original":"Which has claimed her...?","ipa":"/wɪtʃ hɐz kleɪmd hɜ/","zh":"夺走了她的权利。。.？","en":"","note":""},{"id":"phantom-of-the-opera-09-223","lineIndex":218,"speaker":"","original":"Think how you'll shine in that final encore!","ipa":"/θɪŋk haʊ jul ʃaɪn ɪn ðæt faɪnəl ɑŋkɔɹ/","zh":"想想你将如何在最后的安可中大放异彩！","en":"","note":""},{"id":"phantom-of-the-opera-09-224","lineIndex":219,"speaker":"","original":"Sing, prima donna, once more!","ipa":"/sɪŋ pɹimə dɑnə wʌns mɔɹ/","zh":"首席女歌手，再唱一次！","en":"","note":""},{"id":"phantom-of-the-opera-09-225","lineIndex":220,"speaker":"","original":"Oh fools, to have flouted his warnings!","ipa":"/oʊ fulz tə hæv flaʊɾᵻd hɪz wɔɹnɪŋz/","zh":"噢，傻瓜们，竟然无视他的警告！","en":"","note":""},{"id":"phantom-of-the-opera-09-226","lineIndex":221,"speaker":"","original":"Surely, for her sake...","ipa":"/ʃʊɹli fɔɹ hɜ seɪk/","zh":"当然，为了她。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-227","lineIndex":222,"speaker":"","original":"Surely he'll strike back...","ipa":"/ʃʊɹli hil stɹaɪk bæk/","zh":"他肯定会反击的。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-228","lineIndex":223,"speaker":"","original":"Surely there'll be further scenes -","ipa":"/ʃʊɹli ðɛɹl bi fɜðɚ sinz/","zh":"肯定还会有更多场景 -","en":"","note":""},{"id":"phantom-of-the-opera-09-229","lineIndex":224,"speaker":"","original":"worse than this!","ipa":"/wɜs ðɐn ðɪs/","zh":"比这更糟糕！","en":"","note":""},{"id":"phantom-of-the-opera-09-230","lineIndex":225,"speaker":"","original":"Think, before these demands are rejected!","ipa":"/θɪŋk bᵻfɔɹ ðiz dᵻmændz ɑɹ ɹᵻdʒɛktᵻd/","zh":"在这些要求被拒绝之前想想吧！","en":"","note":""},{"id":"phantom-of-the-opera-09-231","lineIndex":226,"speaker":"","original":"... I must see these demands are rejected!","ipa":"/dɑt aɪ mʌst si ðiz dᵻmændz ɑɹ ɹᵻdʒɛktᵻd/","zh":"。。.我必须看到这些要求被拒绝！","en":"","note":""},{"id":"phantom-of-the-opera-09-232","lineIndex":227,"speaker":"","original":"... if his threats and demands are rejected!","ipa":"/ɪf hɪz θɹɛts ænd dᵻmændz ɑɹ ɹᵻdʒɛktᵻd/","zh":"。。。如果他的威胁和要求被拒绝！","en":"","note":""},{"id":"phantom-of-the-opera-09-233","lineIndex":228,"speaker":"","original":"Who'd believe a diva happy to relieve a chorus girl","ipa":"/hud bᵻliv ɐ divə hæpi tə ɹᵻliv ɐ kɔɹəs ɡɜl/","zh":"谁会相信一个女主角会很乐意去接替一个合唱团女孩","en":"","note":""},{"id":"phantom-of-the-opera-09-234","lineIndex":229,"speaker":"","original":"who's gone and slept with the patron?","ipa":"/huz ɡɔn ænd slɛpt wɪððə peɪtɹən/","zh":"谁已经和赞助人一起睡了？","en":"","note":""},{"id":"phantom-of-the-opera-09-235","lineIndex":230,"speaker":"","original":"Raoul and the soubrette, entwined in love's duet!","ipa":"/ɹeɪəʌl ænd ðə saʊbɹɛt ɛntwaɪnd ɪn lʌvz djuɛt/","zh":"拉乌尔和红娘子，交织在爱情的二重唱中！","en":"","note":""},{"id":"phantom-of-the-opera-09-236","lineIndex":231,"speaker":"","original":"Although he may demur, he must have been with her!","ipa":"/ɔlðoʊ hi meɪ dᵻmɜ hi mʌstɐv bɪn wɪð hɜ/","zh":"虽然他可能会反对，但他一定是和她在一起了！","en":"","note":""},{"id":"phantom-of-the-opera-09-237","lineIndex":232,"speaker":"","original":"Christine must be protected!","ipa":"/kɹɪstin mʌst bi pɹətɛktᵻd/","zh":"必须保护克里斯汀！","en":"","note":""},{"id":"phantom-of-the-opera-09-238","lineIndex":233,"speaker":"","original":"O, fortunata!","ipa":"/oʊ fɔɹtʃʊnɑɾə/","zh":"哦，幸运儿！","en":"","note":""},{"id":"phantom-of-the-opera-09-239","lineIndex":234,"speaker":"","original":"Non ancor abbandonata!","ipa":"/nɑn æŋkɚɹ æbɐndoʊnɑɾə/","zh":"不放弃！","en":"","note":""},{"id":"phantom-of-the-opera-09-240","lineIndex":235,"speaker":"","original":"You'd never get away with all this in a play","ipa":"/jud nɛvɚ ɡɛt ɐweɪ wɪð ɔl ðɪs ɪn ɐ pleɪ/","zh":"你永远不可能在戏剧中摆脱这一切","en":"","note":""},{"id":"phantom-of-the-opera-09-241","lineIndex":236,"speaker":"","original":"but if it's loudly sung and in a foreign tongue;","ipa":"/bʌt ɪf ɪts laʊdli sʌŋ ænd ɪn ɐ fɔɹən tʌŋ/","zh":"但如果它是用外语大声唱的；","en":"","note":""},{"id":"phantom-of-the-opera-09-242","lineIndex":237,"speaker":"","original":"it's just the sort of story audiences adore","ipa":"/ɪts dʒʌst ðə sɔɹt ʌv stɔɹi ɔdiənsᵻz ɐdɔɹ/","zh":"这正是观众喜爱的故事类型","en":"","note":""},{"id":"phantom-of-the-opera-09-243","lineIndex":238,"speaker":"","original":"in fact a perfect opera!","ipa":"/ɪn fækt ɐ pɜfɛkt ɑpɚɹə/","zh":"实际上是一部完美的歌剧！","en":"","note":""},{"id":"phantom-of-the-opera-09-244","lineIndex":239,"speaker":"","original":"His game is over!","ipa":"/hɪz ɡeɪm ɪz oʊvɚ/","zh":"他的游戏结束了！","en":"","note":""},{"id":"phantom-of-the-opera-09-245","lineIndex":240,"speaker":"","original":"This is a game you cannot hope to win!","ipa":"/ðɪs ɪz ɐ ɡeɪm ju kænɑt hoʊp tə wɪn/","zh":"这是一场你不可能获胜的游戏！","en":"","note":""},{"id":"phantom-of-the-opera-09-246","lineIndex":241,"speaker":"","original":"And in Box Five","ipa":"/ænd ɪn bɑks faɪv/","zh":"在第五箱中","en":"","note":""},{"id":"phantom-of-the-opera-09-247","lineIndex":242,"speaker":"","original":"a new game will begin...","ipa":"/ɐ nu ɡeɪm wɪl bɪɡɪn/","zh":"一场新游戏将开始。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-248","lineIndex":243,"speaker":"","original":"For, if his curse is on this opera...","ipa":"/fɔɹ ɪf hɪz kɜs ɪz ɔn ðɪs ɑpɚɹə/","zh":"因为，如果他的咒语是在这部歌剧上的话。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-249","lineIndex":244,"speaker":"","original":"But if his curse is on this opera...","ipa":"/bʌt ɪf hɪz kɜs ɪz ɔn ðɪs ɑpɚɹə/","zh":"但如果他的诅咒落在这部歌剧上的话。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-250","lineIndex":245,"speaker":"","original":"Prima donna, the world is at your feet!","ipa":"/pɹimə dɑnə ðə wɜld ɪz æt jʊɹ fit/","zh":"首席女士，世界就在你的脚下！","en":"","note":""},{"id":"phantom-of-the-opera-09-251","lineIndex":246,"speaker":"","original":"A nation waits, and how it hates to be cheated!","ipa":"/ɐ neɪʃən weɪts ænd haʊ ɪt heɪts təbi tʃiɾᵻd/","zh":"一个国家在等待，它多么讨厌被欺骗！","en":"","note":""},{"id":"phantom-of-the-opera-09-252","lineIndex":247,"speaker":"","original":"The stress that falls upon a famous prima donna!","ipa":"/ðə stɹɛs ðæt fɔlz əpɑn ɐ feɪməs pɹimə dɑnə/","zh":"著名首席女歌手承受的压力！","en":"","note":""},{"id":"phantom-of-the-opera-09-253","lineIndex":248,"speaker":"","original":"Terrible diseases, coughs and colds and sneezes!","ipa":"/tɛɹᵻbəl dɪzizᵻz kɔfs ænd koʊldz ænd snizᵻz/","zh":"可怕的疾病，咳嗽、感冒和打喷嚏！","en":"","note":""},{"id":"phantom-of-the-opera-09-254","lineIndex":249,"speaker":"","original":"Still, the dryest throat will reach the highest note","ipa":"/stɪl ðə dɹaɪɪst θɹoʊt wɪl ɹitʃ ðə haɪɪst noʊt/","zh":"尽管如此，最干燥的喉咙也会达到最高音","en":"","note":""},{"id":"phantom-of-the-opera-09-255","lineIndex":250,"speaker":"","original":"in search of perfect opera!","ipa":"/ɪn sɜtʃ ʌv pɜfɛkt ɑpɚɹə/","zh":"寻找完美的歌剧！","en":"","note":""},{"id":"phantom-of-the-opera-09-256","lineIndex":251,"speaker":"","original":"... then I fear the outcome...","ipa":"/ðɛn aɪ fɪɹ ðɪ aʊtkʌm/","zh":"。。。然后我就害怕这个结果。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-257","lineIndex":252,"speaker":"","original":"Christine plays the Pageboy","ipa":"/kɹɪstin pleɪz ðə peɪdʒbɔɪ/","zh":"克里斯汀扮演侍童","en":"","note":""},{"id":"phantom-of-the-opera-09-258","lineIndex":253,"speaker":"","original":"Carlotta plays the Countess...","ipa":"/kɑɹlɑɾə pleɪz ðə kaʊntɛs/","zh":"卡洛塔扮演伯爵夫人。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-259","lineIndex":254,"speaker":"","original":"... should you dare to..","ipa":"/ʃʊd ju dɛɹ tu/","zh":"。。。你敢吗？。","en":"","note":""},{"id":"phantom-of-the-opera-09-260","lineIndex":255,"speaker":"","original":"... when you once again...","ipa":"/wɛn ju wʌns ɐɡɛn/","zh":"。。。当你再次。。。","en":"","note":""},{"id":"phantom-of-the-opera-09-261","lineIndex":256,"speaker":"","original":"Light up the stage with that age old rapport!","ipa":"/laɪt ʌp ðə steɪdʒ wɪð ðæt eɪdʒ oʊld ɹæpɔɹ/","zh":"用古老的融洽气氛点亮舞台！","en":"","note":""},{"id":"phantom-of-the-opera-09-262","lineIndex":257,"speaker":"","original":"Sing, prima donna, once more!","ipa":"/sɪŋ pɹimə dɑnə wʌns mɔɹ/","zh":"首席女歌手，再唱一次！","en":"","note":""},{"id":"phantom-of-the-opera-09-263","lineIndex":258,"speaker":"","original":"So, it is to be war between us! If these demands are not","ipa":"/soʊ ɪɾ ɪz təbi wɔɹ bᵻtwin ʌs ɪf ðiz dᵻmændz ɑɹ nɑt/","zh":"所以，我们之间即将爆发战争！如果这些要求得不到","en":"","note":""},{"id":"phantom-of-the-opera-09-264","lineIndex":259,"speaker":"","original":"met, a disaster beyond your imagination will occur!","ipa":"/mɛt ɐ dɪzæstɚ bᵻjɔnd jʊɹ ɪmædʒᵻneɪʃən wɪl əkɜ/","zh":"的满足，超乎你想象的灾难将会发生！","en":"","note":""},{"id":"phantom-of-the-opera-09-265","lineIndex":260,"speaker":"","original":"Once more!","ipa":"/wʌns mɔɹ/","zh":"再来一次！","en":"","note":""}],"sourceOrder":9,"displayOrder":9},{"order":10,"id":"10-poor-fool-he-makes-me-laugh-live","title":"Poor Fool, He Makes Me Laugh","titleZh":"可怜的傻瓜，他逗我发笑","lines":[{"id":"phantom-of-the-opera-10-001","lineIndex":1,"speaker":"","original":"Poor Fool, He Makes Me Laugh","ipa":"/pʊɹ ful hi meɪks mi læf/","zh":"可怜的傻瓜，他让我发笑","en":"","note":""},{"id":"phantom-of-the-opera-10-003","lineIndex":2,"speaker":"RAOUL","original":"Gentlemen, if you would care to take your seats...","ipa":"/dʒɛntəlmən ɪf ju wʊd kɛɹ tə teɪk jʊɹ sits/","zh":"先生们，请入座...","en":"","note":""},{"id":"phantom-of-the-opera-10-004","lineIndex":3,"speaker":"","original":"I shall be sitting in Box Five.","ipa":"/aɪʃɐl bi sɪɾɪŋ ɪn bɑks faɪv/","zh":"我将坐在五号包厢","en":"","note":""},{"id":"phantom-of-the-opera-10-006","lineIndex":4,"speaker":"ANDRE","original":"Do you really think that's wise, monsieur?","ipa":"/du ju ɹiəli θɪŋk ðæts waɪz məsjɜ/","zh":"您真觉得这明智吗，先生？","en":"","note":""},{"id":"phantom-of-the-opera-10-008","lineIndex":5,"speaker":"RAOUL","original":"My dear Andre","ipa":"/maɪ dɪɹ ɑndɹeɪ/","zh":"亲爱的安德烈","en":"","note":""},{"id":"phantom-of-the-opera-10-009","lineIndex":6,"speaker":"","original":"there would appear to be no seats available other than Box Five.","ipa":"/ðɛɹ wʊd ɐpɪɹ təbi noʊ sits ɐveɪləbəl ʌðɚ ðɐn bɑks faɪv/","zh":"除了五号包厢已无其他空位","en":"","note":""},{"id":"phantom-of-the-opera-10-011","lineIndex":7,"speaker":"CONFIDANTE","original":"They say that this youth has set my Lady's heart aflame!","ipa":"/ðeɪ seɪ ðæt ðɪs juθ hɐz sɛt maɪ leɪdɪʃɑɹt ɐfleɪm/","zh":"他们说这年轻人点燃了我家夫人的心！","en":"","note":""},{"id":"phantom-of-the-opera-10-013","lineIndex":8,"speaker":"1ST FOP","original":"His Lordship sure would die of shock!","ipa":"/hɪz lɔɹdʃɪp ʃʊɹ wʊd daɪ ʌv ʃɑk/","zh":"老爷知道定会气昏头！","en":"","note":""},{"id":"phantom-of-the-opera-10-015","lineIndex":9,"speaker":"2ND FOP","original":"His Lordship is a laughing-st ock!","ipa":"/hɪz lɔɹdʃɪp ɪz ɐ læfɪŋsənt ɑk/","zh":"老爷就是个大笑话！","en":"","note":""},{"id":"phantom-of-the-opera-10-017","lineIndex":10,"speaker":"CONFIDANTE","original":"Should he suspect her, God protect her!","ipa":"/ʃʊd hi sʌspɛkt hɜ ɡɑd pɹətɛkt hɜ/","zh":"若他起疑心，愿主保佑她！","en":"","note":""},{"id":"phantom-of-the-opera-10-019","lineIndex":11,"speaker":"ALL THREE","original":"Shame! Shame! Shame!","ipa":"/ʃeɪm ʃeɪm ʃeɪm/","zh":"可耻！可耻！可耻！","en":"","note":""},{"id":"phantom-of-the-opera-10-020","lineIndex":12,"speaker":"","original":"This faithless lady's bound for Hades!","ipa":"/ðɪs feɪθləs leɪdiz baʊnd fɔɹ heɪdiz/","zh":"这负心妇人该下地狱！","en":"","note":""},{"id":"phantom-of-the-opera-10-021","lineIndex":13,"speaker":"","original":"Shame! Shame! Shame!","ipa":"/ʃeɪm ʃeɪm ʃeɪm/","zh":"可耻！可耻！可耻！","en":"","note":""},{"id":"phantom-of-the-opera-10-023","lineIndex":14,"speaker":"ANDRE","original":"Nothing like the old operas!","ipa":"/nʌθɪŋ laɪk ðɪ oʊld ɑpɚɹəz/","zh":"还是老歌剧够味！","en":"","note":""},{"id":"phantom-of-the-opera-10-025","lineIndex":15,"speaker":"FIRMIN","original":"Or the old scenery...","ipa":"/ɔɹ ðɪ oʊld sinɚɹi/","zh":"还有老布景...","en":"","note":""},{"id":"phantom-of-the-opera-10-027","lineIndex":16,"speaker":"ANDRE","original":"The old singers...","ipa":"/ðɪ oʊld sɪŋɚz/","zh":"老歌手们...","en":"","note":""},{"id":"phantom-of-the-opera-10-029","lineIndex":17,"speaker":"FIRMIN","original":"The old audience...","ipa":"/ðɪ oʊld ɔdiəns/","zh":"老观众们...","en":"","note":""},{"id":"phantom-of-the-opera-10-031","lineIndex":18,"speaker":"ANDRE","original":"And every seat sold!","ipa":"/ænd ɛvɹi sit soʊld/","zh":"座无虚席！","en":"","note":""},{"id":"phantom-of-the-opera-10-033","lineIndex":19,"speaker":"FIRMIN","original":"Hardly a disaster beyond all imagination!","ipa":"/hɑɹdli ɐ dɪzæstɚ bᵻjɔnd ɔl ɪmædʒᵻneɪʃən/","zh":"这哪算得上什么灾难！","en":"","note":""},{"id":"phantom-of-the-opera-10-035","lineIndex":20,"speaker":"COUNTESS","original":"Serafimo - your disguise is perfect.","ipa":"/sɛɹɐfɪmoʊ jʊɹ dɪsɡaɪz ɪz pɜfɛkt/","zh":"塞拉菲莫—你的伪装完美无缺","en":"","note":""},{"id":"phantom-of-the-opera-10-036","lineIndex":21,"speaker":"","original":"Who can this be?","ipa":"/hu kæn ðɪs bi/","zh":"这会是谁呢？","en":"","note":""},{"id":"phantom-of-the-opera-10-038","lineIndex":22,"speaker":"DON ATTILIO","original":"Gentle wife, admit your loving husband.","ipa":"/dʒɛntəl waɪf ɐdmɪt jʊɹ lʌvɪŋ hʌsbənd/","zh":"爱妻，快给你深情的丈夫开门","en":"","note":""},{"id":"phantom-of-the-opera-10-039","lineIndex":23,"speaker":"","original":"My love - I am called to England on affairs of State","ipa":"/maɪ lʌv aɪɐm kɔld tʊ ɪŋɡlənd ɔn ɐfɛɹz ʌv steɪt/","zh":"亲爱的—我要去英国处理国务","en":"","note":""},{"id":"phantom-of-the-opera-10-040","lineIndex":24,"speaker":"","original":"and must leave you with your new maid.","ipa":"/ænd mʌst liv ju wɪð jʊɹ nu meɪd/","zh":"只能留你和新女仆作伴了","en":"","note":""},{"id":"phantom-of-the-opera-10-041","lineIndex":25,"speaker":"","original":"(Aside) Though I'd gladly take the maid with me.","ipa":"/ɐsaɪd ðoʊ aɪd ɡlædli teɪk ðə meɪd wɪð mi/","zh":"（旁白） 虽然我更想带走那女仆","en":"","note":""},{"id":"phantom-of-the-opera-10-043","lineIndex":26,"speaker":"COUNTESS","original":"(aside) The old fool's leaving!","ipa":"/ɐsaɪd ðɪ oʊld fulz livɪŋ/","zh":"（旁白）老傻瓜要走了！","en":"","note":""},{"id":"phantom-of-the-opera-10-045","lineIndex":27,"speaker":"DON ATTILI0","original":"(aside) I suspect my young bride is untrue to me.","ipa":"/ɐsaɪd aɪ səspɛkt maɪ jʌŋ bɹaɪd ɪz ʌntɹu tə mi/","zh":"（旁白）我怀疑年轻妻子对我不忠","en":"","note":""},{"id":"phantom-of-the-opera-10-046","lineIndex":28,"speaker":"","original":"I shall not leave, but shall hide over there to observe her!","ipa":"/aɪʃɐl nɑt liv bʌt ʃæl haɪd oʊvɚ ðɛɹ tʊ əbzɜv hɜ/","zh":"我不走了，要躲起来监视她！","en":"","note":""},{"id":"phantom-of-the-opera-10-047","lineIndex":29,"speaker":"","original":"Addio!","ipa":"/ædɪoʊ/","zh":"再见！","en":"","note":""},{"id":"phantom-of-the-opera-10-049","lineIndex":30,"speaker":"COUNTESS","original":"Addio!","ipa":"/ædɪoʊ/","zh":"再见！","en":"","note":""},{"id":"phantom-of-the-opera-10-051","lineIndex":31,"speaker":"BOTH","original":"Addio!","ipa":"/ædɪoʊ/","zh":"再见！","en":"","note":""},{"id":"phantom-of-the-opera-10-053","lineIndex":32,"speaker":"CARLOTTA","original":"Serafimo! Away with this pretense!","ipa":"/sɛɹɐfɪmoʊ ɐweɪ wɪð ðɪs pɹitɛns/","zh":"塞拉菲莫！别装了！","en":"","note":""},{"id":"phantom-of-the-opera-10-054","lineIndex":33,"speaker":"","original":"You cannot speak, but kiss me in my husband's absence!","ipa":"/ju kænɑt spik bʌt kɪs mi ɪn maɪ hʌsbəndz æbsəns/","zh":"你不能说话，就趁丈夫不在吻我吧！","en":"","note":""},{"id":"phantom-of-the-opera-10-055","lineIndex":34,"speaker":"","original":"Poor fool, he makes me laugh!","ipa":"/pʊɹ ful hi meɪks mi læf/","zh":"可怜的傻瓜，他让我发笑！","en":"","note":""},{"id":"phantom-of-the-opera-10-056","lineIndex":35,"speaker":"","original":"Time I tried to get a better better half!","ipa":"/taɪm aɪ tɹaɪd tə ɡɛt ɐ bɛɾɚ bɛɾɚ hæf/","zh":"是时候找个更好的伴侣了！","en":"","note":""},{"id":"phantom-of-the-opera-10-057","lineIndex":36,"speaker":"","original":"Poor fool, he doesn't know!","ipa":"/pʊɹ ful hi dʌzənt noʊ/","zh":"可怜的傻瓜，他毫不知情！","en":"","note":""},{"id":"phantom-of-the-opera-10-058","lineIndex":37,"speaker":"","original":"If he knew, the fool, he never would have gone!","ipa":"/ɪf hi nu ðə ful hi nɛvɚ wʊdhɐv ɡɔn/","zh":"若他知道，这傻瓜绝不会离开！","en":"","note":""},{"id":"phantom-of-the-opera-10-060","lineIndex":38,"speaker":"PHANTOM","original":"Did I not instruct that Box Five was to be kept empty?","ipa":"/dɪd aɪ nɑt ɪnstɹʌkt ðæt bɑks faɪv wʌz təbi kɛpt ɛmpti/","zh":"我不是说过五号包厢必须空着吗？","en":"","note":""},{"id":"phantom-of-the-opera-10-062","lineIndex":39,"speaker":"MEG","original":"He's here: the Phantom of the Opera...","ipa":"/hiz hɪɹ ðə fæntəm ʌvðɪ ɑpɚɹə/","zh":"他来了：歌剧院的魅影...","en":"","note":""},{"id":"phantom-of-the-opera-10-064","lineIndex":40,"speaker":"CHRISTINE","original":"It's him! I know it, it's him!","ipa":"/ɪts hɪm aɪ noʊ ɪt ɪts hɪm/","zh":"是他！我知道，就是他！","en":"","note":""},{"id":"phantom-of-the-opera-10-066","lineIndex":41,"speaker":"CARLOTTA","original":"Your part is silent... little toad!","ipa":"/jʊɹ pɑɹt ɪz saɪlənt lɪɾəl toʊd/","zh":"你的角色是哑巴...小癞蛤蟆！","en":"","note":""},{"id":"phantom-of-the-opera-10-068","lineIndex":42,"speaker":"PHANTOM","original":"A toad, madame? Perhaps it is you who are the toad!","ipa":"/ɐ toʊd mædəm pɚhæps ɪɾ ɪz ju hu ɑɹ ðə toʊd/","zh":"蛤蟆，夫人？或许你才是蛤蟆！","en":"","note":""},{"id":"phantom-of-the-opera-10-070","lineIndex":43,"speaker":"CARLOTTA","original":"Serafimo! Away with this pretense!","ipa":"/sɛɹɐfɪmoʊ ɐweɪ wɪð ðɪs pɹitɛns/","zh":"塞拉菲莫！别装了！","en":"","note":""},{"id":"phantom-of-the-opera-10-071","lineIndex":44,"speaker":"","original":"You cannot speak, but kiss me in my... croak!","ipa":"/ju kænɑt spik bʌt kɪs mi ɪn maɪ kɹoʊk/","zh":"你不能说话，就趁我...呱！","en":"","note":""},{"id":"phantom-of-the-opera-10-072","lineIndex":45,"speaker":"","original":"Poor fool, he makes me laugh! Croak! Croak!","ipa":"/pʊɹ ful hi meɪks mi læf kɹoʊk kɹoʊk/","zh":"可怜的傻瓜，他让我发笑！呱！呱！","en":"","note":""},{"id":"phantom-of-the-opera-10-074","lineIndex":46,"speaker":"PHANTOM","original":"Behold! She is singing to bring down the chandelier!","ipa":"/bᵻhoʊld ʃi ɪz sɪŋɪŋ tə bɹɪŋ daʊn ðə ʃændəlɪɹ/","zh":"看哪！她的歌声要震落吊灯了！","en":"","note":""},{"id":"phantom-of-the-opera-10-076","lineIndex":47,"speaker":"ANDRE","original":"Ladies and gentlemen","ipa":"/leɪdiz ænd dʒɛntəlmən/","zh":"女士们先生们","en":"","note":""},{"id":"phantom-of-the-opera-10-077","lineIndex":48,"speaker":"","original":"the performance will continue in ten minutes time","ipa":"/ðə pɚfɔɹməns wɪl kəntɪnju ɪn tɛn mɪnɪts taɪm/","zh":"演出将在十分钟后继续","en":"","note":""},{"id":"phantom-of-the-opera-10-078","lineIndex":49,"speaker":"","original":"when the role of the Countess will be sung by Miss Christine Daae.","ipa":"/wɛn ðə ɹoʊl ʌvðə kaʊntɛs wɪl bi sʌŋ baɪ mɪs kɹɪstin dɑ/","zh":"伯爵夫人角色将由克里斯汀·戴伊小姐演唱","en":"","note":""},{"id":"phantom-of-the-opera-10-079","lineIndex":50,"speaker":"","original":"In the meantime, ladies and gentlemen, we shall be giving you the ballet from Act","ipa":"/ɪnðə mintaɪm leɪdiz ænd dʒɛntəlmən wiʃɐl bi ɡɪvɪŋ ju ðə bæleɪ fɹʌm ækt/","zh":"在此期间，我们将为您献上今晚歌剧","en":"","note":""},{"id":"phantom-of-the-opera-10-080","lineIndex":51,"speaker":"","original":"Three of tonight's opera.","ipa":"/θɹi ʌv tənaɪts ɑpɚɹə/","zh":"第三幕的芭蕾舞段","en":"","note":""},{"id":"phantom-of-the-opera-10-081","lineIndex":52,"speaker":"","original":"Maestro, the ballet, NOW!","ipa":"/maɪstɹoʊ ðə bæleɪ naʊ/","zh":"大师，现在开始芭蕾！","en":"","note":""},{"id":"phantom-of-the-opera-10-083","lineIndex":53,"speaker":"CHRISTINE","original":"Raoul! Raoul!","ipa":"/ɹeɪəʌl ɹeɪəʌl/","zh":"拉乌尔！拉乌尔！","en":"","note":""},{"id":"phantom-of-the-opera-10-085","lineIndex":54,"speaker":"RAOUL","original":"Christine! Come with me!","ipa":"/kɹɪstin kʌm wɪð mi/","zh":"克里斯汀！跟我走！","en":"","note":""},{"id":"phantom-of-the-opera-10-087","lineIndex":55,"speaker":"CHRISTINE","original":"No, we must go up! To the roof!","ipa":"/noʊ wi mʌst ɡoʊ ʌp tə ðə ɹuf/","zh":"不，我们必须上去！到屋顶！","en":"","note":""},{"id":"phantom-of-the-opera-10-089","lineIndex":56,"speaker":"ANDRE","original":"Ladies and gentlemen, please! Remain in your seats! Do not panic! It was an accident","ipa":"/leɪdiz ænd dʒɛntəlmən pliz ɹᵻmeɪn ɪn jʊɹ sits dunɑt pænɪk ɪt wʌz ɐn æksɪdənt/","zh":"女士们先生们，请保持镇静！留在座位上！别惊慌！这只是意外","en":"","note":""},{"id":"phantom-of-the-opera-10-090","lineIndex":57,"speaker":"","original":"simply an accident!","ipa":"/sɪmpli ɐn æksɪdənt/","zh":"仅仅是个意外！","en":"","note":""}],"sourceOrder":10,"displayOrder":10},{"order":11,"id":"11-why-have-you-brought-me-here-live","title":"Why Have You Brought Me Here","titleZh":"你为何带我来这里","lines":[{"id":"phantom-of-the-opera-11-001","lineIndex":1,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-002","lineIndex":2,"speaker":"","original":"Why have you brought us here?","ipa":"/waɪ hæv ju bɹɔt ʌs hɪɹ/","zh":"你为什么把我们带到这里来？","en":"","note":""},{"id":"phantom-of-the-opera-11-003","lineIndex":3,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-004","lineIndex":4,"speaker":"","original":"Don't take me back there!","ipa":"/doʊnt teɪk mi bæk ðɛɹ/","zh":"不要带我回去！","en":"","note":""},{"id":"phantom-of-the-opera-11-005","lineIndex":5,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-006","lineIndex":6,"speaker":"","original":"We must return!","ipa":"/wi mʌst ɹᵻtɜn/","zh":"我们必须回去！","en":"","note":""},{"id":"phantom-of-the-opera-11-007","lineIndex":7,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-008","lineIndex":8,"speaker":"","original":"He'll kill me!","ipa":"/hil kɪl mi/","zh":"他会杀了我！","en":"","note":""},{"id":"phantom-of-the-opera-11-009","lineIndex":9,"speaker":"","original":"His eyes will find you there!","ipa":"/hɪz aɪz wɪl faɪnd ju ðɛɹ/","zh":"他的双眼会窥视到你！","en":"","note":""},{"id":"phantom-of-the-opera-11-010","lineIndex":10,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-011","lineIndex":11,"speaker":"","original":"Christine, don't say that.","ipa":"/kɹɪstin doʊnt seɪ ðæt/","zh":"克里斯汀，不要这么说。","en":"","note":""},{"id":"phantom-of-the-opera-11-012","lineIndex":12,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-013","lineIndex":13,"speaker":"","original":"Those eyes that burn!","ipa":"/ðoʊz aɪz ðæt bɜn/","zh":"他那燃烧着愤怒的双眼！","en":"","note":""},{"id":"phantom-of-the-opera-11-014","lineIndex":14,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-015","lineIndex":15,"speaker":"","original":"Don't even think it","ipa":"/doʊnt ivən θɪŋk ɪt/","zh":"这些事情想都不要去想","en":"","note":""},{"id":"phantom-of-the-opera-11-016","lineIndex":16,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-017","lineIndex":17,"speaker":"","original":"And if he has to kill a thousand men","ipa":"/ænd ɪf hi hɐz tə kɪl ɐ θaʊzənd mɛn/","zh":"假如他想无止尽的杀人","en":"","note":""},{"id":"phantom-of-the-opera-11-018","lineIndex":18,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-019","lineIndex":19,"speaker":"","original":"Forget this waking nightmare...","ipa":"/fɚɡɛt ðɪs weɪkɪŋ naɪtmɛɹ/","zh":"忘掉这个噩梦……","en":"","note":""},{"id":"phantom-of-the-opera-11-020","lineIndex":20,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-021","lineIndex":21,"speaker":"","original":"The Phantom of the Opera will kill...","ipa":"/ðə fæntəm ʌvðɪ ɑpɚɹə wɪl kɪl/","zh":"剧院魅影会杀戮……","en":"","note":""},{"id":"phantom-of-the-opera-11-022","lineIndex":22,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-023","lineIndex":23,"speaker":"","original":"This phantom is a fable","ipa":"/ðɪs fæntəm ɪz ɐ feɪbəl/","zh":"魅影只是个传说","en":"","note":""},{"id":"phantom-of-the-opera-11-024","lineIndex":24,"speaker":"","original":"Believe me","ipa":"/bᵻliv mi/","zh":"相信我","en":"","note":""},{"id":"phantom-of-the-opera-11-025","lineIndex":25,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-026","lineIndex":26,"speaker":"","original":"...and kill again!","ipa":"/ænd kɪl ɐɡɛn/","zh":"……再一次大开杀戒！","en":"","note":""},{"id":"phantom-of-the-opera-11-027","lineIndex":27,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-028","lineIndex":28,"speaker":"","original":"There is no Phantom of the Opera","ipa":"/ðɛɹ ɪz noʊ fæntəm ʌvðɪ ɑpɚɹə/","zh":"根本就没有剧院魅影","en":"","note":""},{"id":"phantom-of-the-opera-11-029","lineIndex":29,"speaker":"","original":"BOTH","ipa":"/boʊθ/","zh":"合唱","en":"","note":""},{"id":"phantom-of-the-opera-11-030","lineIndex":30,"speaker":"","original":"My God, who is this man...","ipa":"/maɪ ɡɑd hu ɪz ðɪs mæn/","zh":"天哪，这个恶魔到底是谁……","en":"","note":""},{"id":"phantom-of-the-opera-11-031","lineIndex":31,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-032","lineIndex":32,"speaker":"","original":"...who hunts to kill?","ipa":"/hu hʌnts tə kɪl/","zh":"……是谁在猎捕追杀？","en":"","note":""},{"id":"phantom-of-the-opera-11-033","lineIndex":33,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-034","lineIndex":34,"speaker":"","original":"...this mask of death?","ipa":"/ðɪs mæsk ʌv dɛθ/","zh":"……是谁藏在死神的面具下？","en":"","note":""},{"id":"phantom-of-the-opera-11-035","lineIndex":35,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-036","lineIndex":36,"speaker":"","original":"I can't escape from him...","ipa":"/aɪ kænt ɛskeɪp fɹʌm hɪm/","zh":"我躲不掉他这一劫……","en":"","note":""},{"id":"phantom-of-the-opera-11-037","lineIndex":37,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-038","lineIndex":38,"speaker":"","original":"Whose is this voice you hear...","ipa":"/huz ɪz ðɪs vɔɪs ju hɪɹ/","zh":"你听到的究竟是谁的声音……","en":"","note":""},{"id":"phantom-of-the-opera-11-039","lineIndex":39,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-040","lineIndex":40,"speaker":"","original":"... I never will!","ipa":"/aɪ nɛvɚ wɪl/","zh":"……我永远逃不掉！","en":"","note":""},{"id":"phantom-of-the-opera-11-041","lineIndex":41,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-042","lineIndex":42,"speaker":"","original":"...with every breath?","ipa":"/wɪð ɛvɹi bɹɛθ/","zh":"……交融在你的呼吸中？","en":"","note":""},{"id":"phantom-of-the-opera-11-043","lineIndex":43,"speaker":"","original":"BOTH","ipa":"/boʊθ/","zh":"合唱","en":"","note":""},{"id":"phantom-of-the-opera-11-044","lineIndex":44,"speaker":"","original":"And in this labyrinth","ipa":"/ænd ɪn ðɪs læbɚɹɪnθ/","zh":"而在这绝望的迷惘中","en":"","note":""},{"id":"phantom-of-the-opera-11-045","lineIndex":45,"speaker":"","original":"where night is blind","ipa":"/wɛɹ naɪt ɪz blaɪnd/","zh":"连夜色也变得盲目","en":"","note":""},{"id":"phantom-of-the-opera-11-046","lineIndex":46,"speaker":"","original":"the Phantom of the Opera is here/there","ipa":"/ðə fæntəm ʌvðɪ ɑpɚɹə ɪz hɪɹ slæʃ ðɛɹ/","zh":"剧院魅影就在这里/那里","en":"","note":""},{"id":"phantom-of-the-opera-11-047","lineIndex":47,"speaker":"","original":"inside my/your mind...","ipa":"/ɪnsaɪd maɪ slæʃ jʊɹ maɪnd/","zh":"就在我/你脑海中……","en":"","note":""},{"id":"phantom-of-the-opera-11-048","lineIndex":48,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-049","lineIndex":49,"speaker":"","original":"There is no Phantom of the Opera...","ipa":"/ðɛɹ ɪz noʊ fæntəm ʌvðɪ ɑpɚɹə/","zh":"根本没有什么剧院魅影……","en":"","note":""},{"id":"phantom-of-the-opera-11-050","lineIndex":50,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-051","lineIndex":51,"speaker":"","original":"Raoul, I've been there","ipa":"/ɹeɪəʌl aɪv bɪn ðɛɹ/","zh":"拉乌尔，我曾站在那里","en":"","note":""},{"id":"phantom-of-the-opera-11-052","lineIndex":52,"speaker":"","original":"to his world of unending night","ipa":"/tə hɪz wɜld ʌv ʌnɛndɪŋ naɪt/","zh":"在他无尽黑暗的世界中","en":"","note":""},{"id":"phantom-of-the-opera-11-053","lineIndex":53,"speaker":"","original":"To a world with the daylight dissolves into darkness...","ipa":"/tʊ ɐ wɜld wɪððə deɪlaɪt dɪsɑlvz ɪntʊ dɑɹknəs/","zh":"他那连日光都会黯淡的黑暗……","en":"","note":""},{"id":"phantom-of-the-opera-11-054","lineIndex":54,"speaker":"","original":"darkness...","ipa":"/dɑɹknəs/","zh":"绝望的黑暗……","en":"","note":""},{"id":"phantom-of-the-opera-11-055","lineIndex":55,"speaker":"","original":"Raoul, I've seen him!","ipa":"/ɹeɪəʌl aɪv sin hɪm/","zh":"拉乌尔，我见过他！","en":"","note":""},{"id":"phantom-of-the-opera-11-056","lineIndex":56,"speaker":"","original":"Can I ever forget that sight?","ipa":"/kæn aɪ ɛvɚ fɚɡɛt ðæt saɪt/","zh":"难道我能忘记那可怕的景象？","en":"","note":""},{"id":"phantom-of-the-opera-11-057","lineIndex":57,"speaker":"","original":"Can I ever escape from that face?","ipa":"/kæn aɪ ɛvɚɹ ɛskeɪp fɹʌm ðæt feɪs/","zh":"我还能逃离那张脸吗？","en":"","note":""},{"id":"phantom-of-the-opera-11-058","lineIndex":58,"speaker":"","original":"So distorted, deformed, it was hardly a face","ipa":"/soʊ dɪstɔɹɾᵻd dᵻfɔɹmd ɪt wʌz hɑɹdli ɐ feɪs/","zh":"那么扭曲、畸形，那几乎不能被称作脸","en":"","note":""},{"id":"phantom-of-the-opera-11-059","lineIndex":59,"speaker":"","original":"in that darkness...","ipa":"/ɪn ðæt dɑɹknəs/","zh":"在黑暗中……","en":"","note":""},{"id":"phantom-of-the-opera-11-060","lineIndex":60,"speaker":"","original":"darkness...","ipa":"/dɑɹknəs/","zh":"无止境的黑暗……","en":"","note":""},{"id":"phantom-of-the-opera-11-061","lineIndex":61,"speaker":"","original":"But his voice filled my spirit","ipa":"/bʌt hɪz vɔɪs fɪld maɪ spɪɹɪt/","zh":"但他的歌声充盈着我的灵魂","en":"","note":""},{"id":"phantom-of-the-opera-11-062","lineIndex":62,"speaker":"","original":"with a strange, sweet sound...","ipa":"/wɪð ɐ stɹeɪndʒ swit saʊnd/","zh":"那奇异而美妙的歌声……","en":"","note":""},{"id":"phantom-of-the-opera-11-063","lineIndex":63,"speaker":"","original":"In that night there was music in my mind...","ipa":"/ɪn ðæt naɪt ðɛɹwʌz mjuzɪk ɪn maɪ maɪnd/","zh":"那一夜，我心深处充斥着音乐……","en":"","note":""},{"id":"phantom-of-the-opera-11-064","lineIndex":64,"speaker":"","original":"And through music my soul began to soar!","ipa":"/ænd θɹu mjuzɪk maɪ soʊl bɪɡæn tə sɔɹ/","zh":"而我的灵魂随着歌声开始翱翔！","en":"","note":""},{"id":"phantom-of-the-opera-11-065","lineIndex":65,"speaker":"","original":"And I heard as I'd never heard before...","ipa":"/ænd aɪ hɜd æz aɪd nɛvɚ hɜd bᵻfɔɹ/","zh":"我听到从未享受过的音乐……","en":"","note":""},{"id":"phantom-of-the-opera-11-066","lineIndex":66,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-067","lineIndex":67,"speaker":"","original":"What you heard was a dream and nothing more...","ipa":"/wʌt ju hɜd wʌzɐ dɹim ænd nʌθɪŋ mɔɹ/","zh":"你什么都没听到，至多不过是个美丽的梦……","en":"","note":""},{"id":"phantom-of-the-opera-11-068","lineIndex":68,"speaker":"","original":"CHRISTINE","ipa":"/kɹɪstin/","zh":"克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-11-069","lineIndex":69,"speaker":"","original":"Yet in his eyes","ipa":"/jɛt ɪn hɪz aɪz/","zh":"然而在他的眼中","en":"","note":""},{"id":"phantom-of-the-opera-11-070","lineIndex":70,"speaker":"","original":"all the sadness of the world","ipa":"/ɔl ðə sædnəs ʌvðə wɜld/","zh":"有着世间所有的悲伤","en":"","note":""},{"id":"phantom-of-the-opera-11-071","lineIndex":71,"speaker":"","original":"Those pleading eyes","ipa":"/ðoʊz plidɪŋ aɪz/","zh":"那乞求的双眼","en":"","note":""},{"id":"phantom-of-the-opera-11-072","lineIndex":72,"speaker":"","original":"that both threaten and adore","ipa":"/ðæt boʊθ θɹɛʔn̩ ænd ɐdɔɹ/","zh":"让人那么害怕，却那么爱慕","en":"","note":""},{"id":"phantom-of-the-opera-11-073","lineIndex":73,"speaker":"","original":"RAOUL","ipa":"/ɹeɪəʌl/","zh":"拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-11-074","lineIndex":74,"speaker":"","original":"Christine...","ipa":"/kɹɪstin/","zh":"克里斯汀……","en":"","note":""},{"id":"phantom-of-the-opera-11-075","lineIndex":75,"speaker":"","original":"Christine...","ipa":"/kɹɪstin/","zh":"克里斯汀……","en":"","note":""},{"id":"phantom-of-the-opera-11-076","lineIndex":76,"speaker":"","original":"PHANTOM","ipa":"/fæntəm/","zh":"魅影","en":"","note":""},{"id":"phantom-of-the-opera-11-077","lineIndex":77,"speaker":"","original":"Christine...","ipa":"/kɹɪstin/","zh":"克里斯汀……","en":"","note":""}],"sourceOrder":11,"displayOrder":11},{"order":12,"id":"12-all-i-ask-of-you-live","title":"All I Ask Of You","titleZh":"我对你唯一的请求","lines":[{"id":"phantom-of-the-opera-12-001","lineIndex":1,"speaker":"","original":"No more talk of darkness","ipa":"/noʊmɔɹ tɔk ʌv dɑɹknəs/","zh":"莫再言及黑暗","en":"","note":""},{"id":"phantom-of-the-opera-12-002","lineIndex":2,"speaker":"","original":"Forget these wide-eyed fears","ipa":"/fɚɡɛt ðiz waɪdaɪd fɪɹz/","zh":"忘了这些令人瞠目结舌的恐惧","en":"","note":""},{"id":"phantom-of-the-opera-12-003","lineIndex":3,"speaker":"","original":"I'm here","ipa":"/aɪm hɪɹ/","zh":"我在此","en":"","note":""},{"id":"phantom-of-the-opera-12-004","lineIndex":4,"speaker":"","original":"Nothing can harm you","ipa":"/nʌθɪŋ kæn hɑɹm ju/","zh":"没什么能伤害你","en":"","note":""},{"id":"phantom-of-the-opera-12-005","lineIndex":5,"speaker":"","original":"My words will warm and calm you","ipa":"/maɪ wɜdz wɪl wɔɹm ænd kɑm ju/","zh":"我的话语将温暖你、平静你","en":"","note":""},{"id":"phantom-of-the-opera-12-006","lineIndex":6,"speaker":"","original":"Let me be your freedom","ipa":"/lɛt mi bi jʊɹ fɹidəm/","zh":"让我成为你的自由","en":"","note":""},{"id":"phantom-of-the-opera-12-007","lineIndex":7,"speaker":"","original":"Let daylight dry your tears","ipa":"/lɛt deɪlaɪt dɹaɪ jʊɹ tɪɹz/","zh":"让日光擦干你的泪水","en":"","note":""},{"id":"phantom-of-the-opera-12-008","lineIndex":8,"speaker":"","original":"I'm here","ipa":"/aɪm hɪɹ/","zh":"我在此","en":"","note":""},{"id":"phantom-of-the-opera-12-009","lineIndex":9,"speaker":"","original":"With you, beside you","ipa":"/wɪð ju bᵻsaɪd ju/","zh":"伴随在你身旁","en":"","note":""},{"id":"phantom-of-the-opera-12-010","lineIndex":10,"speaker":"","original":"To guard you and to guide you","ipa":"/tə ɡɑɹd ju ænd tə ɡaɪd ju/","zh":"守护你、指引你","en":"","note":""},{"id":"phantom-of-the-opera-12-011","lineIndex":11,"speaker":"","original":"Say you love me every waking moment","ipa":"/seɪ ju lʌv mi ɛvɹi weɪkɪŋ moʊmənt/","zh":"说你在每个苏醒的时刻都爱着我","en":"","note":""},{"id":"phantom-of-the-opera-12-012","lineIndex":12,"speaker":"","original":"Turn my head with talk of summertime","ipa":"/tɜn maɪ hɛd wɪð tɔk ʌv sʌmɚtaɪm/","zh":"用夏日时光的谈论，将我的头转过去","en":"","note":""},{"id":"phantom-of-the-opera-12-013","lineIndex":13,"speaker":"","original":"Say you need me with you now and always","ipa":"/seɪ ju nid mi wɪð ju naʊ ænd ɔlweɪz/","zh":"说你生生世世需要我陪伴着你","en":"","note":""},{"id":"phantom-of-the-opera-12-014","lineIndex":14,"speaker":"","original":"Promise me that all you say is true","ipa":"/pɹɑmɪs mi ðæt ɔl ju seɪ ɪz tɹu/","zh":"对我承诺你所说的皆出自真心","en":"","note":""},{"id":"phantom-of-the-opera-12-015","lineIndex":15,"speaker":"","original":"That's all I ask of you","ipa":"/ðæts ɔl aɪ æsk ʌv ju/","zh":"那是我对你仅有的要求","en":"","note":""},{"id":"phantom-of-the-opera-12-016","lineIndex":16,"speaker":"","original":"Let me be your shelter","ipa":"/lɛt mi bi jʊɹ ʃɛltɚ/","zh":"让我成为你的避风港","en":"","note":""},{"id":"phantom-of-the-opera-12-017","lineIndex":17,"speaker":"","original":"Let me be your light","ipa":"/lɛt mi bi jʊɹ laɪt/","zh":"让我成为你的明灯","en":"","note":""},{"id":"phantom-of-the-opera-12-018","lineIndex":18,"speaker":"","original":"You're safe","ipa":"/jʊɹ seɪf/","zh":"你安全了","en":"","note":""},{"id":"phantom-of-the-opera-12-019","lineIndex":19,"speaker":"","original":"No one will find you","ipa":"/noʊwʌn wɪl faɪnd ju/","zh":"无人能找到你","en":"","note":""},{"id":"phantom-of-the-opera-12-020","lineIndex":20,"speaker":"","original":"Your fears are far behind you","ipa":"/jʊɹ fɪɹz ɑɹ fɑɹ bᵻhaɪnd ju/","zh":"你的恐惧离你遥不可及","en":"","note":""},{"id":"phantom-of-the-opera-12-021","lineIndex":21,"speaker":"","original":"All I want is freedom","ipa":"/ɔl aɪ wɔnt ɪz fɹidəm/","zh":"我只祈求自由","en":"","note":""},{"id":"phantom-of-the-opera-12-022","lineIndex":22,"speaker":"","original":"A world with no more night","ipa":"/ɐ wɜld wɪð noʊmɔɹ naɪt/","zh":"不再有黑夜的世界","en":"","note":""},{"id":"phantom-of-the-opera-12-023","lineIndex":23,"speaker":"","original":"And you","ipa":"/ænd ju/","zh":"而你...","en":"","note":""},{"id":"phantom-of-the-opera-12-024","lineIndex":24,"speaker":"","original":"Always beside me","ipa":"/ɔlweɪz bᵻsaɪd mi/","zh":"永远伴我身旁","en":"","note":""},{"id":"phantom-of-the-opera-12-025","lineIndex":25,"speaker":"","original":"To hold me and to hide me","ipa":"/tə hoʊld mi ænd tə haɪd mi/","zh":"拥抱我、藏匿我","en":"","note":""},{"id":"phantom-of-the-opera-12-026","lineIndex":26,"speaker":"","original":"Then say you'll share with me one love","ipa":"/ðɛn seɪ jul ʃɛɹ wɪð mi wʌn lʌv/","zh":"那就说你愿与我共享...坚定爱情","en":"","note":""},{"id":"phantom-of-the-opera-12-027","lineIndex":27,"speaker":"","original":"One lifetime","ipa":"/wʌn laɪftaɪm/","zh":"一生一世","en":"","note":""},{"id":"phantom-of-the-opera-12-028","lineIndex":28,"speaker":"","original":"Let me lead you from your solitude","ipa":"/lɛt mi lid ju fɹʌm jʊɹ sɑlɪtud/","zh":"让我引你走出孤独","en":"","note":""},{"id":"phantom-of-the-opera-12-029","lineIndex":29,"speaker":"","original":"Say you need me with you","ipa":"/seɪ ju nid mi wɪð ju/","zh":"说你需要我与你相随","en":"","note":""},{"id":"phantom-of-the-opera-12-030","lineIndex":30,"speaker":"","original":"Here beside you","ipa":"/hɪɹ bᵻsaɪd ju/","zh":"伴你身旁","en":"","note":""},{"id":"phantom-of-the-opera-12-031","lineIndex":31,"speaker":"","original":"Anywhere you go, let me go too","ipa":"/ɛnɪwɛɹ ju ɡoʊ lɛt mi ɡoʊ tu/","zh":"不论身往何方，也让我同行","en":"","note":""},{"id":"phantom-of-the-opera-12-032","lineIndex":32,"speaker":"","original":"Christine, that's all I ask of you","ipa":"/kɹɪstin ðæts ɔl aɪ æsk ʌv ju/","zh":"那是我对你仅有的要求","en":"","note":""},{"id":"phantom-of-the-opera-12-033","lineIndex":33,"speaker":"","original":"Say you'll share with me one love, one lifetime","ipa":"/seɪ jul ʃɛɹ wɪð mi wʌn lʌv wʌn laɪftaɪm/","zh":"说你愿与我共享坚定爱情，一生一世","en":"","note":""},{"id":"phantom-of-the-opera-12-034","lineIndex":34,"speaker":"","original":"Say the word and I will follow you","ipa":"/seɪ ðə wɜd ænd aɪ wɪl fɑloʊ ju/","zh":"说出这句话，我便会跟随你","en":"","note":""},{"id":"phantom-of-the-opera-12-035","lineIndex":35,"speaker":"","original":"Share each day with me","ipa":"/ʃɛɹ itʃ deɪ wɪð mi/","zh":"与我共享每一天","en":"","note":""},{"id":"phantom-of-the-opera-12-036","lineIndex":36,"speaker":"","original":"Each night, each morning","ipa":"/itʃ naɪt itʃ mɔɹnɪŋ/","zh":"每一个昼夜晨昏","en":"","note":""},{"id":"phantom-of-the-opera-12-037","lineIndex":37,"speaker":"","original":"Say you love me (You know I do)","ipa":"/seɪ ju lʌv mi ju noʊ aɪ du/","zh":"说你爱我... （你知道我爱你的...）","en":"","note":""},{"id":"phantom-of-the-opera-12-038","lineIndex":38,"speaker":"","original":"Love me","ipa":"/lʌv mi/","zh":"爱我","en":"","note":""},{"id":"phantom-of-the-opera-12-039","lineIndex":39,"speaker":"","original":"That's all I ask of you Anywhere you go, let me go too","ipa":"/ðæts ɔl aɪ æsk ʌv ju ɛnɪwɛɹ ju ɡoʊ lɛt mi ɡoʊ tu/","zh":"那是我对你仅有的要求，不论身往何方，也让我同行","en":"","note":""},{"id":"phantom-of-the-opera-12-040","lineIndex":40,"speaker":"","original":"Love me","ipa":"/lʌv mi/","zh":"爱我","en":"","note":""},{"id":"phantom-of-the-opera-12-041","lineIndex":41,"speaker":"","original":"That's all I ask of you","ipa":"/ðæts ɔl aɪ æsk ʌv ju/","zh":"那是我对你仅有的要求","en":"","note":""}],"sourceOrder":12,"displayOrder":12},{"order":13,"id":"13-all-i-ask-of-you-live","title":"All I Ask Of You (Reprise)","titleZh":"我对你唯一的请求（重唱）","lines":[{"id":"phantom-of-the-opera-13-001","lineIndex":1,"speaker":"","original":"I must go","ipa":"/aɪ mʌst ɡoʊ/","zh":"我得走了","en":"","note":""},{"id":"phantom-of-the-opera-13-002","lineIndex":2,"speaker":"","original":"They'll wonder where I am","ipa":"/ðeɪl wʌndɚ wɛɹ aɪæm/","zh":"他们会怀疑我在哪儿","en":"","note":""},{"id":"phantom-of-the-opera-13-003","lineIndex":3,"speaker":"","original":"Wait for me, Raoul","ipa":"/weɪt fɔɹ mi ɹeɪəʌl/","zh":"等我，拉乌尔","en":"","note":""},{"id":"phantom-of-the-opera-13-004","lineIndex":4,"speaker":"","original":"Christine, I love you","ipa":"/kɹɪstin aɪ lʌv ju/","zh":"克莉丝汀，我爱你","en":"","note":""},{"id":"phantom-of-the-opera-13-005","lineIndex":5,"speaker":"","original":"Order your fine horses","ipa":"/ɔɹdɚ jʊɹ faɪn hɔɹsᵻz/","zh":"备好你的良驹","en":"","note":""},{"id":"phantom-of-the-opera-13-006","lineIndex":6,"speaker":"","original":"Be with them at the door","ipa":"/bi wɪð ðɛm æt ðə dɔɹ/","zh":"在门口静候","en":"","note":""},{"id":"phantom-of-the-opera-13-007","lineIndex":7,"speaker":"","original":"And soon you'll be beside me","ipa":"/ænd sun jul bi bᵻsaɪd mi/","zh":"很快你就要伴我身旁","en":"","note":""},{"id":"phantom-of-the-opera-13-008","lineIndex":8,"speaker":"","original":"You'll guard me, and you'll guide me...","ipa":"/jul ɡɑɹd mi ænd jul ɡaɪd mi/","zh":"你会保护我，指引我...","en":"","note":""},{"id":"phantom-of-the-opera-13-009","lineIndex":9,"speaker":"","original":"I gave you my music","ipa":"/aɪ ɡeɪv ju maɪ mjuzɪk/","zh":"我给你我的音乐","en":"","note":""},{"id":"phantom-of-the-opera-13-010","lineIndex":10,"speaker":"","original":"Made your song take wing","ipa":"/meɪd jʊɹ sɔŋ teɪk wɪŋ/","zh":"让你的歌声展翅飞翔","en":"","note":""},{"id":"phantom-of-the-opera-13-011","lineIndex":11,"speaker":"","original":"And now how you've repaid me","ipa":"/ænd naʊ haʊ juv ɹᵻpeɪd mi/","zh":"而现在，你却如此报答我","en":"","note":""},{"id":"phantom-of-the-opera-13-012","lineIndex":12,"speaker":"","original":"Denied me and betrayed me...","ipa":"/dᵻnaɪd mi ænd bᵻtɹeɪd mi/","zh":"否认我，背叛我...","en":"","note":""},{"id":"phantom-of-the-opera-13-013","lineIndex":13,"speaker":"","original":"He was bound to love you","ipa":"/hi wʌz baʊnd tə lʌv ju/","zh":"他注定要爱上你","en":"","note":""},{"id":"phantom-of-the-opera-13-014","lineIndex":14,"speaker":"","original":"When he heard you sing","ipa":"/wɛn hi hɜd ju sɪŋ/","zh":"当他听到你的歌声后","en":"","note":""},{"id":"phantom-of-the-opera-13-015","lineIndex":15,"speaker":"","original":"Christine...","ipa":"/kɹɪstin/","zh":"克莉丝汀...","en":"","note":""},{"id":"phantom-of-the-opera-13-016","lineIndex":16,"speaker":"","original":"Christine...","ipa":"/kɹɪstin/","zh":"克莉丝汀...","en":"","note":""},{"id":"phantom-of-the-opera-13-017","lineIndex":17,"speaker":"","original":"Say you'll share with me one love, one lifetime","ipa":"/seɪ jul ʃɛɹ wɪð mi wʌn lʌv wʌn laɪftaɪm/","zh":"说你一生一世，只爱我一人","en":"","note":""},{"id":"phantom-of-the-opera-13-018","lineIndex":18,"speaker":"","original":"Say the word and I will follow you","ipa":"/seɪ ðə wɜd ænd aɪ wɪl fɑloʊ ju/","zh":"说出这句话，我就跟你走","en":"","note":""},{"id":"phantom-of-the-opera-13-019","lineIndex":19,"speaker":"","original":"Share each day with me","ipa":"/ʃɛɹ itʃ deɪ wɪð mi/","zh":"与我相伴","en":"","note":""},{"id":"phantom-of-the-opera-13-020","lineIndex":20,"speaker":"","original":"Each night, each morning...","ipa":"/itʃ naɪt itʃ mɔɹnɪŋ/","zh":"日日夜夜...","en":"","note":""},{"id":"phantom-of-the-opera-13-021","lineIndex":21,"speaker":"","original":"You will curse the day you did not do...","ipa":"/ju wɪl kɜs ðə deɪ ju dɪdnɑt du/","zh":"没有听从魅影唯一的要求","en":"","note":""},{"id":"phantom-of-the-opera-13-022","lineIndex":22,"speaker":"","original":"All that the Phantom asked of you!","ipa":"/ɔl ðætðə fæntəm æskt ʌv ju/","zh":"你将为这一天追悔莫及！","en":"","note":""},{"id":"phantom-of-the-opera-13-023","lineIndex":23,"speaker":"","original":"Hahahahahahahaha...","ipa":"/hæhɐhæhɐhæhɐhɑhə/","zh":"哈哈哈哈哈哈哈哈...","en":"","note":""},{"id":"phantom-of-the-opera-13-024","lineIndex":24,"speaker":"","original":"Ahahahahahahahaha...","ipa":"/æhɐhæhɐhæhɐhɐhɑhə/","zh":"啊哈哈哈哈哈哈哈哈...","en":"","note":""},{"id":"phantom-of-the-opera-13-025","lineIndex":25,"speaker":"","original":"Ahahahaha...","ipa":"/æhɐhɐhɑhə/","zh":"啊哈哈哈哈...","en":"","note":""},{"id":"phantom-of-the-opera-13-026","lineIndex":26,"speaker":"","original":"Go...","ipa":"/ɡoʊ/","zh":"快跑...","en":"","note":""}],"sourceOrder":13,"displayOrder":13},{"order":16,"id":"16-masquerade-why-so-silent-live","title":"Masquerade/Why So Silent","titleZh":"假面舞会／为何如此沉默","lines":[{"id":"phantom-of-the-opera-16-001","lineIndex":1,"speaker":"","original":"Masquerade! Paper faces on parade...","ipa":"/mæskɚɹeɪd peɪpɚ feɪsᵻz ɔn pɚɹeɪd/","zh":"化妆舞会！纸面具列队游行...","en":"","note":""},{"id":"phantom-of-the-opera-16-002","lineIndex":2,"speaker":"","original":"Masquerade! Hide your face, so the world will never find you!","ipa":"/mæskɚɹeɪd haɪd jʊɹ feɪs soʊ ðə wɜld wɪl nɛvɚ faɪnd ju/","zh":"化妆舞会！藏起真容，让世人永远找不到你！","en":"","note":""},{"id":"phantom-of-the-opera-16-003","lineIndex":3,"speaker":"","original":"Masquerade! Every face a different shade...","ipa":"/mæskɚɹeɪd ɛvɹi feɪs ɐ dɪfɹənt ʃeɪd/","zh":"化妆舞会！每张脸都戴着不同面具...","en":"","note":""},{"id":"phantom-of-the-opera-16-004","lineIndex":4,"speaker":"","original":"Masquerade! Look around - there's another mask behind you!","ipa":"/mæskɚɹeɪd lʊk ɚɹaʊnd ðɛɹz ɐnʌðɚ mæsk bᵻhaɪnd ju/","zh":"化妆舞会！环顾四周—你身后还有另一副假面！","en":"","note":""},{"id":"phantom-of-the-opera-16-005","lineIndex":5,"speaker":"","original":"Flash of mauve, splash of puce...","ipa":"/flæʃ ʌv moʊv splæʃ ʌv pjus/","zh":"淡紫闪过 绛红飞溅...","en":"","note":""},{"id":"phantom-of-the-opera-16-006","lineIndex":6,"speaker":"","original":"Fool and king, ghoul and ghost...","ipa":"/ful ænd kɪŋ ɡul ænd ɡoʊst/","zh":"愚人与王 食尸鬼与幽魂...","en":"","note":""},{"id":"phantom-of-the-opera-16-007","lineIndex":7,"speaker":"","original":"Green and black, queen and priest...","ipa":"/ɡɹin ænd blæk kwin ænd pɹist/","zh":"墨绿玄黑 女王与神父...","en":"","note":""},{"id":"phantom-of-the-opera-16-008","lineIndex":8,"speaker":"","original":"Trace of rouge, face of beast...","ipa":"/tɹeɪs ʌv ɹuʒ feɪs ʌv bist/","zh":"胭脂残痕 野兽面孔...","en":"","note":""},{"id":"phantom-of-the-opera-16-009","lineIndex":9,"speaker":"","original":"Faces... take your turn, take a ride","ipa":"/feɪsᵻz teɪk jʊɹ tɜn teɪk ɐ ɹaɪd/","zh":"众生百相...轮番登场 乘着","en":"","note":""},{"id":"phantom-of-the-opera-16-010","lineIndex":10,"speaker":"","original":"on the merry-go-round... in an inhuman race...","ipa":"/ɔnðə mɛɹiɡoʊɹaʊnd ɪn ɐn ɪnhjumən ɹeɪs/","zh":"旋转木马...卷入这场非人的竞赛...","en":"","note":""},{"id":"phantom-of-the-opera-16-011","lineIndex":11,"speaker":"","original":"Eye of gold, thigh of blue...","ipa":"/aɪ ʌv ɡoʊld θaɪ ʌv blu/","zh":"金色眼眸 蓝色大腿...","en":"","note":""},{"id":"phantom-of-the-opera-16-012","lineIndex":12,"speaker":"","original":"True is false, who is who?","ipa":"/tɹu ɪz fɔls hu ɪz hu/","zh":"真亦是假 谁是谁非？","en":"","note":""},{"id":"phantom-of-the-opera-16-013","lineIndex":13,"speaker":"","original":"Curl of lip, swirl of gown...","ipa":"/kɜl ʌv lɪp swɜl ʌv ɡaʊn/","zh":"嘴角轻扬 裙摆翩跹...","en":"","note":""},{"id":"phantom-of-the-opera-16-014","lineIndex":14,"speaker":"","original":"Ace of hearts, face of clown...","ipa":"/eɪs ʌv hɑɹts feɪs ʌv klaʊn/","zh":"红心王牌 小丑脸谱...","en":"","note":""},{"id":"phantom-of-the-opera-16-015","lineIndex":15,"speaker":"","original":"Faces... drink it in, drink it up","ipa":"/feɪsᵻz dɹɪŋk ɪɾ ɪn dɹɪŋk ɪɾ ʌp/","zh":"众生百相...痛饮狂欢 畅饮至","en":"","note":""},{"id":"phantom-of-the-opera-16-016","lineIndex":16,"speaker":"","original":"till you've drowned in the light... in the sound...","ipa":"/tɪl juv dɹaʊnd ɪnðə laɪt ɪnðə saʊnd/","zh":"溺毙于华光...于喧嚣...","en":"","note":""},{"id":"phantom-of-the-opera-16-017","lineIndex":17,"speaker":"","original":"But who can name the face...","ipa":"/bʌt hu kæn neɪm ðə feɪs/","zh":"但谁能看穿面具下的真相...","en":"","note":""},{"id":"phantom-of-the-opera-16-018","lineIndex":18,"speaker":"","original":"Masquerade! Grinning yellows, spinning reds...","ipa":"/mæskɚɹeɪd ɡɹɪnɪŋ jɛloʊz spɪnɪŋ ɹɛdz/","zh":"化妆舞会！狞笑的黄 旋转的红...","en":"","note":""},{"id":"phantom-of-the-opera-16-019","lineIndex":19,"speaker":"","original":"Masquerade! Take your fill - let the spectacle astound you!","ipa":"/mæskɚɹeɪd teɪk jʊɹ fɪl lɛt ðə spɛktəkəl ɐstaʊnd ju/","zh":"化妆舞会！尽情享受—让这奇观震撼你！","en":"","note":""},{"id":"phantom-of-the-opera-16-020","lineIndex":20,"speaker":"","original":"Masquerade! Burning glances, turning heads...","ipa":"/mæskɚɹeɪd bɜnɪŋ ɡlænsᵻz tɜnɪŋ hɛdz/","zh":"化妆舞会！灼热眼波 回眸生姿...","en":"","note":""},{"id":"phantom-of-the-opera-16-021","lineIndex":21,"speaker":"","original":"Masquerade! Stop and stare at the sea of smiles around you!","ipa":"/mæskɚɹeɪd stɑp ænd stɛɹ æt ðə si ʌv smaɪlz ɚɹaʊnd ju/","zh":"化妆舞会！驻足凝视周围微笑的海洋！","en":"","note":""},{"id":"phantom-of-the-opera-16-022","lineIndex":22,"speaker":"","original":"Masquerade! Seething shadows, breathing lies...","ipa":"/mæskɚɹeɪd siðɪŋ ʃædoʊz bɹiðɪŋ laɪz/","zh":"化妆舞会！暗影翻涌 谎言吐息...","en":"","note":""},{"id":"phantom-of-the-opera-16-023","lineIndex":23,"speaker":"","original":"Masquerade! You can fool and friend who ever knew you!","ipa":"/mæskɚɹeɪd ju kæn ful ænd fɹɛnd hu ɛvɚ nu ju/","zh":"化妆舞会！你能欺骗所有认识你的朋友！","en":"","note":""},{"id":"phantom-of-the-opera-16-024","lineIndex":24,"speaker":"","original":"Masquerade! Leering satyrs, peering eyes...","ipa":"/mæskɚɹeɪd lɪɹɪŋ sæɾɚz pɪɹɪŋ aɪz/","zh":"化妆舞会！淫视的山怪 窥探的眼睛...","en":"","note":""},{"id":"phantom-of-the-opera-16-025","lineIndex":25,"speaker":"","original":"Masquerade! Run and hide - but a face will still pursue you!","ipa":"/mæskɚɹeɪd ɹʌn ænd haɪd bʌt ɐ feɪs wɪl stɪl pɚsu ju/","zh":"化妆舞会！逃跑躲藏—但假面终将追上你！","en":"","note":""},{"id":"phantom-of-the-opera-16-026","lineIndex":26,"speaker":"","original":"What a night!","ipa":"/wʌt ɐ naɪt/","zh":"多美妙的夜！","en":"","note":""},{"id":"phantom-of-the-opera-16-027","lineIndex":27,"speaker":"","original":"What a crowd!","ipa":"/wʌt ɐ kɹaʊd/","zh":"多热闹的场！","en":"","note":""},{"id":"phantom-of-the-opera-16-028","lineIndex":28,"speaker":"","original":"Makes you glad!","ipa":"/meɪks ju ɡlæd/","zh":"让你欢欣！","en":"","note":""},{"id":"phantom-of-the-opera-16-029","lineIndex":29,"speaker":"","original":"Makes you proud!","ipa":"/meɪks ju pɹaʊd/","zh":"让你自豪！","en":"","note":""},{"id":"phantom-of-the-opera-16-030","lineIndex":30,"speaker":"","original":"All the creme de la creme!","ipa":"/ɔl ðə kɹim də læ kɹim/","zh":"全是社会名流！","en":"","note":""},{"id":"phantom-of-the-opera-16-031","lineIndex":31,"speaker":"","original":"Watching us watching them!","ipa":"/wɑtʃɪŋ ʌs wɑtʃɪŋ ðɛm/","zh":"我们看他们 他们看我们！","en":"","note":""},{"id":"phantom-of-the-opera-16-032","lineIndex":32,"speaker":"","original":"And all our fears are in the past!","ipa":"/ænd ɔl aʊɚ fɪɹz ɑɹ ɪnðə pæst/","zh":"所有恐惧都已成过往！","en":"","note":""},{"id":"phantom-of-the-opera-16-033","lineIndex":33,"speaker":"","original":"Six months...","ipa":"/sɪks mʌnθs/","zh":"六个月...","en":"","note":""},{"id":"phantom-of-the-opera-16-034","lineIndex":34,"speaker":"","original":"Of relief!","ipa":"/ʌv ɹᵻlif/","zh":"的解脱！","en":"","note":""},{"id":"phantom-of-the-opera-16-035","lineIndex":35,"speaker":"","original":"Of delight!","ipa":"/ʌv dᵻlaɪt/","zh":"的欢愉！","en":"","note":""},{"id":"phantom-of-the-opera-16-036","lineIndex":36,"speaker":"","original":"Of Elysian peace!","ipa":"/ʌv ɛlɪʒən pis/","zh":"极乐净土般的安宁！","en":"","note":""},{"id":"phantom-of-the-opera-16-037","lineIndex":37,"speaker":"","original":"And we can breathe at last!","ipa":"/ænd wi kæn bɹið æt læst/","zh":"我们终于能呼吸！","en":"","note":""},{"id":"phantom-of-the-opera-16-038","lineIndex":38,"speaker":"","original":"No more notes!","ipa":"/noʊmɔɹ noʊts/","zh":"再无字条！","en":"","note":""},{"id":"phantom-of-the-opera-16-039","lineIndex":39,"speaker":"","original":"No more ghosts!","ipa":"/noʊmɔɹ ɡoʊsts/","zh":"再无幽灵！","en":"","note":""},{"id":"phantom-of-the-opera-16-040","lineIndex":40,"speaker":"","original":"Here's a health!","ipa":"/hɪɹz ɐ hɛlθ/","zh":"举杯祝酒！","en":"","note":""},{"id":"phantom-of-the-opera-16-041","lineIndex":41,"speaker":"","original":"Here's a toast: to a prosperous year!","ipa":"/hɪɹz ɐ toʊst tʊ ɐ pɹɑspɚɹəs jɪɹ/","zh":"共庆这：繁荣之年！","en":"","note":""},{"id":"phantom-of-the-opera-16-042","lineIndex":42,"speaker":"","original":"To the new chandelier!","ipa":"/tə ðə nu ʃændəlɪɹ/","zh":"为新枝形吊灯！","en":"","note":""},{"id":"phantom-of-the-opera-16-043","lineIndex":43,"speaker":"","original":"And may its splendour never fade!","ipa":"/ænd meɪ ɪts splɛndɚ nɛvɚ feɪd/","zh":"愿其辉煌永不褪色！","en":"","note":""},{"id":"phantom-of-the-opera-16-044","lineIndex":44,"speaker":"","original":"Six months!","ipa":"/sɪks mʌnθs/","zh":"六个月！","en":"","note":""},{"id":"phantom-of-the-opera-16-045","lineIndex":45,"speaker":"","original":"What a joy!","ipa":"/wʌt ɐ dʒɔɪ/","zh":"何等喜悦！","en":"","note":""},{"id":"phantom-of-the-opera-16-046","lineIndex":46,"speaker":"","original":"What a change!","ipa":"/wʌt ɐ tʃeɪndʒ/","zh":"何等改变！","en":"","note":""},{"id":"phantom-of-the-opera-16-047","lineIndex":47,"speaker":"","original":"What a blessed release!","ipa":"/wʌt ɐ blɛst ɹᵻlis/","zh":"何等神圣解脱！","en":"","note":""},{"id":"phantom-of-the-opera-16-048","lineIndex":48,"speaker":"","original":"And what a masquerade!","ipa":"/ænd wʌt ɐ mæskɚɹeɪd/","zh":"何等化妆舞会！","en":"","note":""},{"id":"phantom-of-the-opera-16-049","lineIndex":49,"speaker":"","original":"Think of it! A secret engagement!","ipa":"/θɪŋk ʌv ɪt ɐ sikɹᵻt ɛŋɡeɪdʒmənt/","zh":"想想看！秘密订婚！","en":"","note":""},{"id":"phantom-of-the-opera-16-050","lineIndex":50,"speaker":"","original":"Look - your future bride! Just think of it!","ipa":"/lʊk jʊɹ fjutʃɚ bɹaɪd dʒʌst θɪŋk ʌv ɪt/","zh":"看—你未来的新娘！好好想想！","en":"","note":""},{"id":"phantom-of-the-opera-16-051","lineIndex":51,"speaker":"","original":"But why is it secret? What have we to hide?","ipa":"/bʌt waɪ ɪz ɪt sikɹᵻt wʌt hæv wi tə haɪd/","zh":"但为何要保密？我们有何可隐藏？","en":"","note":""},{"id":"phantom-of-the-opera-16-052","lineIndex":52,"speaker":"","original":"Please, let's not fight...","ipa":"/pliz lɛts nɑt faɪt/","zh":"求你别争吵...","en":"","note":""},{"id":"phantom-of-the-opera-16-053","lineIndex":53,"speaker":"","original":"Christine, you're free!","ipa":"/kɹɪstin jʊɹ fɹi/","zh":"克里斯汀 你自由了！","en":"","note":""},{"id":"phantom-of-the-opera-16-054","lineIndex":54,"speaker":"","original":"Wait till the time is right...","ipa":"/weɪt tɪl ðə taɪm ɪz ɹaɪt/","zh":"等待合适时机...","en":"","note":""},{"id":"phantom-of-the-opera-16-055","lineIndex":55,"speaker":"","original":"When will you that be? It's an engagement, not a crime!","ipa":"/wɛn wɪl ju ðæt bi ɪts ɐn ɛŋɡeɪdʒmənt nɑɾə kɹaɪm/","zh":"何时才算合适？订婚又不是犯罪！","en":"","note":""},{"id":"phantom-of-the-opera-16-056","lineIndex":56,"speaker":"","original":"Christine, What are you afraid of?","ipa":"/kɹɪstin wʌt ɑɹ ju ɐfɹeɪd ʌv/","zh":"克里斯汀 你究竟在害怕什么？","en":"","note":""},{"id":"phantom-of-the-opera-16-057","lineIndex":57,"speaker":"","original":"Let's not argue...","ipa":"/lɛts nɑt ɑɹɡju/","zh":"别再争执...","en":"","note":""},{"id":"phantom-of-the-opera-16-058","lineIndex":58,"speaker":"","original":"Let's not argue...","ipa":"/lɛts nɑt ɑɹɡju/","zh":"别再争执...","en":"","note":""},{"id":"phantom-of-the-opera-16-059","lineIndex":59,"speaker":"","original":"Please pretend...","ipa":"/pliz pɹɪtɛnd/","zh":"请假装...","en":"","note":""},{"id":"phantom-of-the-opera-16-060","lineIndex":60,"speaker":"","original":"I can only hope I'll...","ipa":"/aɪ kæn oʊnli hoʊp aɪl/","zh":"我只能希望我终将...","en":"","note":""},{"id":"phantom-of-the-opera-16-061","lineIndex":61,"speaker":"","original":"You will...","ipa":"/ju wɪl/","zh":"你会...","en":"","note":""},{"id":"phantom-of-the-opera-16-062","lineIndex":62,"speaker":"","original":"... understand in time...","ipa":"/ʌndɚstænd ɪn taɪm/","zh":"...在某个时刻明白...","en":"","note":""},{"id":"phantom-of-the-opera-16-063","lineIndex":63,"speaker":"","original":"Masquerade! Paper faces on parade!","ipa":"/mæskɚɹeɪd peɪpɚ feɪsᵻz ɔn pɚɹeɪd/","zh":"化妆舞会！纸面具列队游行！","en":"","note":""},{"id":"phantom-of-the-opera-16-064","lineIndex":64,"speaker":"","original":"Masquerade! Hide your face, so the world will never find you!","ipa":"/mæskɚɹeɪd haɪd jʊɹ feɪs soʊ ðə wɜld wɪl nɛvɚ faɪnd ju/","zh":"化妆舞会！藏起真容，让世人永远找不到你！","en":"","note":""},{"id":"phantom-of-the-opera-16-065","lineIndex":65,"speaker":"","original":"Masquerade! Every face a different shade!","ipa":"/mæskɚɹeɪd ɛvɹi feɪs ɐ dɪfɹənt ʃeɪd/","zh":"化妆舞会！每张脸都戴着不同面具！","en":"","note":""},{"id":"phantom-of-the-opera-16-066","lineIndex":66,"speaker":"","original":"Masquerade! Look around - there's another mask behind you!","ipa":"/mæskɚɹeɪd lʊk ɚɹaʊnd ðɛɹz ɐnʌðɚ mæsk bᵻhaɪnd ju/","zh":"化妆舞会！环顾四周—你身后还有另一副假面！","en":"","note":""},{"id":"phantom-of-the-opera-16-067","lineIndex":67,"speaker":"","original":"Masquerade! Burning glances! turning heads...","ipa":"/mæskɚɹeɪd bɜnɪŋ ɡlænsᵻz tɜnɪŋ hɛdz/","zh":"化妆舞会！灼热眼波！回眸生姿...","en":"","note":""},{"id":"phantom-of-the-opera-16-068","lineIndex":68,"speaker":"","original":"Masquerade! Stop and stare at the sea of smiles around you!","ipa":"/mæskɚɹeɪd stɑp ænd stɛɹ æt ðə si ʌv smaɪlz ɚɹaʊnd ju/","zh":"化妆舞会！驻足凝视周围微笑的海洋！","en":"","note":""},{"id":"phantom-of-the-opera-16-069","lineIndex":69,"speaker":"","original":"Masquerade! Grinning yellows, spinning reds...","ipa":"/mæskɚɹeɪd ɡɹɪnɪŋ jɛloʊz spɪnɪŋ ɹɛdz/","zh":"化妆舞会！狞笑的黄 旋转的红...","en":"","note":""},{"id":"phantom-of-the-opera-16-070","lineIndex":70,"speaker":"","original":"Masquerade! Take your fill - let the spectacle astound you!","ipa":"/mæskɚɹeɪd teɪk jʊɹ fɪl lɛt ðə spɛktəkəl ɐstaʊnd ju/","zh":"化妆舞会！尽情享受—让这奇观震撼你！","en":"","note":""},{"id":"phantom-of-the-opera-16-071","lineIndex":71,"speaker":"","original":"Why so silent, good messieurs?","ipa":"/waɪ soʊ saɪlənt ɡʊd məsjɜz/","zh":"为何如此沉默 先生们？","en":"","note":""},{"id":"phantom-of-the-opera-16-072","lineIndex":72,"speaker":"","original":"Did you think that I had left you for good?","ipa":"/dɪd ju θɪŋk ðæt aɪ hæd lɛft ju fɔɹ ɡʊd/","zh":"难道以为我已永远离开？","en":"","note":""},{"id":"phantom-of-the-opera-16-073","lineIndex":73,"speaker":"","original":"Have you missed me, good messieurs?","ipa":"/hæv ju mɪst mi ɡʊd məsjɜz/","zh":"可曾想念我 先生们？","en":"","note":""},{"id":"phantom-of-the-opera-16-074","lineIndex":74,"speaker":"","original":"I have written you an opera!","ipa":"/aɪ hæv ɹɪʔn̩ ju ɐn ɑpɚɹə/","zh":"我为你们写了部歌剧！","en":"","note":""},{"id":"phantom-of-the-opera-16-075","lineIndex":75,"speaker":"","original":"Here I bring the finished score! Don Juan Triumphant!","ipa":"/hɪɹ aɪ bɹɪŋ ðə fɪnɪʃt skɔɹ dɑn hwɑn tɹaɪʌmfənt/","zh":"带来完整乐谱！《胜利的唐璜》！","en":"","note":""},{"id":"phantom-of-the-opera-16-076","lineIndex":76,"speaker":"","original":"I advise you to comply, my instructions should be clear","ipa":"/aɪ ɐdvaɪz ju tə kəmplaɪ maɪ ɪnstɹʌkʃənz ʃʊd bi klɪɹ/","zh":"奉劝你们乖乖服从 我的要求应当明确","en":"","note":""},{"id":"phantom-of-the-opera-16-077","lineIndex":77,"speaker":"","original":"Remember there are worse things than a shattered chandelier...","ipa":"/ɹᵻmɛmbɚ ðɛɹɑɹ wɜs θɪŋz ðænə ʃæɾɚd ʃændəlɪɹ/","zh":"记住 比破碎吊灯更可怕的事多着呢...","en":"","note":""},{"id":"phantom-of-the-opera-16-078","lineIndex":78,"speaker":"","original":"Your chains are still mine You will sing for me...!","ipa":"/jʊɹ tʃeɪnz ɑɹ stɪl maɪn ju wɪl sɪŋ fɔɹ mi ɛkskləmeɪʃən/","zh":"你们的枷锁仍属于我 你们要为我歌唱...！","en":"","note":""}],"sourceOrder":16,"displayOrder":14},{"order":18,"id":"18-wishing-you-were-somehow-here-again-live","title":"Wishing You Were Somehow Here Again","titleZh":"愿你能再次回到这里","lines":[{"id":"phantom-of-the-opera-18-001","lineIndex":1,"speaker":"","original":"Little Lottie thought of everything and nothing","ipa":"/lɪɾəl lɑɾi θɔt ʌv ɛvɹɪθɪŋ ænd nʌθɪŋ/","zh":"小罗蒂思绪万千然一筹莫展","en":"","note":""},{"id":"phantom-of-the-opera-18-002","lineIndex":2,"speaker":"","original":"Her father promised her that he","ipa":"/hɜ fɑðɚ pɹɑmɪst hɜ ðæt hi/","zh":"父亲答曾答应","en":"","note":""},{"id":"phantom-of-the-opera-18-003","lineIndex":3,"speaker":"","original":"Would sent her The Angel Of Music","ipa":"/wʊd sɛnt hɜ ðɪ eɪndʒəl ʌv mjuzɪk/","zh":"送给她音乐的天使","en":"","note":""},{"id":"phantom-of-the-opera-18-004","lineIndex":4,"speaker":"","original":"Her father promised her","ipa":"/hɜ fɑðɚ pɹɑmɪst hɜ/","zh":"父亲曾答应......","en":"","note":""},{"id":"phantom-of-the-opera-18-005","lineIndex":5,"speaker":"","original":"Her father promised her","ipa":"/hɜ fɑðɚ pɹɑmɪst hɜ/","zh":"父亲曾答应......","en":"","note":""},{"id":"phantom-of-the-opera-18-006","lineIndex":6,"speaker":"","original":"You were once my one companion","ipa":"/ju wɜ wʌns maɪ wʌn kəmpæniən/","zh":"曾经，你是我亲密的同伴","en":"","note":""},{"id":"phantom-of-the-opera-18-007","lineIndex":7,"speaker":"","original":"You were all that mattered","ipa":"/ju wɜɹ ɔl ðæt mæɾɚd/","zh":"曾经，你是我的一切","en":"","note":""},{"id":"phantom-of-the-opera-18-008","lineIndex":8,"speaker":"","original":"You were once a friend and father","ipa":"/ju wɜ wʌns ɐ fɹɛnd ænd fɑðɚ/","zh":"曾经，你是我的朋友及父亲","en":"","note":""},{"id":"phantom-of-the-opera-18-009","lineIndex":9,"speaker":"","original":"Then my world was shattered","ipa":"/ðɛn maɪ wɜld wʌz ʃæɾɚd/","zh":"现在，我的世界支离破碎了","en":"","note":""},{"id":"phantom-of-the-opera-18-010","lineIndex":10,"speaker":"","original":"Wishing you were somehow here again","ipa":"/wɪʃɪŋ ju wɜ sʌmhaʊ hɪɹ ɐɡɛn/","zh":"不知怎的，希望你能再一次出现","en":"","note":""},{"id":"phantom-of-the-opera-18-011","lineIndex":11,"speaker":"","original":"Wishing you were somehow near","ipa":"/wɪʃɪŋ ju wɜ sʌmhaʊ nɪɹ/","zh":"不知怎的，希望你就在附近","en":"","note":""},{"id":"phantom-of-the-opera-18-012","lineIndex":12,"speaker":"","original":"Sometimes it seemed if I just dreamed","ipa":"/sʌmtaɪmz ɪt simd ɪf aɪ dʒʌst dɹimd/","zh":"有时候，好像只要我想象你会出现","en":"","note":""},{"id":"phantom-of-the-opera-18-013","lineIndex":13,"speaker":"","original":"Somehow you would be here","ipa":"/sʌmhaʊ ju wʊd bi hɪɹ/","zh":"不知怎的，你就会出现","en":"","note":""},{"id":"phantom-of-the-opera-18-014","lineIndex":14,"speaker":"","original":"Wishing I could hear your voice again","ipa":"/wɪʃɪŋ aɪ kʊd hɪɹ jʊɹ vɔɪs ɐɡɛn/","zh":"我希望能再次听见你的声音","en":"","note":""},{"id":"phantom-of-the-opera-18-015","lineIndex":15,"speaker":"","original":"Knowing that I never would","ipa":"/noʊɪŋ ðæt aɪ nɛvɚ wʊd/","zh":"虽然我知道那是不可能的了","en":"","note":""},{"id":"phantom-of-the-opera-18-016","lineIndex":16,"speaker":"","original":"Dreaming of you won't help me to do","ipa":"/dɹimɪŋ ʌv ju woʊnt hɛlp mi tə du/","zh":"一味挂念你，是不会帮我实现","en":"","note":""},{"id":"phantom-of-the-opera-18-017","lineIndex":17,"speaker":"","original":"All that you dreamed I could","ipa":"/ɔl ðæt ju dɹimd aɪ kʊd/","zh":"所有那些你希望我做得到的事情","en":"","note":""},{"id":"phantom-of-the-opera-18-018","lineIndex":18,"speaker":"","original":"Pulsing bells and sculptured angles","ipa":"/pʌlsɪŋ bɛlz ænd skʌlptʃɚd æŋɡəlz/","zh":"微微晃动的丧钟，石头雕刻的天使","en":"","note":""},{"id":"phantom-of-the-opera-18-019","lineIndex":19,"speaker":"","original":"Cold and monumental","ipa":"/koʊld ænd mɑnjumɛntəl/","zh":"像纪念碑一样，毫无生气","en":"","note":""},{"id":"phantom-of-the-opera-18-020","lineIndex":20,"speaker":"","original":"Seemed for you the wrong companion","ipa":"/simd fɔɹ ju ðə ɹɔŋ kəmpæniən/","zh":"他们看上去，不像是你的朋友","en":"","note":""},{"id":"phantom-of-the-opera-18-021","lineIndex":21,"speaker":"","original":"You were warm and gentle","ipa":"/ju wɜ wɔɹm ænd dʒɛntəl/","zh":"你既温暖又和蔼","en":"","note":""},{"id":"phantom-of-the-opera-18-022","lineIndex":22,"speaker":"","original":"Too many years fighting back tears","ipa":"/tu mɛni jɪɹz faɪɾɪŋ bæk tɪɹz/","zh":"多年以来，一直拼命忍住泪水","en":"","note":""},{"id":"phantom-of-the-opera-18-023","lineIndex":23,"speaker":"","original":"Why can't the past just die?","ipa":"/waɪ kænt ðə pæst dʒʌst daɪ/","zh":"为何往事不能悄然而去呢？","en":"","note":""},{"id":"phantom-of-the-opera-18-024","lineIndex":24,"speaker":"","original":"Wishing you were somehow here again","ipa":"/wɪʃɪŋ ju wɜ sʌmhaʊ hɪɹ ɐɡɛn/","zh":"不知怎的，希望你能再一次出现","en":"","note":""},{"id":"phantom-of-the-opera-18-025","lineIndex":25,"speaker":"","original":"Knowing we must say good bye","ipa":"/noʊɪŋ wi mʌst seɪ ɡʊd baɪ/","zh":"虽然清楚我们终会永别","en":"","note":""},{"id":"phantom-of-the-opera-18-026","lineIndex":26,"speaker":"","original":"Try to forgive teach me to live","ipa":"/tɹaɪ tə fɚɡɪv titʃ mi tə lɪv/","zh":"请试着原谅我，教我该如何生活","en":"","note":""},{"id":"phantom-of-the-opera-18-027","lineIndex":27,"speaker":"","original":"Give me the strength to try","ipa":"/ɡɪv mi ðə stɹɛŋθ tə tɹaɪ/","zh":"请赐予我力量，让我踏出最艰难的第一步","en":"","note":""},{"id":"phantom-of-the-opera-18-028","lineIndex":28,"speaker":"","original":"No more memories no more silent tears","ipa":"/noʊmɔɹ mɛmɚɹiz noʊmɔɹ saɪlənt tɪɹz/","zh":"不再留恋过去，不再暗自流泪","en":"","note":""},{"id":"phantom-of-the-opera-18-029","lineIndex":29,"speaker":"","original":"No repeating of lost and wasted years","ipa":"/noʊ ɹᵻpiɾɪŋ ʌv lɔst ænd weɪstᵻd jɪɹz/","zh":"不再重复叹息白白逝去的青春","en":"","note":""},{"id":"phantom-of-the-opera-18-030","lineIndex":30,"speaker":"","original":"Help me say good bye","ipa":"/hɛlp mi seɪ ɡʊd baɪ/","zh":"请给我告别的勇气","en":"","note":""}],"sourceOrder":18,"displayOrder":15},{"order":19,"id":"19-wandering-child-bravo-monsieur-live","title":"Wandering Child.../Bravo, Monsieur...","titleZh":"迷途的孩子……／好极了，先生……","lines":[{"id":"phantom-of-the-opera-19-002","lineIndex":1,"speaker":"PHANTOM","original":"Wandering child, so lost, so helpless...","ipa":"/wɔndɚɹɪŋ tʃaɪld soʊ lɔst soʊ hɛlpləs/","zh":"迷途的孩子 如此彷徨无助","en":"","note":""},{"id":"phantom-of-the-opera-19-003","lineIndex":2,"speaker":"","original":"yearning for my guidance...","ipa":"/jˈɜːnɪŋ fɔː‍ɹ ma‍ɪ ɡˈa‍ɪdəns/","zh":"渴望我的指引","en":"","note":""},{"id":"phantom-of-the-opera-19-005","lineIndex":3,"speaker":"CHRISTINE","original":"Angel or father... friend... or Phantom...?","ipa":"/eɪndʒəl ɔɹ fɑðɚ fɹɛnd ɔɹ fæntəm/","zh":"是天使 父亲 朋友 还是魅影？","en":"","note":""},{"id":"phantom-of-the-opera-19-006","lineIndex":4,"speaker":"","original":"Who is it there, staring...?","ipa":"/hu ɪz ɪt ðɛɹ stɛɹɪŋ/","zh":"谁在那里凝视？","en":"","note":""},{"id":"phantom-of-the-opera-19-008","lineIndex":5,"speaker":"PHANTOM","original":"Have you forgotten your Angel...?","ipa":"/hæv ju fɚɡɑʔn̩ jʊɹ eɪndʒəl/","zh":"你已忘记你的天使了吗？","en":"","note":""},{"id":"phantom-of-the-opera-19-010","lineIndex":6,"speaker":"CHRISTINE","original":"Angel... oh, speak...","ipa":"/eɪndʒəl oʊ spik/","zh":"天使啊 请开口","en":"","note":""},{"id":"phantom-of-the-opera-19-011","lineIndex":7,"speaker":"","original":"What endless longings echo in this whisper...!","ipa":"/wʌt ɛndləs lɔŋɪŋz ɛkoʊ ɪn ðɪs wɪspɚ ɛkskləmeɪʃən/","zh":"这低语中回荡着无尽的渴望！","en":"","note":""},{"id":"phantom-of-the-opera-19-013","lineIndex":8,"speaker":"PHANTOM","original":"Too long you've wandered in winter...","ipa":"/tu lɔŋ juv wɔndɚd ɪn wɪntɚ/","zh":"你已在寒冬徘徊太久","en":"","note":""},{"id":"phantom-of-the-opera-19-014","lineIndex":9,"speaker":"","original":"Far from my far -reaching gaze...","ipa":"/fɑɹ fɹʌm maɪ fɑɹ ɹitʃɪŋ ɡeɪz/","zh":"远离我守望的目光","en":"","note":""},{"id":"phantom-of-the-opera-19-016","lineIndex":10,"speaker":"CHRISTINE","original":"Wildly my mind beats against you...","ipa":"/waɪldli maɪ maɪnd bits ɐɡɛnst ju/","zh":"我的心狂乱地抗拒着你","en":"","note":""},{"id":"phantom-of-the-opera-19-018","lineIndex":11,"speaker":"PHANTOM","original":"You resist...","ipa":"/ju ɹᵻzɪst/","zh":"你在抗拒","en":"","note":""},{"id":"phantom-of-the-opera-19-020","lineIndex":12,"speaker":"BOTH","original":"Yet your/the soul obeys...","ipa":"/jɛt jʊɹ slæʃ ðə soʊl oʊbeɪz/","zh":"但你的灵魂已臣服","en":"","note":""},{"id":"phantom-of-the-opera-19-022","lineIndex":13,"speaker":"PHANTOM","original":"Angel of Music! You denied me, turning from true beauty...","ipa":"/eɪndʒəl ʌv mjuzɪk ju dᵻnaɪd mi tɜnɪŋ fɹʌm tɹu bjuɾi/","zh":"音乐天使！你曾背弃我 远离真正的美","en":"","note":""},{"id":"phantom-of-the-opera-19-023","lineIndex":14,"speaker":"","original":"Angel of Music! Do not shun me... Come to your strange Angel!","ipa":"/eɪndʒəl ʌv mjuzɪk dunɑt ʃʌn mi kʌm tə jʊɹ stɹeɪndʒ eɪndʒəl/","zh":"音乐天使！别躲开我 来到你奇异的天使身边","en":"","note":""},{"id":"phantom-of-the-opera-19-025","lineIndex":15,"speaker":"CHRISTINE","original":"Angel of Music! I denied you, turning from true beauty...","ipa":"/eɪndʒəl ʌv mjuzɪk aɪ dᵻnaɪd ju tɜnɪŋ fɹʌm tɹu bjuɾi/","zh":"音乐天使！我曾背弃你 远离真正的美","en":"","note":""},{"id":"phantom-of-the-opera-19-026","lineIndex":16,"speaker":"","original":"Angel of Music! My protector... Come to me, strange Angel!","ipa":"/eɪndʒəl ʌv mjuzɪk maɪ pɹətɛktɚ kʌm tə mi stɹeɪndʒ eɪndʒəl/","zh":"音乐天使！我的守护者 来到我身边 奇异的天使","en":"","note":""},{"id":"phantom-of-the-opera-19-028","lineIndex":17,"speaker":"PHANTOM","original":"I am your Angel of Music...","ipa":"/aɪɐm jʊɹ eɪndʒəl ʌv mjuzɪk/","zh":"我是你的音乐天使","en":"","note":""},{"id":"phantom-of-the-opera-19-029","lineIndex":18,"speaker":"","original":"Come to me: Angel of Music...","ipa":"/kʌm tə mi eɪndʒəl ʌv mjuzɪk/","zh":"来到我身边：音乐天使","en":"","note":""},{"id":"phantom-of-the-opera-19-031","lineIndex":19,"speaker":"RAOUL","original":"Leave her!","ipa":"/liv hɜ/","zh":"放开她！","en":"","note":""},{"id":"phantom-of-the-opera-19-032","lineIndex":20,"speaker":"","original":"You have no claim on her... Leave her!","ipa":"/ju hæv noʊ kleɪm ɔn hɜ liv hɜ/","zh":"你无权占有她 放开她！","en":"","note":""},{"id":"phantom-of-the-opera-19-033","lineIndex":21,"speaker":"","original":"Your words are wasted --","ipa":"/jʊɹ wɜdz ɑɹ weɪstᵻd/","zh":"你的言语徒劳","en":"","note":""},{"id":"phantom-of-the-opera-19-034","lineIndex":22,"speaker":"","original":"Can't you see she'll never be yours?","ipa":"/kænt ju si ʃil nɛvɚ bi jɔɹz/","zh":"难道看不出她永远不会属于你？","en":"","note":""},{"id":"phantom-of-the-opera-19-035","lineIndex":23,"speaker":"","original":"Christine! Christine!","ipa":"/kɹɪstin kɹɪstin/","zh":"克里斯汀！克里斯汀！","en":"","note":""},{"id":"phantom-of-the-opera-19-037","lineIndex":24,"speaker":"CHRISTINE","original":"Raoul!","ipa":"/ɹeɪəʌl/","zh":"拉乌尔！","en":"","note":""},{"id":"phantom-of-the-opera-19-039","lineIndex":25,"speaker":"PHANTOM","original":"Bravo, monsieur! Such spirited words!","ipa":"/bɹɑvoʊ məsjɜ sʌtʃ spɪɹɪɾᵻd wɜdz/","zh":"好极了 先生！多么激昂的言辞！","en":"","note":""},{"id":"phantom-of-the-opera-19-041","lineIndex":26,"speaker":"RAOUL","original":"More tricks, monsieur?","ipa":"/mɔɹ tɹɪks məsjɜ/","zh":"又要耍花招吗 先生？","en":"","note":""},{"id":"phantom-of-the-opera-19-043","lineIndex":27,"speaker":"PHANTOM","original":"Let's see, Monsieur, how far you dare go?","ipa":"/lˈɛts sˈiː məsjˈɜː hˌa‍ʊ fˈɑː‍ɹ juː dˈɛ‍ɹ ɡˈo‍ʊ/","zh":"让我们看看 先生 你敢走多远？","en":"","note":""},{"id":"phantom-of-the-opera-19-045","lineIndex":28,"speaker":"RAOUL","original":"More deception? More violence?","ipa":"/mɔɹ dᵻsɛpʃən mɔɹ vaɪələns/","zh":"更多欺骗？更多暴力？","en":"","note":""},{"id":"phantom-of-the-opera-19-047","lineIndex":29,"speaker":"PHANTOM","original":"That's right, that's right, keep walking this way!","ipa":"/ðæts ɹaɪt ðæts ɹaɪt kip wɔkɪŋ ðɪs weɪ/","zh":"没错 就这样 继续往这边走！","en":"","note":""},{"id":"phantom-of-the-opera-19-049","lineIndex":30,"speaker":"RAOUL","original":"You can't win her love by making her your prisoner.","ipa":"/ju kænt wɪn hɜ lʌv baɪ meɪkɪŋ hɜ jʊɹ pɹɪzənɚ/","zh":"你无法通过囚禁来赢得她的爱","en":"","note":""},{"id":"phantom-of-the-opera-19-051","lineIndex":31,"speaker":"PHANTOM","original":"I'm here, I'm here, monsieur: the Angel of Death!","ipa":"/aɪm hɪɹ aɪm hɪɹ məsjɜ ðɪ eɪndʒəl ʌv dɛθ/","zh":"我在此 先生：死亡天使！","en":"","note":""},{"id":"phantom-of-the-opera-19-052","lineIndex":32,"speaker":"","original":"Come on, come on, don't stop, don't stop!","ipa":"/kʌm ɔn kʌm ɔn doʊnt stɑp doʊnt stɑp/","zh":"来吧 别停下 别停下！","en":"","note":""},{"id":"phantom-of-the-opera-19-054","lineIndex":33,"speaker":"CHRISTINE","original":"Raoul!!","ipa":"/ɹeɪəʌl/","zh":"拉乌尔！！","en":"","note":""},{"id":"phantom-of-the-opera-19-056","lineIndex":34,"speaker":"PHANTOM","original":"Don't go!!","ipa":"/doʊnt ɡoʊ/","zh":"别走！！","en":"","note":""},{"id":"phantom-of-the-opera-19-057","lineIndex":35,"speaker":"","original":"So be it! Now let it be war upon you both!","ipa":"/soʊ bi ɪt naʊ lɛt ɪt bi wɔɹ əpɑn ju boʊθ/","zh":"既然如此 就让战争降临你们！","en":"","note":""},{"id":"phantom-of-the-opera-19-059","lineIndex":36,"speaker":"CHIEF","original":"You understand your instructions?","ipa":"/ju ʌndɚstænd jʊɹ ɪnstɹʌkʃənz/","zh":"都明白指令了吗？","en":"","note":""},{"id":"phantom-of-the-opera-19-061","lineIndex":37,"speaker":"FIREMEN","original":"Sir!","ipa":"/sɜ/","zh":"明白！","en":"","note":""},{"id":"phantom-of-the-opera-19-063","lineIndex":38,"speaker":"CHIEF","original":"When you hear the whistle, take up your positions.","ipa":"/wɛn ju hɪɹ ðə wɪsəl teɪk ʌp jʊɹ pəzɪʃənz/","zh":"听到哨声就各就各位","en":"","note":""},{"id":"phantom-of-the-opera-19-064","lineIndex":39,"speaker":"","original":"I shall then instruct you to secure the doors.","ipa":"/aɪʃɐl ðɛn ɪnstɹʌkt ju tə sᵻkjʊɹ ðə dɔɹz/","zh":"我会下令封锁所有门","en":"","note":""},{"id":"phantom-of-the-opera-19-065","lineIndex":40,"speaker":"","original":"It is essential that all doors are properly secured.","ipa":"/ɪɾ ɪz ᵻsɛnʃəl ðæt ɔl dɔɹz ɑɹ pɹɑpɚli sᵻkjʊɹd/","zh":"必须确保每扇门都牢固","en":"","note":""},{"id":"phantom-of-the-opera-19-067","lineIndex":41,"speaker":"FIRMIN","original":"Are we doing the right thing, Andre?","ipa":"/ɑɹ wi duɪŋ ðə ɹaɪt θɪŋ ɑndɹeɪ/","zh":"我们做得对吗 安德烈？","en":"","note":""},{"id":"phantom-of-the-opera-19-069","lineIndex":42,"speaker":"ANDRE","original":"Have you got a better idea?","ipa":"/hæv ju ɡɑt ɐ bɛɾɚɹ aɪdiə/","zh":"你有更好的主意吗？","en":"","note":""},{"id":"phantom-of-the-opera-19-071","lineIndex":43,"speaker":"CHIEF","original":"Monsieur le Vicomte, am I to give the order?","ipa":"/məsjɜ lə vɪkɑmt æm aɪ tə ɡɪv ðɪ ɔɹdɚ/","zh":"子爵阁下 可以下令了吗？","en":"","note":""},{"id":"phantom-of-the-opera-19-073","lineIndex":44,"speaker":"RAOUL","original":"Give the order.","ipa":"/ɡɪv ðɪ ɔɹdɚ/","zh":"下令吧","en":"","note":""},{"id":"phantom-of-the-opera-19-075","lineIndex":45,"speaker":"RAOUL","original":"You in the pit - do you have a clear view of this box?","ipa":"/ju ɪnðə pɪt du ju hæv ɐ klɪɹ vju ʌv ðɪs bɑks/","zh":"楼下的人 能看清这个包厢吗？","en":"","note":""},{"id":"phantom-of-the-opera-19-077","lineIndex":46,"speaker":"MARKSMAN","original":"Yes, sir.","ipa":"/jɛs sɜ/","zh":"能 阁下","en":"","note":""},{"id":"phantom-of-the-opera-19-079","lineIndex":47,"speaker":"RAOUL","original":"Remember, when the time comes, shoot. Only if you have to - but shoot. To kill.","ipa":"/ɹᵻmɛmbɚ wɛn ðə taɪm kʌmz ʃut oʊnli ɪf ju hæv tʊ bʌt ʃut tə kɪl/","zh":"记住 时机一到就开枪 万不得已时 必须击毙","en":"","note":""},{"id":"phantom-of-the-opera-19-081","lineIndex":48,"speaker":"MARKSMAN","original":"How will I know, sir?","ipa":"/haʊ wɪl aɪ noʊ sɜ/","zh":"如何判断时机 阁下？","en":"","note":""},{"id":"phantom-of-the-opera-19-083","lineIndex":49,"speaker":"RAOUL","original":"You'll know.","ipa":"/jul noʊ/","zh":"你自会知晓","en":"","note":""},{"id":"phantom-of-the-opera-19-085","lineIndex":50,"speaker":"FIRMIN","original":"Monsieur le Vicomte, are you confident that this will work? Will Miss Daae sing?","ipa":"/məsjɜ lə vɪkɑmt ɑɹ ju kɑnfɪdənt ðæt ðɪs wɪl wɜk wɪl mɪs dɑ sɪŋ/","zh":"子爵阁下 您确信这能成功吗？戴伊小姐会演唱吗？","en":"","note":""},{"id":"phantom-of-the-opera-19-087","lineIndex":51,"speaker":"RAOUL","original":"Don't worry, Firmin. Andre?","ipa":"/doʊnt wʌɹi fɜmɪn ɑndɹeɪ/","zh":"别担心 菲尔曼 安德烈？","en":"","note":""},{"id":"phantom-of-the-opera-19-089","lineIndex":52,"speaker":"ANDRE","original":"We're in your hands, sir.","ipa":"/wɪɹ ɪn jʊɹ hændz sɜ/","zh":"我们听您指挥","en":"","note":""},{"id":"phantom-of-the-opera-19-091","lineIndex":53,"speaker":"CHIEF","original":"My men are now in position, sir.","ipa":"/maɪ mɛn ɑɹ naʊ ɪn pəzɪʃən sɜ/","zh":"我的人已就位","en":"","note":""},{"id":"phantom-of-the-opera-19-093","lineIndex":54,"speaker":"RAOUL","original":"Go ahead, then.","ipa":"/ɡoʊ ɐhɛd ðɛn/","zh":"开始行动","en":"","note":""},{"id":"phantom-of-the-opera-19-095","lineIndex":55,"speaker":"CHIEF","original":"Are the doors secure?","ipa":"/ɑɹ ðə dɔɹz sᵻkjʊɹ/","zh":"所有门都锁好了吗？","en":"","note":""},{"id":"phantom-of-the-opera-19-097","lineIndex":56,"speaker":"The FIREMEN answering one by one","original":"\"Secure.\"'","ipa":"/sᵻkjʊɹ/","zh":"\"已锁好\"","en":"","note":""},{"id":"phantom-of-the-opera-19-099","lineIndex":57,"speaker":"PHAN TOM'S VOICE","original":"I'm here: The Phantom of the Opera...","ipa":"/aɪm hɪɹ ðə fæntəm ʌvðɪ ɑpɚɹə/","zh":"我在此：剧院魅影...","en":"","note":""},{"id":"phantom-of-the-opera-19-100","lineIndex":58,"speaker":"","original":"I'm here: The Phantom of the Opera...","ipa":"/aɪm hɪɹ ðə fæntəm ʌvðɪ ɑpɚɹə/","zh":"我在此：剧院魅影...","en":"","note":""},{"id":"phantom-of-the-opera-19-102","lineIndex":59,"speaker":"RAOUL","original":"You fool, I said only when the times comes!","ipa":"/ju ful aɪ sɛd oʊnli wɛn ðə taɪmz kʌmz/","zh":"蠢货 我说了要等时机！","en":"","note":""},{"id":"phantom-of-the-opera-19-104","lineIndex":60,"speaker":"MARKSMAN","original":"But, Monsieur le Vicomte...","ipa":"/bʌt məsjɜ lə vɪkɑmt/","zh":"但是 子爵阁下...","en":"","note":""},{"id":"phantom-of-the-opera-19-106","lineIndex":61,"speaker":"PHANTOM'S VOICE","original":"No \"buts\"! For once, Monsieur le Vicomte is right.","ipa":"/noʊ bʌts fɔɹ wʌns məsjɜ lə vɪkɑmt ɪz ɹaɪt/","zh":"没有\"但是\"！这次子爵说得对","en":"","note":""},{"id":"phantom-of-the-opera-19-107","lineIndex":62,"speaker":"","original":"Seal my fate tonight - I hate to have to cut the fun short but the joke's wearing thin","ipa":"/sil maɪ feɪt tənaɪt aɪ heɪt tə hæv tə kʌt ðə fʌn ʃɔɹt bʌt ðə dʒoʊkz wɛɹɪŋ θɪn/","zh":"今夜注定我的结局 虽不忍打断好戏 但玩笑该收场了","en":"","note":""},{"id":"phantom-of-the-opera-19-108","lineIndex":63,"speaker":"","original":"Let the audience in... let my opera begin!","ipa":"/lɛt ðɪ ɔdiəns ɪn lɛt maɪ ɑpɚɹə bɪɡɪn/","zh":"让观众入场...让我的歌剧开演！","en":"","note":""},{"id":"phantom-of-the-opera-19-109","lineIndex":64,"speaker":"","original":"Don Juan performance","ipa":"/dɑn hwɑn pɚfɔɹməns/","zh":"《唐璜》演出","en":"","note":""},{"id":"phantom-of-the-opera-19-111","lineIndex":65,"speaker":"CHORUS","original":"Here the sire may serve the dam, here the master takes his meat!","ipa":"/hɪɹ ðə saɪɚ meɪ sɜv ðə dæm hɪɹ ðə mæstɚ teɪks hɪz mit/","zh":"此处老爷享用女仆 此处主人大快朵颐！","en":"","note":""},{"id":"phantom-of-the-opera-19-112","lineIndex":66,"speaker":"","original":"Here the sacrificial lam b utters one despairing bleat!","ipa":"/hɪɹ ðə sækɹɪfɪʃəl læm bi ʌɾɚz wʌn dᵻspɛɹɪŋ blit/","zh":"此处祭品羔羊 发出绝望哀啼！","en":"","note":""},{"id":"phantom-of-the-opera-19-114","lineIndex":67,"speaker":"CARLOTTA AND CHORUS","original":"Poor young maiden! For the thrill on your tongue of stolen sweets","ipa":"/pʊɹ jʌŋ meɪdən fɚðə θɹɪl ɔn jʊɹ tʌŋ ʌv stoʊlən swits/","zh":"可怜的少女！为你舌尖偷尝的甜蜜","en":"","note":""},{"id":"phantom-of-the-opera-19-115","lineIndex":68,"speaker":"","original":"you will have to pay the bill -tangled in the winding sheets!","ipa":"/ju wɪl hæv tə peɪ ðə bɪl tæŋɡəld ɪnðə waɪndɪŋ ʃits/","zh":"你将付出代价 被缠绕在寿衣里！","en":"","note":""},{"id":"phantom-of-the-opera-19-116","lineIndex":69,"speaker":"","original":"Serve the meal and serve the maid! Serve the master so that when tables, plans and maids are laid, Don Juan triumphs once again!","ipa":"/sˈɜːv ðə mˈiːl ænd sˈɜːv ðə mˈeɪd sˈɜːv ðə mˈæstɚ sˌoʊ ðæt wɛn tˈeɪbəlz plˈænz ænd mˈeɪdz ɑːɹ lˈeɪd dˈɑːn hwˈɑːn tɹˈaɪʌmfz wˈʌns ɐɡˈɛn/","zh":"端上佳肴与女仆！侍奉主人直到当餐桌 计划与女仆就绪 唐璜将再次胜利！","en":"","note":""},{"id":"phantom-of-the-opera-19-119","lineIndex":70,"speaker":"DON JUAN","original":"Passarino, faithful friend, once again recite the plan.","ipa":"/pæsɑɹɹinoʊ feɪθfəl fɹɛnd wʌns ɐɡɛn ɹᵻsaɪt ðə plæn/","zh":"帕萨里诺 忠实的朋友 再复述一遍计划","en":"","note":""},{"id":"phantom-of-the-opera-19-121","lineIndex":71,"speaker":"PASSARINO","original":"Your young guest believes I'm you - I, the master, you, the man.","ipa":"/jʊɹ jʌŋ ɡɛst bᵻlivz aɪm ju aɪ ðə mæstɚ ju ðə mæn/","zh":"你的客人以为我是你 我扮主人 你扮随从","en":"","note":""},{"id":"phantom-of-the-opera-19-123","lineIndex":72,"speaker":"DON JUAN","original":"When you met you wore my cloak, with my scarf you hid your face.","ipa":"/wɛn ju mɛt ju wɔɹ maɪ kloʊk wɪð maɪ skɑɹf ju hɪd jʊɹ feɪs/","zh":"相遇时你披我的斗篷 用我的围巾遮面","en":"","note":""},{"id":"phantom-of-the-opera-19-124","lineIndex":73,"speaker":"","original":"She believes she dines with me, in her master's borrowed place!","ipa":"/ʃi bᵻlivz ʃi daɪnz wɪð mi ɪn hɜ mæstɚz bɑɹoʊd pleɪs/","zh":"她以为正与主人共餐 在她主人的领地！","en":"","note":""},{"id":"phantom-of-the-opera-19-125","lineIndex":74,"speaker":"","original":"Furtively, we'll scoff and quaff, stealing what, in truth, is mine.","ipa":"/fɜɾɪvli wil skɔf ænd kwɑf stilɪŋ wʌt ɪn tɹuθ ɪz maɪn/","zh":"我们要偷偷痛饮大嚼 窃取本属于我的欢愉","en":"","note":""},{"id":"phantom-of-the-opera-19-126","lineIndex":75,"speaker":"","original":"When it's late and modesty starts to mellow, with the wine...","ipa":"/wɛn ɪts leɪt ænd mɑdəsti stɑɹts tə mɛloʊ wɪððə waɪn/","zh":"当夜深人静 矜持随美酒消退...","en":"","note":""},{"id":"phantom-of-the-opera-19-128","lineIndex":76,"speaker":"PASSARINO","original":"You come home! I use your voice - slam the door like crack of doom!","ipa":"/ju kʌm hoʊm aɪ juz jʊɹ vɔɪs slæm ðə dɔɹ laɪk kɹæk ʌv dum/","zh":"你回家来！我模仿你声音 摔门如末日审判！","en":"","note":""},{"id":"phantom-of-the-opera-19-130","lineIndex":77,"speaker":"DON JUAN","original":"I shall say: \"come - hide with me! Where, oh, where? Of course - my room!\"","ipa":"/aɪʃɐl seɪ kʌm haɪd wɪð mi wɛɹ oʊ wɛɹ ʌv kɔɹs maɪ ɹum/","zh":"我会说\"快来躲我这儿！躲哪？当然是我房间！\"","en":"","note":""},{"id":"phantom-of-the-opera-19-132","lineIndex":78,"speaker":"PASSARINO","original":"Poor thing hasn't got a chance!","ipa":"/pʊɹ θɪŋ hæzənt ɡɑt ɐ tʃæns/","zh":"可怜人毫无胜算！","en":"","note":""},{"id":"phantom-of-the-opera-19-134","lineIndex":79,"speaker":"DON JUAN","original":"Here's my hat, my cloak and sword.","ipa":"/hɪɹz maɪ hæt maɪ kloʊk ænd sɔɹd/","zh":"给你我的帽子斗篷和佩剑","en":"","note":""},{"id":"phantom-of-the-opera-19-135","lineIndex":80,"speaker":"","original":"Conquest is assured, if I do not forget myself and laugh...","ipa":"/kɑŋkwɛst ɪz əʃʊɹd ɪf aɪ dunɑt fɚɡɛt maɪsɛlf ænd læf/","zh":"胜券在握 只要我不忘形笑场...","en":"","note":""},{"id":"phantom-of-the-opera-19-137","lineIndex":81,"speaker":"AMINTA","original":"\"... no thoughts within her head, but thoughts of joy!","ipa":"/noʊ θɔts wɪðɪn hɜ hɛd bʌt θɔts ʌv dʒɔɪ/","zh":"\"...她脑海唯有欢愉！","en":"","note":""},{"id":"phantom-of-the-opera-19-138","lineIndex":82,"speaker":"","original":"No dreams within her heart but dreams of love!\"","ipa":"/noʊ dɹimz wɪðɪn hɜ hɑɹt bʌt dɹimz ʌv lʌv/","zh":"她心间唯存爱意！\"","en":"","note":""},{"id":"phantom-of-the-opera-19-140","lineIndex":83,"speaker":"PASSARINO","original":"Master?","ipa":"/mæstɚ/","zh":"主人？","en":"","note":""},{"id":"phantom-of-the-opera-19-142","lineIndex":84,"speaker":"PHANTOM","original":"Passarino - go away, for the trap is set and waits for its prey!","ipa":"/pæsɑɹɹinoʊ ɡoʊ ɐweɪ fɚðə tɹæp ɪz sɛt ænd weɪts fɔɹ ɪts pɹeɪ/","zh":"帕萨里诺 快离开 陷阱已布好 静待猎物来！","en":"","note":""}],"sourceOrder":19,"displayOrder":16},{"order":20,"id":"20-the-point-of-no-return-live","title":"The Point Of No Return","titleZh":"不归点","lines":[{"id":"phantom-of-the-opera-20-001","lineIndex":1,"speaker":"PHANTOM","original":"Past the point of no return","ipa":"/fæntəm koʊlən pæst ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"一越过了不归点","en":"","note":""},{"id":"phantom-of-the-opera-20-002","lineIndex":2,"speaker":"","original":"no backward glances","ipa":"/noʊ bækwɚd ɡlænsᵻz/","zh":"就无法再回头","en":"","note":""},{"id":"phantom-of-the-opera-20-003","lineIndex":3,"speaker":"","original":"the games we've played till now are at an end...","ipa":"/ðə ɡeɪmz wiv pleɪd tɪl naʊ ɑɹ æɾ ɐn ɛnd/","zh":"我们的伪装游戏已至尾声","en":"","note":""},{"id":"phantom-of-the-opera-20-004","lineIndex":4,"speaker":"","original":"Past all thought of \"if\" or \"when\" no use resisting","ipa":"/pæst ɔl θɔt ʌv ɪf ɔɹ wɛn noʊ jus ɹᵻzɪstɪŋ/","zh":"越过了“如果”或“何时”的念头","en":"","note":""},{"id":"phantom-of-the-opera-20-005","lineIndex":5,"speaker":"","original":"abandon thought, and let the dream descend","ipa":"/ɐbændən θɔt ænd lɛt ðə dɹim dᵻsɛnd/","zh":"抵抗也无济于事 放弃疑虑 让梦沉淀","en":"","note":""},{"id":"phantom-of-the-opera-20-006","lineIndex":6,"speaker":"","original":"What raging fire shall flood the soul?","ipa":"/wʌt ɹeɪdʒɪŋ faɪɚ ʃæl flʌd ðə soʊl/","zh":"如怒火淹没灵魂","en":"","note":""},{"id":"phantom-of-the-opera-20-007","lineIndex":7,"speaker":"","original":"What rich desire unlock its door?","ipa":"/wʌt ɹɪtʃ dɪzaɪɚɹ ʌnlɑk ɪts dɔɹ/","zh":"如浓烈欲望开启心扉","en":"","note":""},{"id":"phantom-of-the-opera-20-008","lineIndex":8,"speaker":"","original":"What sweet seduction lies before us?","ipa":"/wʌt swit sᵻdʌkʃən laɪz bᵻfɔɹ ʌs/","zh":"如甜蜜诱惑呈现眼前","en":"","note":""},{"id":"phantom-of-the-opera-20-009","lineIndex":9,"speaker":"","original":"Past the point of no return","ipa":"/pæst ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"一越过了不归点","en":"","note":""},{"id":"phantom-of-the-opera-20-010","lineIndex":10,"speaker":"","original":"the final threshold","ipa":"/ðə faɪnəl θɹɛʃoʊld/","zh":"这最终的门槛","en":"","note":""},{"id":"phantom-of-the-opera-20-011","lineIndex":11,"speaker":"","original":"what warm, unspoken secrets will we learn?","ipa":"/wʌt wɔɹm ʌnspoʊkən sikɹᵻts wɪl wi lɜn/","zh":"是何不可言喻的秘密 我们将知晓","en":"","note":""},{"id":"phantom-of-the-opera-20-012","lineIndex":12,"speaker":"","original":"Beyond the point of no return...","ipa":"/bᵻjɔnd ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"在不归点之外","en":"","note":""},{"id":"phantom-of-the-opera-20-014","lineIndex":13,"speaker":"CHRISTINE","original":"You have brought me to that moment","ipa":"/ju hæv bɹɔt mi tə ðæt moʊmənt/","zh":"你已带给了我","en":"","note":""},{"id":"phantom-of-the-opera-20-015","lineIndex":14,"speaker":"","original":"where words run dry","ipa":"/wɛɹ wɜdz ɹʌn dɹaɪ/","zh":"直到文字干涸枯竭的那一刻","en":"","note":""},{"id":"phantom-of-the-opera-20-016","lineIndex":15,"speaker":"","original":"to that moment","ipa":"/tə ðæt moʊmənt/","zh":"直到言语","en":"","note":""},{"id":"phantom-of-the-opera-20-017","lineIndex":16,"speaker":"","original":"where speech disappears into silence","ipa":"/wɛɹ spitʃ dɪsɐpɪɹz ɪntʊ saɪləns/","zh":"无影无踪的那一刻 化作寂静","en":"","note":""},{"id":"phantom-of-the-opera-20-018","lineIndex":17,"speaker":"","original":"silence...","ipa":"/saɪləns/","zh":"寂静...","en":"","note":""},{"id":"phantom-of-the-opera-20-019","lineIndex":18,"speaker":"","original":"hardly knowing the reason why","ipa":"/hɑɹdli noʊɪŋ ðə ɹizən waɪ/","zh":"几乎不明究理","en":"","note":""},{"id":"phantom-of-the-opera-20-020","lineIndex":19,"speaker":"","original":"In my mind","ipa":"/ɪn maɪ maɪnd/","zh":"在我心中","en":"","note":""},{"id":"phantom-of-the-opera-20-021","lineIndex":20,"speaker":"","original":"I've already imagined our bodies entwining","ipa":"/aɪv ɔlɹɛdi ɪmædʒɪnd aʊɚ bɑdiz ɛntwaɪnɪŋ/","zh":"我已经想像过 我俩的身体缠绵不清","en":"","note":""},{"id":"phantom-of-the-opera-20-022","lineIndex":21,"speaker":"","original":"defenceless and silent","ipa":"/dᵻfɛnsləs ænd saɪlənt/","zh":"毫无戒备、一语不发","en":"","note":""},{"id":"phantom-of-the-opera-20-023","lineIndex":22,"speaker":"","original":"and now I am here with you","ipa":"/ænd naʊ aɪɐm hɪɹ wɪð ju/","zh":"如今我与你在此","en":"","note":""},{"id":"phantom-of-the-opera-20-024","lineIndex":23,"speaker":"","original":"no second thoughts","ipa":"/noʊ sɛkənd θɔts/","zh":"别无二心","en":"","note":""},{"id":"phantom-of-the-opera-20-025","lineIndex":24,"speaker":"","original":"I've decided","ipa":"/aɪv dᵻsaɪdᵻd/","zh":"我已下定决心","en":"","note":""},{"id":"phantom-of-the-opera-20-026","lineIndex":25,"speaker":"","original":"decided...","ipa":"/dᵻsaɪdᵻd/","zh":"已下定决心","en":"","note":""},{"id":"phantom-of-the-opera-20-027","lineIndex":26,"speaker":"","original":"Past the point of no return","ipa":"/pæst ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"一越过了不归点","en":"","note":""},{"id":"phantom-of-the-opera-20-028","lineIndex":27,"speaker":"","original":"no going back now","ipa":"/noʊ ɡoʊɪŋ bæk naʊ/","zh":"现在已无法回头","en":"","note":""},{"id":"phantom-of-the-opera-20-029","lineIndex":28,"speaker":"","original":"our passion play has now at last begun","ipa":"/aʊɚ pæʃən pleɪ hɐz naʊ æt læst bɪɡʌn/","zh":"我们的激情戏如今终于揭幕","en":"","note":""},{"id":"phantom-of-the-opera-20-030","lineIndex":29,"speaker":"","original":"Past all thought of right or wrong","ipa":"/pæst ɔl θɔt ʌv ɹaɪt ɔɹ ɹɔŋ/","zh":"不论是对或错","en":"","note":""},{"id":"phantom-of-the-opera-20-031","lineIndex":30,"speaker":"","original":"one final question:","ipa":"/wʌn faɪnəl kwɛstʃən/","zh":"最后一个问题","en":"","note":""},{"id":"phantom-of-the-opera-20-032","lineIndex":31,"speaker":"","original":"how long should we two wait","ipa":"/haʊ lɔŋ ʃʊd wi tu weɪt/","zh":"还要等多久","en":"","note":""},{"id":"phantom-of-the-opera-20-033","lineIndex":32,"speaker":"","original":"before we're one?","ipa":"/bᵻfɔɹ wɪɹ wʌn/","zh":"我俩才能结合？","en":"","note":""},{"id":"phantom-of-the-opera-20-034","lineIndex":33,"speaker":"","original":"When will the blood begin to race","ipa":"/wɛn wɪl ðə blʌd bɪɡɪn tə ɹeɪs/","zh":"何时才能血液沸腾？","en":"","note":""},{"id":"phantom-of-the-opera-20-035","lineIndex":34,"speaker":"","original":"the sleeping bud burst into bloom?","ipa":"/ðə slipɪŋ bʌd bɜst ɪntʊ blum/","zh":"沉睡的花蕾才能绽放出花瓣？","en":"","note":""},{"id":"phantom-of-the-opera-20-036","lineIndex":35,"speaker":"","original":"When will the flames at last consume us?","ipa":"/wɛn wɪl ðə fleɪmz æt læst kənsum ʌs/","zh":"何时火焰终将耗尽我们？","en":"","note":""},{"id":"phantom-of-the-opera-20-038","lineIndex":36,"speaker":"BOTH","original":"Past the point of no return","ipa":"/pæst ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"一越过了不归点","en":"","note":""},{"id":"phantom-of-the-opera-20-039","lineIndex":37,"speaker":"","original":"the final threshold","ipa":"/ðə faɪnəl θɹɛʃoʊld/","zh":"这最终的门槛","en":"","note":""},{"id":"phantom-of-the-opera-20-040","lineIndex":38,"speaker":"","original":"the bridge is crossed","ipa":"/ðə bɹɪdʒ ɪz kɹɔst/","zh":"已越过了桥梁","en":"","note":""},{"id":"phantom-of-the-opera-20-041","lineIndex":39,"speaker":"","original":"so stand and watch it burn","ipa":"/soʊ stænd ænd wɑtʃ ɪt bɜn/","zh":"就站着看它燃烧","en":"","note":""},{"id":"phantom-of-the-opera-20-042","lineIndex":40,"speaker":"","original":"We've passed the point of no return","ipa":"/wiv pæst ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"我们已越过了不归点","en":"","note":""},{"id":"phantom-of-the-opera-20-043","lineIndex":41,"speaker":"","original":"Say you'll share with me","ipa":"/seɪ jul ʃɛɹ wɪð mi/","zh":"说你愿与我共享...","en":"","note":""},{"id":"phantom-of-the-opera-20-044","lineIndex":42,"speaker":"","original":"one love, one life time","ipa":"/wʌn lʌv wʌn laɪf taɪm/","zh":"坚定爱情，一生一世","en":"","note":""},{"id":"phantom-of-the-opera-20-045","lineIndex":43,"speaker":"","original":"Lead me, save me from my solitude","ipa":"/lid mi seɪv mi fɹʌm maɪ sɑlɪtud/","zh":"指引我、拯救我走出孤独","en":"","note":""},{"id":"phantom-of-the-opera-20-046","lineIndex":44,"speaker":"","original":"Say you want me with you","ipa":"/seɪ ju wɔnt mi wɪð ju/","zh":"说你需要我 陪你在此","en":"","note":""},{"id":"phantom-of-the-opera-20-047","lineIndex":45,"speaker":"","original":"here beside you","ipa":"/hɪɹ bᵻsaɪd ju/","zh":"伴你身旁","en":"","note":""},{"id":"phantom-of-the-opera-20-048","lineIndex":46,"speaker":"","original":"Anywhere you go let me go too","ipa":"/ɛnɪwɛɹ ju ɡoʊ lɛt mi ɡoʊ tu/","zh":"不论身往何方 也让我同行","en":"","note":""},{"id":"phantom-of-the-opera-20-049","lineIndex":47,"speaker":"","original":"Christine, that's all I ask of...","ipa":"/kɹɪstin ðæts ɔl aɪ æsk ʌv/","zh":"克莉丝汀，那就是仅有的要求...","en":"","note":""},{"id":"phantom-of-the-opera-20-051","lineIndex":48,"speaker":"CARLOTTA","original":"What is it? What has happened? Ubaldo!","ipa":"/wʌt ɪz ɪt wʌt hɐz hæpənd jubɔldoʊ/","zh":"亲爱的，亲爱的，这是谁做的？","en":"","note":""},{"id":"phantom-of-the-opera-20-053","lineIndex":49,"speaker":"ANDRE","original":"We're ruined, Andre - ruined!","ipa":"/wɪɹ ɹuɪnd ɑndɹeɪ ɹuɪnd/","zh":"我们逃吧 安卓 快逃","en":"","note":""},{"id":"phantom-of-the-opera-20-055","lineIndex":50,"speaker":"GIRY","original":"Monsieur le Vicomte! Come with me!","ipa":"/məsjɜ lə vɪkɑmt kʌm wɪð mi/","zh":"跟我来，子爵先生","en":"","note":""},{"id":"phantom-of-the-opera-20-057","lineIndex":51,"speaker":"CARLOTTA","original":"Oh, my darling, my darling...","ipa":"/oʊ maɪ dɑɹlɪŋ maɪ dɑɹlɪŋ/","zh":"亲爱的，亲爱的","en":"","note":""},{"id":"phantom-of-the-opera-20-058","lineIndex":52,"speaker":"","original":"who has done this? You!","ipa":"/hu hɐz dʌn ðɪs ju/","zh":"这是谁做的？","en":"","note":""},{"id":"phantom-of-the-opera-20-059","lineIndex":53,"speaker":"","original":"Why did you let this happen?","ipa":"/waɪ dɪd ju lɛt ðɪs hæpən/","zh":"为什么，是你做的？","en":"","note":""},{"id":"phantom-of-the-opera-20-062","lineIndex":54,"speaker":"RAOUL","original":"But can I trust you?","ipa":"/bʌt kæn aɪ tɹʌst ju/","zh":"我能相信你吗？","en":"","note":""},{"id":"phantom-of-the-opera-20-064","lineIndex":55,"speaker":"GIRY","original":"You must. But remember:","ipa":"/ju mʌst bʌt ɹᵻmɛmbɚ/","zh":"你必须，但切记","en":"","note":""},{"id":"phantom-of-the-opera-20-065","lineIndex":56,"speaker":"","original":"your hand at the level of your eyes!","ipa":"/jʊɹ hænd æt ðə lɛvəl ʌv jʊɹ aɪz/","zh":"手保持与眼睛一样的高度","en":"","note":""},{"id":"phantom-of-the-opera-20-067","lineIndex":57,"speaker":"RAOUL","original":"But why...?","ipa":"/bʌt waɪ/","zh":"为什么？","en":"","note":""},{"id":"phantom-of-the-opera-20-069","lineIndex":58,"speaker":"GIRY","original":"Why? The Punjab lasso, monsieur.","ipa":"/waɪ ðə pʌndʒɑb læsoʊ məsjɜ/","zh":"为什么？旁遮普，套索，老板","en":"","note":""},{"id":"phantom-of-the-opera-20-070","lineIndex":59,"speaker":"","original":"First Buquet. Now Piangi.","ipa":"/fɜst bjukeɪ naʊ paɪəŋɡi/","zh":"先是布列特，现在皮安齐","en":"","note":""},{"id":"phantom-of-the-opera-20-072","lineIndex":60,"speaker":"MEG","original":"Like this, monsieur. I'll come with you.","ipa":"/laɪk ðɪs məsjɜ aɪl kʌm wɪð ju/","zh":"像这样，老板，我跟你去","en":"","note":""},{"id":"phantom-of-the-opera-20-074","lineIndex":61,"speaker":"GIRY","original":"No, Meg! No, you stay here!","ipa":"/noʊ mɛɡ noʊ ju steɪ hɪɹ/","zh":"不行，梅格，你必须留在这里","en":"","note":""},{"id":"phantom-of-the-opera-20-075","lineIndex":62,"speaker":"","original":"Come with me, monsieur.","ipa":"/kʌm wɪð mi məsjɜ/","zh":"跟我来，先生。","en":"","note":""},{"id":"phantom-of-the-opera-20-076","lineIndex":63,"speaker":"","original":"Hurry, or we shall be too late...","ipa":"/hɜɹi ɔɹ wiʃɐl bi tu leɪt/","zh":"跟我来，先生，否则来不及了","en":"","note":""}],"sourceOrder":20,"displayOrder":17},{"order":21,"id":"21-down-once-more-track-down-this-murderer-live","title":"Down Once More.../Track Down This Murderer...","titleZh":"再次下行……／追捕这个凶手……","lines":[{"id":"phantom-of-the-opera-21-001","lineIndex":1,"speaker":"","original":"Down once more to the dungeon of my black despair!","ipa":"/daʊn wʌns mɔɹ tə ðə dʌndʒən ʌv maɪ blæk dᵻspɛɹ/","zh":"再次奔向我黑色绝望的地牢底下","en":"","note":""},{"id":"phantom-of-the-opera-21-002","lineIndex":2,"speaker":"","original":"Down we plunge to the prison of my mind!","ipa":"/daʊn wi plʌndʒ tə ðə pɹɪzən ʌv maɪ maɪnd/","zh":"坠入我心灵的囚房","en":"","note":""},{"id":"phantom-of-the-opera-21-003","lineIndex":3,"speaker":"","original":"Down that path into darkness deep as hell!","ipa":"/daʊn ðæt pæθ ɪntʊ dɑɹknəs dip æz hɛl/","zh":"走下那隐没黑暗中的路径，深如地狱","en":"","note":""},{"id":"phantom-of-the-opera-21-004","lineIndex":4,"speaker":"","original":"Why, you ask, was I bound and chained in this cold and dismal place?","ipa":"/waɪ ju æsk wʌz aɪ baʊnd ænd tʃeɪnd ɪn ðɪs koʊld ænd dɪzməl pleɪs/","zh":"你问我为何，受禁锢枷锁，在这又冷又暗的地方？","en":"","note":""},{"id":"phantom-of-the-opera-21-005","lineIndex":5,"speaker":"","original":"Not for any mortal sin, but the wickedness of my abhorrent face!","ipa":"/nɑt fɔɹ ɛni mɔɹɾəl sɪn bʌt ðə wɪkᵻdnəs ʌv maɪ ɐbhɔɹənt feɪs/","zh":"不是因为犯了任何罪过，而是因为我其貌不扬的脸，所造成的不悦","en":"","note":""},{"id":"phantom-of-the-opera-21-006","lineIndex":6,"speaker":"","original":"Hounded out by everyone!","ipa":"/haʊndᵻd aʊt baɪ ɛvɹɪwʌn/","zh":"循线追查凶手","en":"","note":""},{"id":"phantom-of-the-opera-21-007","lineIndex":7,"speaker":"","original":"Met with hatred everywhere!","ipa":"/mɛt wɪð heɪtɹɪd ɛvɹɪwɛɹ/","zh":"务必要找到他","en":"","note":""},{"id":"phantom-of-the-opera-21-008","lineIndex":8,"speaker":"","original":"No kind word from anyone!","ipa":"/noʊ kaɪnd wɜd fɹʌm ɛnɪwʌn/","zh":"被人人所追捕","en":"","note":""},{"id":"phantom-of-the-opera-21-009","lineIndex":9,"speaker":"","original":"No compassion anywhere!","ipa":"/noʊ kəmpæʃən ɛnɪwɛɹ/","zh":"处处受人仇视","en":"","note":""},{"id":"phantom-of-the-opera-21-010","lineIndex":10,"speaker":"","original":"Christine, Christine...","ipa":"/kɹɪstin kɹɪstin/","zh":"没人和言悦色","en":"","note":""},{"id":"phantom-of-the-opera-21-011","lineIndex":11,"speaker":"","original":"Why, why...?","ipa":"/waɪ waɪ/","zh":"处处不见怜悯","en":"","note":""},{"id":"phantom-of-the-opera-21-012","lineIndex":12,"speaker":"","original":"Your hand at the level of your eyes!","ipa":"/jʊɹ hænd æt ðə lɛvəl ʌv jʊɹ aɪz/","zh":"将手举至与眼同高","en":"","note":""},{"id":"phantom-of-the-opera-21-013","lineIndex":13,"speaker":"","original":"... at the level of your eyes...","ipa":"/æt ðə lɛvəl ʌv jʊɹ aɪz/","zh":"与眼同高","en":"","note":""},{"id":"phantom-of-the-opera-21-014","lineIndex":14,"speaker":"","original":"Your hand at the level of your eyes!","ipa":"/jʊɹ hænd æt ðə lɛvəl ʌv jʊɹ aɪz/","zh":"将手举至与眼同高","en":"","note":""},{"id":"phantom-of-the-opera-21-015","lineIndex":15,"speaker":"","original":"Track down this murderer he must be found!","ipa":"/tɹæk daʊn ðɪs mɜdɚɹɚ hi mʌst bi faʊnd/","zh":"循线追查凶手，务必要找到他","en":"","note":""},{"id":"phantom-of-the-opera-21-016","lineIndex":16,"speaker":"","original":"Hunt out this animal, who runs to ground!","ipa":"/hʌnt aʊt ðɪs ænɪməl hu ɹʌnz tə ɡɹaʊnd/","zh":"追捕这深藏地底怪物","en":"","note":""},{"id":"phantom-of-the-opera-21-017","lineIndex":17,"speaker":"","original":"Too long he's preyed on us","ipa":"/tu lɔŋ hiz pɹeɪd ɔn ʌs/","zh":"他折磨我们太久了","en":"","note":""},{"id":"phantom-of-the-opera-21-018","lineIndex":18,"speaker":"","original":"but now we know, the phantom of the opera is here deep down inside!","ipa":"/bˌʌt nˈaʊ wiː nˈoʊ ðə fˈæntəm ʌvðɪ ˈɑːpɚɹə ɪz hˈɪɹ dˈiːp dˌaʊn ɪnsˈaɪd/","zh":"但现在我们知道，剧院魅影就在那里地窖深处","en":"","note":""},{"id":"phantom-of-the-opera-21-020","lineIndex":19,"speaker":"","original":"He's here the Phantom of the Opera...","ipa":"/hiz hɪɹ ðə fæntəm ʌvðɪ ɑpɚɹə/","zh":"他就在这里，剧院魅影","en":"","note":""},{"id":"phantom-of-the-opera-21-021","lineIndex":20,"speaker":"","original":"He's here the Phantom of the Opera...","ipa":"/hiz hɪɹ ðə fæntəm ʌvðɪ ɑpɚɹə/","zh":"他就在这里，剧院魅影","en":"","note":""},{"id":"phantom-of-the-opera-21-022","lineIndex":21,"speaker":"","original":"Have you gorged yourself at last in your lust for blood?","ipa":"/hæv ju ɡɔɹdʒd jɔɹsɛlf æt læst ɪn jʊɹ lʌst fɔɹ blʌd/","zh":"你是否终于饱食了你嗜血的欲望？","en":"","note":""},{"id":"phantom-of-the-opera-21-023","lineIndex":22,"speaker":"","original":"Am I now to be prey to your lust for flesh?","ipa":"/æm aɪ naʊ təbi pɹeɪ tə jʊɹ lʌst fɔɹ flɛʃ/","zh":"现在我是否成了你嗜肉欲望的猎物？","en":"","note":""},{"id":"phantom-of-the-opera-21-024","lineIndex":23,"speaker":"","original":"That fate which condemns me to wallow in blood","ipa":"/ðæt feɪt wɪtʃ kəndɛmz mi tə wɔloʊ ɪn blʌd/","zh":"命运诅咒我在鲜血中打滚","en":"","note":""},{"id":"phantom-of-the-opera-21-025","lineIndex":24,"speaker":"","original":"has also denied me the joys of the flesh...","ipa":"/hɐz ɔlsoʊ dᵻnaɪd mi ðə dʒɔɪz ʌvðə flɛʃ/","zh":"也否绝了我对肉体的喜悦","en":"","note":""},{"id":"phantom-of-the-opera-21-026","lineIndex":25,"speaker":"","original":"This face - the infection which poisons our love...","ipa":"/ðɪs feɪs ðɪ ɪnfɛkʃən wɪtʃ pɔɪzənz aʊɚ lʌv/","zh":"这张脸，乃毒害我们爱情的传染病","en":"","note":""},{"id":"phantom-of-the-opera-21-027","lineIndex":26,"speaker":"","original":"This face, which earned a mother's fear and loathing...","ipa":"/ðɪs feɪs wɪtʃ ɜnd ɐ mʌðɚz fɪɹ ænd loʊðɪŋ/","zh":"这张脸，换来了母亲的畏惧和嫌弃","en":"","note":""},{"id":"phantom-of-the-opera-21-028","lineIndex":27,"speaker":"","original":"A mask, my first unfeeling scrap of clothing...","ipa":"/ɐ mæsk maɪ fɜst ʌnfilɪŋ skɹæp ʌv kloʊðɪŋ/","zh":"面具，是我第一件冷酷的零星衣物","en":"","note":""},{"id":"phantom-of-the-opera-21-029","lineIndex":28,"speaker":"","original":"Pity comes too late - turn around","ipa":"/pɪɾi kʌmz tu leɪt tɜn ɚɹaʊnd/","zh":"怜悯来的太迟，转身","en":"","note":""},{"id":"phantom-of-the-opera-21-030","lineIndex":29,"speaker":"","original":"and face your fate: an eternity of this before your eyes!","ipa":"/ænd feɪs jʊɹ feɪt ɐn ɪtɜnᵻɾi ʌv ðɪs bᵻfɔɹ jʊɹ aɪz/","zh":"面对你的命运","en":"","note":""},{"id":"phantom-of-the-opera-21-031","lineIndex":30,"speaker":"","original":"This haunted face holds no horror for me now...","ipa":"/ðɪs hɔntᵻd feɪs hoʊldz noʊ hɔɹɚ fɔɹ mi naʊ/","zh":"这张鬼魅般的脸，如今对我已不觉可怕","en":"","note":""},{"id":"phantom-of-the-opera-21-032","lineIndex":31,"speaker":"","original":"It's in your soul that the true distortion lies...","ipa":"/ɪts ɪn jʊɹ soʊl ðætðə tɹu dɪstɔɹʃən laɪz/","zh":"真正扭曲的是你的灵魂","en":"","note":""},{"id":"phantom-of-the-opera-21-033","lineIndex":32,"speaker":"","original":"Wait! I think, my dear, we have a guest!","ipa":"/weɪt aɪ θɪŋk maɪ dɪɹ wi hæv ɐ ɡɛst/","zh":"等一下！亲爱的，我想我们有位客人来了","en":"","note":""},{"id":"phantom-of-the-opera-21-034","lineIndex":33,"speaker":"","original":"Sir, this is indeed an unparalleled delight!","ipa":"/sɜ ðɪs ɪz ɪndid ɐn ʌnpæɹəlɛld dᵻlaɪt/","zh":"先生，真是无比欢欣","en":"","note":""},{"id":"phantom-of-the-opera-21-035","lineIndex":34,"speaker":"","original":"I had rather hoped that you would come.","ipa":"/aɪ hæd ɹæðɚ hoʊpt ðæt ju wʊd kʌm/","zh":"我早就希望你会来","en":"","note":""},{"id":"phantom-of-the-opera-21-036","lineIndex":35,"speaker":"","original":"And now my wish comes true - you have truly made my night!","ipa":"/ænd naʊ maɪ wɪʃ kʌmz tɹu ju hæv tɹuli meɪd maɪ naɪt/","zh":"如今我的愿望实现了，你真的令我这一夜精彩万分","en":"","note":""},{"id":"phantom-of-the-opera-21-037","lineIndex":36,"speaker":"","original":"Free her!","ipa":"/fɹi hɜ/","zh":"放了她","en":"","note":""},{"id":"phantom-of-the-opera-21-038","lineIndex":37,"speaker":"","original":"Do what you like only free her!","ipa":"/du wʌt ju laɪk oʊnli fɹi hɜ/","zh":"随你高兴怎样，只管放了她","en":"","note":""},{"id":"phantom-of-the-opera-21-039","lineIndex":38,"speaker":"","original":"Have you no pity?","ipa":"/hæv ju noʊ pɪɾi/","zh":"你难道没同情心吗？","en":"","note":""},{"id":"phantom-of-the-opera-21-040","lineIndex":39,"speaker":"","original":"Your lover makes a passionate plea!","ipa":"/jʊɹ lʌvɚ meɪks ɐ pæʃənət pli/","zh":"你的爱人作出多情的请求","en":"","note":""},{"id":"phantom-of-the-opera-21-041","lineIndex":40,"speaker":"","original":"Please Raoul, it's useless!","ipa":"/pliz ɹeɪəʌl ɪts jusləs/","zh":"拜讬，劳尔，没用的","en":"","note":""},{"id":"phantom-of-the-opera-21-042","lineIndex":41,"speaker":"","original":"I love her!","ipa":"/aɪ lʌv hɜ/","zh":"我爱她！","en":"","note":""},{"id":"phantom-of-the-opera-21-043","lineIndex":42,"speaker":"","original":"Does that mean nothing?","ipa":"/dʌz ðæt min nʌθɪŋ/","zh":"那不具任何意义吗？","en":"","note":""},{"id":"phantom-of-the-opera-21-044","lineIndex":43,"speaker":"","original":"I love her!","ipa":"/aɪ lʌv hɜ/","zh":"我爱她！","en":"","note":""},{"id":"phantom-of-the-opera-21-045","lineIndex":44,"speaker":"","original":"Show some compassion...","ipa":"/ʃoʊ sʌm kəmpæʃən/","zh":"表现点同情吧","en":"","note":""},{"id":"phantom-of-the-opera-21-046","lineIndex":45,"speaker":"","original":"The world showed no compassion to me!","ipa":"/ðə wɜld ʃoʊd noʊ kəmpæʃən tə mi/","zh":"这世界可没对我表现出同情！","en":"","note":""},{"id":"phantom-of-the-opera-21-047","lineIndex":46,"speaker":"","original":"Christine, Christine...","ipa":"/kɹɪstin kɹɪstin/","zh":"克里斯汀，克里斯汀","en":"","note":""},{"id":"phantom-of-the-opera-21-048","lineIndex":47,"speaker":"","original":"Let me see her...","ipa":"/lɛt mi si hɜ/","zh":"让我见见她","en":"","note":""},{"id":"phantom-of-the-opera-21-049","lineIndex":48,"speaker":"","original":"Be my guest, sir...","ipa":"/bi maɪ ɡɛst sɜ/","zh":"请便，先生","en":"","note":""},{"id":"phantom-of-the-opera-21-050","lineIndex":49,"speaker":"","original":"Monsieur, I bid you welcome!","ipa":"/məsjɜ aɪ bɪd ju wɛlkʌm/","zh":"先生，欢迎大驾光临","en":"","note":""},{"id":"phantom-of-the-opera-21-051","lineIndex":50,"speaker":"","original":"Did you think that I would harm her?","ipa":"/dɪd ju θɪŋk ðæt aɪ wʊd hɑɹm hɜ/","zh":"你以为我会伤害她吗？","en":"","note":""},{"id":"phantom-of-the-opera-21-052","lineIndex":51,"speaker":"","original":"Why should I make her pay for the sins which are yours?","ipa":"/waɪ ʃʊd aɪ meɪk hɜ peɪ fɚðə sɪnz wɪtʃ ɑɹ jɔɹz/","zh":"为何你们所犯的罪过，我要她来承担呢？","en":"","note":""},{"id":"phantom-of-the-opera-21-053","lineIndex":52,"speaker":"","original":"Order your fine horses now!","ipa":"/ɔɹdɚ jʊɹ faɪn hɔɹsᵻz naʊ/","zh":"马上备好你的良驹","en":"","note":""},{"id":"phantom-of-the-opera-21-054","lineIndex":53,"speaker":"","original":"Raise up your hand to the level of your eyes!","ipa":"/ɹeɪz ʌp jʊɹ hænd tə ðə lɛvəl ʌv jʊɹ aɪz/","zh":"把你的手举至与眼同高","en":"","note":""},{"id":"phantom-of-the-opera-21-055","lineIndex":54,"speaker":"","original":"Nothing can save you now - except perhaps Christine...","ipa":"/nʌθɪŋ kæn seɪv ju naʊ ɛksɛpt pɚhæps kɹɪstin/","zh":"现在什么也救不了你，或许除了克莉丝汀之外","en":"","note":""},{"id":"phantom-of-the-opera-21-056","lineIndex":55,"speaker":"","original":"Start a new life with me -","ipa":"/stɑɹt ɐ nu laɪf wɪð mi/","zh":"陪我展开新生活","en":"","note":""},{"id":"phantom-of-the-opera-21-057","lineIndex":56,"speaker":"","original":"Buy his freedom with your love!","ipa":"/baɪ hɪz fɹidəm wɪð jʊɹ lʌv/","zh":"用你的爱情换取他的自由","en":"","note":""},{"id":"phantom-of-the-opera-21-058","lineIndex":57,"speaker":"","original":"Refuse me, and you send your lover to his death!","ipa":"/ɹᵻfjuz mi ænd ju sɛnd jʊɹ lʌvɚ tə hɪz dɛθ/","zh":"拒绝我就等于判处你的爱人死刑","en":"","note":""},{"id":"phantom-of-the-opera-21-059","lineIndex":58,"speaker":"","original":"This is the choice -","ipa":"/ðɪs ɪz ðə tʃɔɪs/","zh":"这就是抉择","en":"","note":""},{"id":"phantom-of-the-opera-21-060","lineIndex":59,"speaker":"","original":"This is the point of no return!","ipa":"/ðɪs ɪz ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"这就是不归点","en":"","note":""},{"id":"phantom-of-the-opera-21-061","lineIndex":60,"speaker":"","original":"The tears I might have shed for your dark fate grow cold","ipa":"/ðə tɪɹz aɪ maɪthɐv ʃɛd fɔɹ jʊɹ dɑɹk feɪt ɡɹoʊ koʊld/","zh":"我可能为你黑暗命运淌下的泪水，已逐渐冷却","en":"","note":""},{"id":"phantom-of-the-opera-21-062","lineIndex":61,"speaker":"","original":"and turn to tears of hate!","ipa":"/ænd tɜn tə tɪɹz ʌv heɪt/","zh":"并转为恨的泪水！","en":"","note":""},{"id":"phantom-of-the-opera-21-063","lineIndex":62,"speaker":"","original":"Christine, forgive me please forgive me...","ipa":"/kɹɪstin fɚɡɪv mi pliz fɚɡɪv mi/","zh":"克莉丝汀，原谅我，请原谅我","en":"","note":""},{"id":"phantom-of-the-opera-21-064","lineIndex":63,"speaker":"","original":"I did it all for you, and all for nothing...","ipa":"/aɪ dɪd ɪɾ ɔl fɔɹ ju ænd ɔl fɔɹ nʌθɪŋ/","zh":"我做的全是为了你，然而却一无所获","en":"","note":""},{"id":"phantom-of-the-opera-21-065","lineIndex":64,"speaker":"","original":"Farewell my fallen idol and false friend...","ipa":"/fɛɹwɛl maɪ fɔlən aɪdəl ænd fɔls fɹɛnd/","zh":"别了，我堕落的偶像、虚假的朋友","en":"","note":""},{"id":"phantom-of-the-opera-21-066","lineIndex":65,"speaker":"","original":"We had such hopes, and now those hopes are shattered!","ipa":"/wi hæd sʌtʃ hoʊps ænd naʊ ðoʊz hoʊps ɑɹ ʃæɾɚd/","zh":"我们原本有希望，如今希望已破碎","en":"","note":""},{"id":"phantom-of-the-opera-21-067","lineIndex":66,"speaker":"","original":"Too late for turning back, too late for prayers and useless pity!","ipa":"/tu leɪt fɔɹ tɜnɪŋ bæk tu leɪt fɔɹ pɹɛɹz ænd jusləs pɪɾi/","zh":"回头已太迟，祈祷和无用的同情亦太迟","en":"","note":""},{"id":"phantom-of-the-opera-21-068","lineIndex":67,"speaker":"","original":"Say you love him and my life is over","ipa":"/seɪ ju lʌv hɪm ænd maɪ laɪf ɪz oʊvɚ/","zh":"说你爱他，我的人生则毁！","en":"","note":""},{"id":"phantom-of-the-opera-21-069","lineIndex":68,"speaker":"","original":"All hope of cries for help; no point in fighting!","ipa":"/ɔl hoʊp ʌv kɹaɪz fɔɹ hɛlp noʊ pɔɪnt ɪn faɪɾɪŋ/","zh":"所有求救的希望，抵抗也无用","en":"","note":""},{"id":"phantom-of-the-opera-21-070","lineIndex":69,"speaker":"","original":"For either way you choose, he has to win/you cannot win!","ipa":"/fɔɹ iðɚ weɪ ju tʃuz hi hɐz tə wɪn slæʃ ju kænɑt wɪn/","zh":"不管你如何选择，你都赢不了","en":"","note":""},{"id":"phantom-of-the-opera-21-071","lineIndex":70,"speaker":"","original":"So, do you end your days with me","ipa":"/soʊ du ju ɛnd jʊɹ deɪz wɪð mi/","zh":"所以你愿与我共度余生","en":"","note":""},{"id":"phantom-of-the-opera-21-072","lineIndex":71,"speaker":"","original":"or do you send him to his grave?","ipa":"/ɔɹ du ju sɛnd hɪm tə hɪz ɡɹeɪv/","zh":"还是愿意送他进坟墓？","en":"","note":""},{"id":"phantom-of-the-opera-21-073","lineIndex":72,"speaker":"","original":"Why make her lie to you, to save me?","ipa":"/waɪ meɪk hɜ laɪ tə ju tə seɪv mi/","zh":"何苦逼她为了救我而言不由衷？","en":"","note":""},{"id":"phantom-of-the-opera-21-074","lineIndex":73,"speaker":"","original":"Angel of Music...","ipa":"/eɪndʒəl ʌv mjuzɪk/","zh":"音乐天使","en":"","note":""},{"id":"phantom-of-the-opera-21-075","lineIndex":74,"speaker":"","original":"Past the point of no return -","ipa":"/pæst ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"越过了不归点","en":"","note":""},{"id":"phantom-of-the-opera-21-076","lineIndex":75,"speaker":"","original":"For pity's sake","ipa":"/fɔɹ pɪɾiz seɪk/","zh":"为了怜悯","en":"","note":""},{"id":"phantom-of-the-opera-21-077","lineIndex":76,"speaker":"","original":"Christine, say no!","ipa":"/kɹɪstin seɪ noʊ/","zh":"克莉丝汀，说不","en":"","note":""},{"id":"phantom-of-the-opera-21-078","lineIndex":77,"speaker":"","original":"...who deserves this?","ipa":"/hu dɪzɜvz ðɪs/","zh":"谁理该得到这种待遇？","en":"","note":""},{"id":"phantom-of-the-opera-21-079","lineIndex":78,"speaker":"","original":"... the final threshold...","ipa":"/ðə faɪnəl θɹɛʃoʊld/","zh":"最后的门槛","en":"","note":""},{"id":"phantom-of-the-opera-21-080","lineIndex":79,"speaker":"","original":"Don't throw your life away for my sake!","ipa":"/doʊnt θɹoʊ jʊɹ laɪf ɐweɪ fɔɹ maɪ seɪk/","zh":"别因我而抛弃了你的人生","en":"","note":""},{"id":"phantom-of-the-opera-21-081","lineIndex":80,"speaker":"","original":"When will you see reason...?","ipa":"/wɛn wɪl ju si ɹizən/","zh":"你什么时候能看到","en":"","note":""},{"id":"phantom-of-the-opera-21-082","lineIndex":81,"speaker":"","original":"His life is now the prize which you must earn!","ipa":"/hɪz laɪf ɪz naʊ ðə pɹaɪz wɪtʃ ju mʌst ɜn/","zh":"现在他的命是你必须争取的奖赏","en":"","note":""},{"id":"phantom-of-the-opera-21-083","lineIndex":82,"speaker":"","original":"I fought so hard to free you...","ipa":"/aɪ fɔt soʊ hɑɹd tə fɹi ju/","zh":"我为了解救你如此拼命","en":"","note":""},{"id":"phantom-of-the-opera-21-084","lineIndex":83,"speaker":"","original":"Angel of Music...","ipa":"/eɪndʒəl ʌv mjuzɪk/","zh":"音乐天使","en":"","note":""},{"id":"phantom-of-the-opera-21-085","lineIndex":84,"speaker":"","original":"You've passed the point of no return...","ipa":"/juv pæst ðə pɔɪnt ʌv noʊ ɹᵻtɜn/","zh":"你已越过了不归点","en":"","note":""},{"id":"phantom-of-the-opera-21-086","lineIndex":85,"speaker":"","original":"... you deceived me.","ipa":"/ju dᵻsivd mi/","zh":"你欺骗了我","en":"","note":""},{"id":"phantom-of-the-opera-21-087","lineIndex":86,"speaker":"","original":"I gave my mind blindly.","ipa":"/aɪ ɡeɪv maɪ maɪnd blaɪndli/","zh":"我盲目地付出了真心","en":"","note":""},{"id":"phantom-of-the-opera-21-088","lineIndex":87,"speaker":"","original":"You try my patience - make your choice!","ipa":"/ju tɹaɪ maɪ peɪʃəns meɪk jʊɹ tʃɔɪs/","zh":"你在考验我的耐性，作出选择！","en":"","note":""},{"id":"phantom-of-the-opera-21-089","lineIndex":88,"speaker":"","original":"Pitiful creature of darkness...","ipa":"/pɪɾifəl kɹitʃɚɹ ʌv dɑɹknəs/","zh":"可悲的黑暗生物","en":"","note":""},{"id":"phantom-of-the-opera-21-090","lineIndex":89,"speaker":"","original":"What kind of life have you known?","ipa":"/wʌt kaɪnd ʌv laɪf hæv ju noʊn/","zh":"你懂得哪种叫生活？","en":"","note":""},{"id":"phantom-of-the-opera-21-091","lineIndex":90,"speaker":"","original":"God give me courage to show you you are not alone...","ipa":"/ɡɑd ɡɪv mi kɜɹɪdʒ tə ʃoʊ ju ju ɑɹ nɑt ɐloʊn/","zh":"上帝赐我勇气向你彰示，你并非孤独一人","en":"","note":""},{"id":"phantom-of-the-opera-21-092","lineIndex":91,"speaker":"","original":"Hunt out this animal, who runs to ground!","ipa":"/hʌnt aʊt ðɪs ænɪməl hu ɹʌnz tə ɡɹaʊnd/","zh":"循线追查凶手，务必要找到他","en":"","note":""},{"id":"phantom-of-the-opera-21-093","lineIndex":92,"speaker":"","original":"Too long he's preyed on us","ipa":"/tu lɔŋ hiz pɹeɪd ɔn ʌs/","zh":"他折磨我们太久了","en":"","note":""},{"id":"phantom-of-the-opera-21-094","lineIndex":93,"speaker":"","original":"but now we know, the phantom of the opera is there","ipa":"/bʌt naʊ wi noʊ ðə fæntəm ʌvðɪ ɑpɚɹə ɪz ðɛɹ/","zh":"但现在我们知道，剧院魅影就在那里","en":"","note":""},{"id":"phantom-of-the-opera-21-095","lineIndex":94,"speaker":"","original":"deep down inside!","ipa":"/dip daʊn ɪnsaɪd/","zh":"地窖深处","en":"","note":""},{"id":"phantom-of-the-opera-21-096","lineIndex":95,"speaker":"","original":"Take her - forget me - forget all of this...","ipa":"/teɪk hɜ fɚɡɛt mi fɚɡɛt ɔl ʌv ðɪs/","zh":"带她走，忘了我，忘了这一切","en":"","note":""},{"id":"phantom-of-the-opera-21-097","lineIndex":96,"speaker":"","original":"Leave me alone - forget all you've seen...","ipa":"/liv mi ɐloʊn fɚɡɛt ɔl juv sin/","zh":"别管我，忘了你们所见的一切.","en":"","note":""},{"id":"phantom-of-the-opera-21-098","lineIndex":97,"speaker":"","original":"Go now - don't let them find you!","ipa":"/ɡoʊ naʊ doʊnt lɛt ðɛm faɪnd ju/","zh":"快走，别让他们发现你们","en":"","note":""},{"id":"phantom-of-the-opera-21-099","lineIndex":98,"speaker":"","original":"Take the boat - leave me know, swear never to tell","ipa":"/teɪk ðə boʊt liv mi noʊ swɛɹ nɛvɚ tə tɛl/","zh":"划这艘船走，向我保证绝口不说出去","en":"","note":""},{"id":"phantom-of-the-opera-21-100","lineIndex":99,"speaker":"","original":"the secrets you know, of the angel in hell","ipa":"/ðə sikɹᵻts ju noʊ ʌvðɪ eɪndʒəl ɪn hɛl/","zh":"你们所知道的秘密--地狱天使！","en":"","note":""},{"id":"phantom-of-the-opera-21-101","lineIndex":100,"speaker":"","original":"GO NOW!","ipa":"/ɡoʊ naʊ/","zh":"快走！","en":"","note":""},{"id":"phantom-of-the-opera-21-102","lineIndex":101,"speaker":"","original":"GO NOW AND LEAVE ME!","ipa":"/ɡoʊ naʊ ænd liv mi/","zh":"快走！别管我！","en":"","note":""},{"id":"phantom-of-the-opera-21-103","lineIndex":102,"speaker":"","original":"Masquerade...","ipa":"/mæskɚɹeɪd/","zh":"化妆舞会","en":"","note":""},{"id":"phantom-of-the-opera-21-104","lineIndex":103,"speaker":"","original":"Paper faces on parade...","ipa":"/peɪpɚ feɪsᵻz ɔn pɚɹeɪd/","zh":"遮蔽的面孔成群结队","en":"","note":""},{"id":"phantom-of-the-opera-21-105","lineIndex":104,"speaker":"","original":"Masquerade...","ipa":"/mæskɚɹeɪd/","zh":"化妆舞会","en":"","note":""},{"id":"phantom-of-the-opera-21-106","lineIndex":105,"speaker":"","original":"Hide your face so the world will never find you...","ipa":"/haɪd jʊɹ feɪs soʊ ðə wɜld wɪl nɛvɚ faɪnd ju/","zh":"遮住面容，世人绝不会发现你","en":"","note":""},{"id":"phantom-of-the-opera-21-107","lineIndex":106,"speaker":"","original":"Christine, I love you...","ipa":"/kɹɪstin aɪ lʌv ju/","zh":"克莉丝汀，我爱你","en":"","note":""},{"id":"phantom-of-the-opera-21-108","lineIndex":107,"speaker":"","original":"Say you'll share with me, one love, one lifetime...","ipa":"/seɪ jul ʃɛɹ wɪð mi wʌn lʌv wʌn laɪftaɪm/","zh":"说你愿与我共享一份爱情，一生一世","en":"","note":""},{"id":"phantom-of-the-opera-21-109","lineIndex":108,"speaker":"","original":"Say the word and I will follow you...","ipa":"/seɪ ðə wɜd ænd aɪ wɪl fɑloʊ ju/","zh":"说出这句话，我便会跟随你","en":"","note":""},{"id":"phantom-of-the-opera-21-110","lineIndex":109,"speaker":"","original":"Share each day with me each night each morning...","ipa":"/ʃˈɛɹ ˈiːtʃ dˈeɪ wɪð mˌiː ˈiːtʃ nˈaɪt ˈiːtʃ mˈɔːɹnɪŋ/","zh":"与我共享每一天每一个昼夜晨昏","en":"","note":""},{"id":"phantom-of-the-opera-21-113","lineIndex":110,"speaker":"","original":"You alone can make my song take flight -","ipa":"/ju ɐloʊn kæn meɪk maɪ sɔŋ teɪk flaɪt/","zh":"唯有你能令我的歌声飞扬","en":"","note":""},{"id":"phantom-of-the-opera-21-114","lineIndex":111,"speaker":"","original":"it's over now, the music of the night!","ipa":"/ɪts oʊvɚ naʊ ðə mjuzɪk ʌvðə naɪt/","zh":"现在结束了！夜之乐章！","en":"","note":""}],"sourceOrder":21,"displayOrder":18}];
